## Next Steps
${context.nextSteps.map(step => `- ${step}`).join('\n') || '- No next steps defined'}

## Session Notes
${context.sessionNotes || 'No session notes available'}
`;

    const exportFile = path.join(process.cwd(), `context-export-${Date.now()}.md`);
