#!/usr/bin/env node

const { Command } = require('commander');
const WebBuilder = require('./builders/web-builder');
const V3ToV4Upgrader = require('./upgraders/v3-to-v4-upgrader');
const IdeSetup = require('./installer/lib/ide-setup');
const { 
  discoverFiles, 
  aggregateFileContents, 
  generateXMLOutput, 
  calculateStatistics,
  filterFiles 
} = require('./flattener/main');
const path = require('path');

const program = new Command();

program
  .name('bmad-build')
  .description('BMad-Method build tool for creating web bundles')
  .version('4.0.0');

program
  .command('build')
  .description('Build web bundles for agents and teams')
  .option('-a, --agents-only', 'Build only agent bundles')
  .option('-t, --teams-only', 'Build only team bundles')
  .option('-e, --expansions-only', 'Build only expansion pack bundles')
  .option('--no-expansions', 'Skip building expansion packs')
  .option('--no-clean', 'Skip cleaning output directories')
  .action(async (options) => {
    const builder = new WebBuilder({
      rootDir: process.cwd()
    });

    try {
      if (options.clean) {
        console.log('Cleaning output directories...');
        await builder.cleanOutputDirs();
      }

      if (options.expansionsOnly) {
        console.log('Building expansion pack bundles...');
        await builder.buildAllExpansionPacks({ clean: false });
      } else {
        if (!options.teamsOnly) {
          console.log('Building agent bundles...');
          await builder.buildAgents();
        }

        if (!options.agentsOnly) {
          console.log('Building team bundles...');
          await builder.buildTeams();
        }

        if (!options.noExpansions) {
          console.log('Building expansion pack bundles...');
          await builder.buildAllExpansionPacks({ clean: false });
        }
      }

      console.log('Build completed successfully!');
    } catch (error) {
      console.error('Build failed:', error.message);
      process.exit(1);
    }
  });

program
  .command('build:expansions')
  .description('Build web bundles for all expansion packs')
  .option('--expansion <name>', 'Build specific expansion pack only')
  .option('--no-clean', 'Skip cleaning output directories')
  .action(async (options) => {
    const builder = new WebBuilder({
      rootDir: process.cwd()
    });

    try {
      if (options.expansion) {
        console.log(`Building expansion pack: ${options.expansion}`);
        await builder.buildExpansionPack(options.expansion, { clean: options.clean });
      } else {
        console.log('Building all expansion packs...');
        await builder.buildAllExpansionPacks({ clean: options.clean });
      }

      console.log('Expansion pack build completed successfully!');
    } catch (error) {
      console.error('Expansion pack build failed:', error.message);
      process.exit(1);
    }
  });

program
  .command('list:agents')
  .description('List all available agents')
  .action(async () => {
    const builder = new WebBuilder({ rootDir: process.cwd() });
    const agents = await builder.resolver.listAgents();
    console.log('Available agents:');
    agents.forEach(agent => console.log(`  - ${agent}`));
  });

program
  .command('list:expansions')
  .description('List all available expansion packs')
  .action(async () => {
    const builder = new WebBuilder({ rootDir: process.cwd() });
    const expansions = await builder.listExpansionPacks();
    console.log('Available expansion packs:');
    expansions.forEach(expansion => console.log(`  - ${expansion}`));
  });

program
  .command('validate')
  .description('Validate agent and team configurations')
  .action(async () => {
    const builder = new WebBuilder({ rootDir: process.cwd() });
    try {
      // Validate by attempting to build all agents and teams
      const agents = await builder.resolver.listAgents();
      const teams = await builder.resolver.listTeams();

      console.log('Validating agents...');
      for (const agent of agents) {
        await builder.resolver.resolveAgentDependencies(agent);
        console.log(`  ✓ ${agent}`);
      }

      console.log('\nValidating teams...');
      for (const team of teams) {
        await builder.resolver.resolveTeamDependencies(team);
        console.log(`  ✓ ${team}`);
      }

      console.log('\nAll configurations are valid!');
    } catch (error) {
      console.error('Validation failed:', error.message);
      process.exit(1);
    }
  });

program
  .command('upgrade')
  .description('Upgrade a BMad-Method V3 project to V4')
  .option('-p, --project <path>', 'Path to V3 project (defaults to current directory)')
  .option('--dry-run', 'Show what would be changed without making changes')
  .option('--no-backup', 'Skip creating backup (not recommended)')
  .action(async (options) => {
    const upgrader = new V3ToV4Upgrader();
    await upgrader.upgrade({
      projectPath: options.project,
      dryRun: options.dryRun,
      backup: options.backup
    });
  });

program
  .command('flatten')
  .description('Flatten codebase into a single XML file for AI analysis')
  .option('-o, --output <path>', 'Output file path', 'flattened-codebase.xml')
  .action(async (options) => {
    console.log(`Flattening codebase to: ${options.output}`);

    try {
      // Import ora dynamically
      const { default: ora } = await import('ora');
      const fs = require('fs-extra');

      // Start file discovery with spinner
      const discoverySpinner = ora('🔍 Discovering files...').start();
      const files = await discoverFiles(process.cwd());
      const filteredFiles = await filterFiles(files, process.cwd());
      discoverySpinner.succeed(`📁 Found ${filteredFiles.length} files to include`);

      // Process files with progress tracking
      console.log('Reading file contents');
      const processingSpinner = ora('📄 Processing files...').start();
      const aggregatedContent = await aggregateFileContents(filteredFiles, process.cwd(), processingSpinner);
      processingSpinner.succeed(`✅ Processed ${aggregatedContent.processedFiles}/${filteredFiles.length} files`);

      // Log processing results for test validation
      console.log(`Processed ${aggregatedContent.processedFiles}/${filteredFiles.length} files`);
      if (aggregatedContent.errors.length > 0) {
        console.log(`Errors: ${aggregatedContent.errors.length}`);
      }
      console.log(`Text files: ${aggregatedContent.textFiles.length}`);
      if (aggregatedContent.binaryFiles.length > 0) {
        console.log(`Binary files: ${aggregatedContent.binaryFiles.length}`);
      }

      // Generate XML output using streaming
      const xmlSpinner = ora('🔧 Generating XML output...').start();
      await generateXMLOutput(aggregatedContent, options.output);
      xmlSpinner.succeed('📝 XML generation completed');

      // Calculate and display statistics
      const outputStats = await fs.stat(options.output);
      const stats = calculateStatistics(aggregatedContent, outputStats.size);

      // Display completion summary
      console.log('\n📊 Completion Summary:');
      console.log(`✅ Successfully processed ${filteredFiles.length} files into ${options.output}`);
      console.log(`📁 Output file: ${path.resolve(options.output)}`);
      console.log(`📏 Total source size: ${stats.totalSize}`);
      console.log(`📄 Generated XML size: ${stats.xmlSize}`);
      console.log(`📝 Total lines of code: ${stats.totalLines.toLocaleString()}`);
      console.log(`🔢 Estimated tokens: ${stats.estimatedTokens}`);
      console.log(`📊 File breakdown: ${stats.textFiles} text, ${stats.binaryFiles} binary, ${stats.errorFiles} errors`);

    } catch (error) {
      console.error('❌ Critical error:', error.message);
      console.error('An unexpected error occurred.');
      process.exit(1);
    }
  });

program.parse();

#!/usr/bin/env node

// Load required modules
const fs = require('fs');
const path = require('path');
const yaml = require('js-yaml');

// Parse CLI arguments
const args = process.argv.slice(2);
const packId = args[0];
const bumpType = args[1] || 'minor';

// Validate arguments
if (!packId || args.length > 2) {
  console.log('Usage: node bump-expansion-version.js <expansion-pack-id> [major|minor|patch]');
  console.log('Default: minor');
  console.log('Example: node bump-expansion-version.js bmad-creator-tools patch');
  process.exit(1);
}

if (!['major', 'minor', 'patch'].includes(bumpType)) {
  console.error('Error: Bump type must be major, minor, or patch');
  process.exit(1);
}

// Version bump logic
function bumpVersion(currentVersion, type) {
  const [major, minor, patch] = currentVersion.split('.').map(Number);

  switch (type) {
    case 'major': return `${major + 1}.0.0`;
    case 'minor': return `${major}.${minor + 1}.0`;
    case 'patch': return `${major}.${minor}.${patch + 1}`;
    default: return currentVersion;
  }
}

// Main function to bump version
async function updateVersion() {
  const configPath = path.join(__dirname, '..', 'expansion-packs', packId, 'config.yaml');

  // Check if config exists
  if (!fs.existsSync(configPath)) {
    console.error(`Error: Expansion pack '${packId}' not found`);
    console.log('\nAvailable expansion packs:');

    const packsDir = path.join(__dirname, '..', 'expansion-packs');
    const entries = fs.readdirSync(packsDir, { withFileTypes: true });

    entries.forEach(entry => {
      if (entry.isDirectory() && !entry.name.startsWith('.')) {
        console.log(`  - ${entry.name}`);
      }
    });

    process.exit(1);
  }

  try {
    const configContent = fs.readFileSync(configPath, 'utf8');
    const config = yaml.load(configContent);

    const oldVersion = config.version || '1.0.0';
    const newVersion = bumpVersion(oldVersion, bumpType);

    config.version = newVersion;

    const updatedYaml = yaml.dump(config, { indent: 2 });
    fs.writeFileSync(configPath, updatedYaml);

    console.log(`✓ ${packId}: ${oldVersion} → ${newVersion}`);
    console.log(`\n✓ Successfully bumped ${packId} with ${bumpType} version bump`);
    console.log('\nNext steps:');
    console.log(`1. Test the changes`);
    console.log(`2. Commit: git add -A && git commit -m "chore: bump ${packId} version (${bumpType})"`);

  } catch (error) {
    console.error('Error updating version:', error.message);
    process.exit(1);
  }
}

updateVersion();

#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const yaml = require('js-yaml');

const args = process.argv.slice(2);
const bumpType = args[0] || 'minor'; // default to minor

if (!['major', 'minor', 'patch'].includes(bumpType)) {
  console.log('Usage: node bump-all-versions.js [major|minor|patch]');
  console.log('Default: minor');
  process.exit(1);
}

function bumpVersion(currentVersion, type) {
  const [major, minor, patch] = currentVersion.split('.').map(Number);

  switch (type) {
    case 'major':
      return `${major + 1}.0.0`;
    case 'minor':
      return `${major}.${minor + 1}.0`;
    case 'patch':
      return `${major}.${minor}.${patch + 1}`;
    default:
      return currentVersion;
  }
}

async function bumpAllVersions() {
  const updatedItems = [];

  // First, bump the core version (package.json)
  const packagePath = path.join(__dirname, '..', 'package.json');
  try {
    const packageContent = fs.readFileSync(packagePath, 'utf8');
    const packageJson = JSON.parse(packageContent);
    const oldCoreVersion = packageJson.version || '1.0.0';
    const newCoreVersion = bumpVersion(oldCoreVersion, bumpType);

    packageJson.version = newCoreVersion;

    fs.writeFileSync(packagePath, JSON.stringify(packageJson, null, 2) + '\n');

    updatedItems.push({ type: 'core', name: 'BMad Core', oldVersion: oldCoreVersion, newVersion: newCoreVersion });
    console.log(`✓ BMad Core (package.json): ${oldCoreVersion} → ${newCoreVersion}`);
  } catch (error) {
    console.error(`✗ Failed to update BMad Core: ${error.message}`);
  }

  // Then, bump all expansion packs
  const expansionPacksDir = path.join(__dirname, '..', 'expansion-packs');

  try {
    const entries = fs.readdirSync(expansionPacksDir, { withFileTypes: true });

    for (const entry of entries) {
      if (entry.isDirectory() && !entry.name.startsWith('.') && entry.name !== 'README.md') {
        const packId = entry.name;
        const configPath = path.join(expansionPacksDir, packId, 'config.yaml');

        if (fs.existsSync(configPath)) {
          try {
            const configContent = fs.readFileSync(configPath, 'utf8');
            const config = yaml.load(configContent);
            const oldVersion = config.version || '1.0.0';
            const newVersion = bumpVersion(oldVersion, bumpType);

            config.version = newVersion;

            const updatedYaml = yaml.dump(config, { indent: 2 });
            fs.writeFileSync(configPath, updatedYaml);

            updatedItems.push({ type: 'expansion', name: packId, oldVersion, newVersion });
            console.log(`✓ ${packId}: ${oldVersion} → ${newVersion}`);

          } catch (error) {
            console.error(`✗ Failed to update ${packId}: ${error.message}`);
          }
        }
      }
    }

    if (updatedItems.length > 0) {
      const coreCount = updatedItems.filter(i => i.type === 'core').length;
      const expansionCount = updatedItems.filter(i => i.type === 'expansion').length;

      console.log(`\n✓ Successfully bumped ${updatedItems.length} item(s) with ${bumpType} version bump`);
      if (coreCount > 0) console.log(`  - ${coreCount} core`);
      if (expansionCount > 0) console.log(`  - ${expansionCount} expansion pack(s)`);

      console.log('\nNext steps:');
      console.log('1. Test the changes');
      console.log('2. Commit: git add -A && git commit -m "chore: bump all versions (' + bumpType + ')"');
    } else {
      console.log('No items found to update');
    }

  } catch (error) {
    console.error('Error reading expansion packs directory:', error.message);
    process.exit(1);
  }
}

bumpAllVersions();

#!/usr/bin/env node

/**
 * BMad Method CLI - Direct execution wrapper for npx
 * This file ensures proper execution when run via npx from GitHub
 */

const { execSync } = require('child_process');
const path = require('path');
const fs = require('fs');

// Check if we're running in an npx temporary directory
const isNpxExecution = __dirname.includes('_npx') || __dirname.includes('.npm');

// If running via npx, we need to handle things differently
if (isNpxExecution) {
  // The actual bmad.js is in installer/bin/ (relative to tools directory)
  const bmadScriptPath = path.join(__dirname, 'installer', 'bin', 'bmad.js');

  // Verify the file exists
  if (!fs.existsSync(bmadScriptPath)) {
    console.error('Error: Could not find bmad.js at', bmadScriptPath);
    console.error('Current directory:', __dirname);
    process.exit(1);
  }

  // Execute with proper working directory
  try {
    execSync(`node "${bmadScriptPath}" ${process.argv.slice(2).join(' ')}`, {
      stdio: 'inherit',
      cwd: path.dirname(__dirname)
    });
  } catch (error) {
    // execSync will throw if the command exits with non-zero
    // But the stdio is inherited, so the error is already displayed
    process.exit(error.status || 1);
  }
} else {
  // Local execution - just require the installer directly
  require('./installer/bin/bmad.js');
}

""" Enhanced testing utilities for the RoS application.
This module provides comprehensive testing support including: - Database fixtures with proper isolation - Mock data factories - Performance testing helpers - API testing utilities """ import asyncio import pytest from datetime import datetime, timedelta, timezone from typing import Any, Dict, List, Optional, AsyncGenerator from unittest.mock import AsyncMock, MagicMock from sqlalchemy.ext.asyncio import AsyncSession import factory
from app.infrastructure.database.models.v2 import ( Ascendant, DungeonSession, DungeonTrial, DungeonProgress )
class AsyncFactory(factory.Factory): """Base factory for async model creation."""
@classmethod async def create_async(cls, **kwargs): """Create instance asynchronously.""" return cls.build(**kwargs)
@classmethod async def create_batch_async(cls, size: int, **kwargs): """Create multiple instances asynchronously.""" return [await cls.create_async(**kwargs) for _ in range(size)]
class AscendantFactory(AsyncFactory): """Factory for creating Ascendant test instances."""
class Meta: model = Ascendant
discord_user_id = factory.Sequence(lambda n: f"user_{n}") level = factory.Faker('random_int', min=1, max=100) xp = factory.LazyAttribute(lambda obj: obj.level * 1000) aura = factory.Faker('random_int', min=100, max=10000) shadow_essence = factory.Faker('random_int', min=0, max=1000) skill_points = factory.Faker('random_int', min=0, max=50) last_login = factory.LazyFunction(lambda: datetime.now(timezone.utc))
class DungeonSessionFactory(AsyncFactory): """Factory for creating DungeonSession test instances."""
class Meta: model = DungeonSession
ascendant_id = factory.SubFactory(AscendantFactory) level = factory.Faker('random_int', min=1, max=10) status = "active" created_at = factory.LazyFunction(lambda: datetime.now(timezone.utc)) expires_at = factory.LazyAttribute( lambda obj: obj.created_at + timedelta(hours=1) )
class DungeonTrialFactory(AsyncFactory): """Factory for creating DungeonTrial test instances."""
class Meta: model = DungeonTrial
session_id = factory.SubFactory(DungeonSessionFactory) trial_number = factory.Sequence(lambda n: n + 1) movement_id = factory.Faker('random_int', min=1, max=100) target_reps = factory.Faker('random_int', min=10, max=50) completed_reps = 0 status = "active"
class TestDataBuilder: """Builder pattern for creating complex test data scenarios."""
def __init__(self): self.data = {}
async def with_ascendant( self, discord_user_id: str = "test_user", level: int = 10, **kwargs ) -> 'TestDataBuilder': """Add an ascendant to the test data.""" ascendant = await AscendantFactory.create_async( discord_user_id=discord_user_id, level=level, **kwargs ) self.data['ascendant'] = ascendant return self
async def with_dungeon_session( self, level: int = 1, status: str = "active", **kwargs ) -> 'TestDataBuilder': """Add a dungeon session to the test data.""" if 'ascendant' not in self.data: await self.with_ascendant()
session = await DungeonSessionFactory.create_async( ascendant_id=self.data['ascendant'].discord_user_id, level=level, status=status, **kwargs ) self.data['dungeon_session'] = session return self
async def with_trials( self, count: int = 3, **kwargs ) -> 'TestDataBuilder': """Add trials to the dungeon session.""" if 'dungeon_session' not in self.data: await self.with_dungeon_session()
trials = await DungeonTrialFactory.create_batch_async( count, session_id=self.data['dungeon_session'].session_id, **kwargs ) self.data['trials'] = trials return self
def build(self) -> Dict[str, Any]: """Build and return the test data.""" return self.data.copy()
class MockAPIClient: """Mock API client for testing external service interactions."""
def __init__(self): self.responses = {} self.call_history = []
def set_response(self, endpoint: str, response: Any): """Set a mock response for an endpoint.""" self.responses[endpoint] = response
async def get(self, endpoint: str, **kwargs) -> Any: """Mock GET request.""" self.call_history.append(('GET', endpoint, kwargs)) return self.responses.get(endpoint, {})
async def post(self, endpoint: str, data: Any = None, **kwargs) -> Any: """Mock POST request.""" self.call_history.append(('POST', endpoint, data, kwargs)) return self.responses.get(endpoint, {})
def get_call_history(self) -> List[tuple]: """Get history of API calls.""" return self.call_history.copy()
def reset(self): """Reset mock state.""" self.responses.clear() self.call_history.clear()
class PerformanceTracker: """Track performance metrics during tests."""
def __init__(self): self.metrics = {} self.start_times = {}
def start_timer(self, name: str): """Start timing an operation.""" self.start_times[name] = asyncio.get_event_loop().time()
def end_timer(self, name: str) -> float: """End timing and record duration.""" if name not in self.start_times: raise ValueError(f"Timer '{name}' not started")
duration = asyncio.get_event_loop().time() - self.start_times[name] self.metrics[name] = duration del self.start_times[name] return duration
def get_metrics(self) -> Dict[str, float]: """Get all recorded metrics.""" return self.metrics.copy()
def assert_performance(self, name: str, max_duration: float): """Assert that an operation completed within time limit.""" if name not in self.metrics: raise ValueError(f"No metrics recorded for '{name}'")
actual_duration = self.metrics[name] assert actual_duration <= max_duration, ( f"Operation '{name}' took {actual_duration:.3f}s, " f"expected <= {max_duration:.3f}s" )
@pytest.fixture async def test_data_builder(): """Provide a test data builder.""" return TestDataBuilder()
@pytest.fixture def mock_api_client(): """Provide a mock API client.""" return MockAPIClient()
@pytest.fixture def performance_tracker(): """Provide a performance tracker.""" return PerformanceTracker()
@pytest.fixture async def mock_cache_service(): """Provide a mock cache service.""" cache = MagicMock() cache.get = AsyncMock(return_value=None) cache.set = AsyncMock(return_value=True) cache.delete = AsyncMock(return_value=True) cache.clear_pattern = AsyncMock(return_value=0) return cache
class DatabaseTestMixin: """Mixin for database testing utilities."""
@staticmethod async def count_records(session: AsyncSession, model) -> int: """Count records in a table.""" from sqlalchemy import select result = await session.execute(select(func.count(model.id))) return result.scalar()
@staticmethod async def clear_table(session: AsyncSession, model): """Clear all records from a table.""" from sqlalchemy import delete await session.execute(delete(model)) await session.commit()
@staticmethod async def assert_record_exists( session: AsyncSession, model, **filters ): """Assert that a record exists with given filters.""" from sqlalchemy import select query = select(model) for key, value in filters.items(): query = query.where(getattr(model, key) == value)
result = await session.execute(query) record = result.scalar_one_or_none() assert record is not None, f"No {model.__name__} found with filters: {filters}" return record
def async_test(func): """Decorator to run async test functions.""" def wrapper(*args, **kwargs): return asyncio.run(func(*args, **kwargs)) return wrapper
def pytest_configure(): """Configure pytest with custom markers.""" pytest.mark.integration = pytest.mark.integration pytest.mark.performance = pytest.mark.performance pytest.mark.slow = pytest.mark.slow

