logger = logging.getLogger(__name__)
class IncursionsCog(commands.Cog): """Shadow Incursions - Dynamic world events for fitness challenges"""
def __init__(self, bot): self.bot = bot self.manager = IncursionManager(bot) self.scheduler = IncursionScheduler(bot)
# Load settings when cog is ready self.bot.loop.create_task(self._initialize_scheduler())
async def _initialize_scheduler(self): """Initialize scheduler settings after bot is ready""" # Wait for bot to be ready and database to be available await self.bot.wait_until_ready()
# Small delay to ensure database pool is ready await asyncio.sleep(1)
try: await self.scheduler.load_settings() except Exception as e: logger.error(f"Error initializing scheduler settings: {e}")
@commands.command(name="incursions", aliases=["inc"]) async def view_incursions(self, ctx: commands.Context): """View active Shadow Incursions""" user = ctx.author try: embed = await IncursionPanel.render_embed(self.bot, user) view = await IncursionPanel.build_view(self.bot, user) await ctx.send(embed=embed, view=view) except Exception as e: import traceback tb = traceback.format_exc() embed = discord.Embed( title="❌ INCURSION ERROR", description=f"```\n{tb}\n```", color=discord.Color.red() ) await ctx.send(embed=embed)
@commands.command(name="incursion_admin", aliases=["inc_admin"]) @commands.is_owner() # Only bot owner can use this command async def incursion_admin(self, ctx: commands.Context, action: Optional[str] = None): """Admin commands for managing incursions. Usage: !incursion_admin [start|stop|status]""" # Delete the user's command message for cleaner chat try: await ctx.message.delete() except (discord.NotFound, discord.Forbidden): pass
if not action: embed = discord.Embed( title="🔧 Incursion Admin Commands", description="Available actions:\n• `!incursion_admin start` - Start a new incursion\n• `!incursion_admin stop` - Stop current incursion\n• `!incursion_admin status` - Check incursion status", color=discord.Color.blue() ) await ctx.send(embed=embed, delete_after=10) return
action = action.lower()
if action == "start": # Start a new incursion using the scheduler's force_spawn_incursion method try: incursion_id = await self.scheduler.force_spawn_incursion() if incursion_id: embed = discord.Embed( title="✅ Incursion Started", description=f"A new Shadow Incursion has been initiated! (ID: {incursion_id})", color=discord.Color.green() ) else: embed = discord.Embed( title="⚠️ Incursion Not Started", description="Could not start a new incursion.", color=discord.Color.orange() ) await ctx.send(embed=embed, delete_after=10) except Exception as e: embed = discord.Embed( title="❌ Error Starting Incursion", description=f"Error: {str(e)}", color=discord.Color.red() ) await ctx.send(embed=embed, delete_after=10)
elif action == "stop": # Stop current incursion by getting active incursions and completing them try: response = await api_client.get_active_incursions(ctx.author) active_incursions = response.get("incursions", [])
if active_incursions: # Complete the first active incursion incursion_id = active_incursions[0]["incursion_id"] result = await api_client.complete_incursion(ctx.author, incursion_id)
if result.get("success"): embed = discord.Embed( title="✅ Incursion Stopped", description=f"The incursion '{active_incursions[0]['title']}' has been ended.", color=discord.Color.green() ) else: embed = discord.Embed( title="⚠️ Error Stopping Incursion", description="Could not stop the incursion.", color=discord.Color.orange() ) else: embed = discord.Embed( title="⚠️ No Active Incursion", description="There is no active incursion to stop.", color=discord.Color.orange() ) await ctx.send(embed=embed, delete_after=10) except Exception as e: embed = discord.Embed( title="❌ Error Stopping Incursion", description=f"Error: {str(e)}", color=discord.Color.red() ) await ctx.send(embed=embed, delete_after=10)
elif action == "status": # Check incursion status try: response = await api_client.get_active_incursions(ctx.author) active_incursions = response.get("incursions", [])
if active_incursions: incursion = active_incursions[0] # Show first active incursion embed = discord.Embed( title="📊 Incursion Status", description=f"**Active Incursion:** {incursion['title']}\n**Type:** {incursion['incursion_type']}\n**Progress:** {incursion['current_reps']}/{incursion['target_reps']}\n**Expires:** <t:{int(incursion['expires_at'])}:R>", color=discord.Color.blue() ) else: embed = discord.Embed( title="📊 Incursion Status", description="No active incursions.", color=discord.Color.blue() ) await ctx.send(embed=embed, delete_after=15) except Exception as e: embed = discord.Embed( title="❌ Error Checking Status", description=f"Error: {str(e)}", color=discord.Color.red() ) await ctx.send(embed=embed, delete_after=10)
else: embed = discord.Embed( title="❌ Invalid Action", description="Valid actions: start, stop, status", color=discord.Color.red() ) await ctx.send(embed=embed, delete_after=10)
@commands.command(name="incursion_testing") @commands.is_owner() async def toggle_testing_mode(self, ctx, mode: str = None): """Toggle testing mode on/off""" if mode is None: # Show current status status = "enabled" if self.scheduler.testing_mode else "disabled" await ctx.send(f"Testing mode is currently **{status}**") return
mode = mode.lower() if mode in ["on", "enable", "true", "1"]: self.scheduler.set_testing_mode(True) await ctx.send("✅ Testing mode **enabled**\n- 1 minute spawn intervals\n- 100% spawn chance\n- 45 second incursion duration") elif mode in ["off", "disable", "false", "0"]: self.scheduler.set_testing_mode(False) await ctx.send("✅ Testing mode **disabled**\n- 2-3 minute spawn intervals\n- 2-3% spawn chance\n- 30 minutes to 3 hours duration") else: await ctx.send("❌ Invalid mode. Use: `on`, `off`, `enable`, `disable`, `true`, or `false`")
@commands.command(name="incursion_status") @commands.is_owner() async def scheduler_status(self, ctx): """Show detailed scheduler status""" status = "Running" if self.scheduler.is_running else "Stopped" testing = "Enabled" if self.scheduler.testing_mode else "Disabled"
