#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const yaml = require('js-yaml');
const { execSync } = require('child_process');

// Dynamic import for ES module
let chalk;

// Initialize ES modules
async function initializeModules() {
  if (!chalk) {
    chalk = (await import('chalk')).default;
  }
}

/**
 * YAML Formatter and Linter for BMad-Method
 * Formats and validates YAML files and YAML embedded in Markdown
 */

async function formatYamlContent(content, filename) {
  await initializeModules();
  try {
    // First try to fix common YAML issues
    let fixedContent = content
      // Fix "commands :" -> "commands:"
      .replace(/^(\s*)(\w+)\s+:/gm, '$1$2:')
      // Fix inconsistent list indentation
      .replace(/^(\s*)-\s{3,}/gm, '$1- ');

    // Skip auto-fixing for .roomodes files - they have special nested structure
    if (!filename.includes('.roomodes')) {
      fixedContent = fixedContent
        // Fix unquoted list items that contain special characters or multiple parts
        .replace(/^(\s*)-\s+(.*)$/gm, (match, indent, content) => {
          // Skip if already quoted
          if (content.startsWith('"') && content.endsWith('"')) {
            return match;
          }
          // If the content contains special YAML characters or looks complex, quote it
          // BUT skip if it looks like a proper YAML key-value pair (like "key: value")
          if ((content.includes(':') || content.includes('-') || content.includes('{') || content.includes('}')) && 
              !content.match(/^\w+:\s/)) {
            // Remove any existing quotes first, escape internal quotes, then add proper quotes
            const cleanContent = content.replace(/^["']|["']$/g, '').replace(/"/g, '\\"');
            return `${indent}- "${cleanContent}"`;
          }
          return match;
        });
    }

    // Debug: show what we're trying to parse
    if (fixedContent !== content) {
      console.log(chalk.blue(`🔧 Applied YAML fixes to ${filename}`));
    }

    // Parse and re-dump YAML to format it
    const parsed = yaml.load(fixedContent);
    const formatted = yaml.dump(parsed, {
      indent: 2,
      lineWidth: -1, // Disable line wrapping
      noRefs: true,
      sortKeys: false // Preserve key order
    });
    return formatted;
  } catch (error) {
    console.error(chalk.red(`❌ YAML syntax error in ${filename}:`), error.message);
    console.error(chalk.yellow(`💡 Try manually fixing the YAML structure first`));
    return null;
  }
}

async function processMarkdownFile(filePath) {
  await initializeModules();
  const content = fs.readFileSync(filePath, 'utf8');
  let modified = false;
  let newContent = content;

  // Fix untyped code blocks by adding 'text' type
  // Match ``` at start of line followed by newline, but only if it's an opening fence
  newContent = newContent.replace(/^```\n([\s\S]*?)\n```$/gm, '```text\n$1\n```');
  if (newContent !== content) {
    modified = true;
    console.log(chalk.blue(`🔧 Added 'text' type to untyped code blocks in ${filePath}`));
  }

  // Find YAML code blocks
  const yamlBlockRegex = /```ya?ml\n([\s\S]*?)\n```/g;
  let match;
  const replacements = [];

  while ((match = yamlBlockRegex.exec(newContent)) !== null) {
    const [fullMatch, yamlContent] = match;
    const formatted = await formatYamlContent(yamlContent, filePath);
    if (formatted !== null) {
      // Remove trailing newline that js-yaml adds
      const trimmedFormatted = formatted.replace(/\n$/, '');

      if (trimmedFormatted !== yamlContent) {
        modified = true;
        console.log(chalk.green(`✓ Formatted YAML in ${filePath}`));
      }

      replacements.push({
        start: match.index,
        end: match.index + fullMatch.length,
        replacement: `\`\`\`yaml\n${trimmedFormatted}\n\`\`\``
      });
    }
  }

  // Apply replacements in reverse order to maintain indices
  for (let i = replacements.length - 1; i >= 0; i--) {
    const { start, end, replacement } = replacements[i];
    newContent = newContent.slice(0, start) + replacement + newContent.slice(end);
  }

  if (modified) {
    fs.writeFileSync(filePath, newContent);
    return true;
  }
  return false;
}

async function processYamlFile(filePath) {
  await initializeModules();
  const content = fs.readFileSync(filePath, 'utf8');
  const formatted = await formatYamlContent(content, filePath);

  if (formatted === null) {
    return false; // Syntax error
  }

  if (formatted !== content) {
    fs.writeFileSync(filePath, formatted);
    return true;
  }
  return false;
}

async function lintYamlFile(filePath) {
  await initializeModules();
  try {
    // Use yaml-lint for additional validation
    execSync(`npx yaml-lint "${filePath}"`, { stdio: 'pipe' });
    return true;
  } catch (error) {
    console.error(chalk.red(`❌ YAML lint error in ${filePath}:`));
    console.error(error.stdout?.toString() || error.message);
    return false;
  }
}

async function main() {
  await initializeModules();
  const args = process.argv.slice(2);
  const glob = require('glob');

  if (args.length === 0) {
    console.error('Usage: node yaml-format.js <file1> [file2] ...');
    process.exit(1);
  }

  let hasErrors = false;
  let hasChanges = false;
  let filesProcessed = [];

  // Expand glob patterns and collect all files
  const allFiles = [];
  for (const arg of args) {
    if (arg.includes('*')) {
      // It's a glob pattern
      const matches = glob.sync(arg);
      allFiles.push(...matches);
    } else {
      // It's a direct file path
      allFiles.push(arg);
    }
  }

  for (const filePath of allFiles) {
    if (!fs.existsSync(filePath)) {
      // Skip silently for glob patterns that don't match anything
      if (!args.some(arg => arg.includes('*') && filePath === arg)) {
        console.error(chalk.red(`❌ File not found: ${filePath}`));
        hasErrors = true;
      }
      continue;
    }

    const ext = path.extname(filePath).toLowerCase();
    const basename = path.basename(filePath).toLowerCase();

    try {
      let changed = false;
      if (ext === '.md') {
        changed = await processMarkdownFile(filePath);
      } else if (ext === '.yaml' || ext === '.yml' || basename.includes('roomodes') || basename.includes('.yaml') || basename.includes('.yml')) {
        // Handle YAML files and special cases like .roomodes
        changed = await processYamlFile(filePath);

        // Also run linting
        const lintPassed = await lintYamlFile(filePath);
        if (!lintPassed) hasErrors = true;
      } else {
        // Skip silently for unsupported files
        continue;
      }

      if (changed) {
        hasChanges = true;
        filesProcessed.push(filePath);
      }
    } catch (error) {
      console.error(chalk.red(`❌ Error processing ${filePath}:`), error.message);
      hasErrors = true;
    }
  }

  if (hasChanges) {
    console.log(chalk.green(`\n✨ YAML formatting completed! Modified ${filesProcessed.length} files:`));
    filesProcessed.forEach(file => console.log(chalk.blue(`  📝 ${file}`)));
  }

  if (hasErrors) {
    console.error(chalk.red('\n💥 Some files had errors. Please fix them before committing.'));
    process.exit(1);
  }
}

if (require.main === module) {
  main().catch(error => {
    console.error('Error:', error);
    process.exit(1);
  });
}

module.exports = { formatYamlContent, processMarkdownFile, processYamlFile };

#!/usr/bin/env node

const fs = require('fs');
const { execSync } = require('child_process');
const path = require('path');

// Dynamic import for ES module
let chalk;

// Initialize ES modules
async function initializeModules() {
  if (!chalk) {
    chalk = (await import('chalk')).default;
  }
}

/**
 * Simple version bumping script for BMad-Method
 * Usage: node tools/version-bump.js [patch|minor|major]
 */

function getCurrentVersion() {
  const packageJson = JSON.parse(fs.readFileSync('package.json', 'utf8'));
  return packageJson.version;
}

async function bumpVersion(type = 'patch') {
  await initializeModules();

  const validTypes = ['patch', 'minor', 'major'];
  if (!validTypes.includes(type)) {
    console.error(chalk.red(`Invalid version type: ${type}. Use: ${validTypes.join(', ')}`));
    process.exit(1);
  }

  console.log(chalk.yellow('⚠️  Manual version bumping is disabled.'));
  console.log(chalk.blue('🤖 This project uses semantic-release for automated versioning.'));
  console.log('');
  console.log(chalk.bold('To create a new release, use conventional commits:'));
  console.log(chalk.cyan('  feat: new feature (minor version bump)'));
  console.log(chalk.cyan('  fix: bug fix (patch version bump)'));
  console.log(chalk.cyan('  feat!: breaking change (major version bump)'));
  console.log('');
  console.log(chalk.dim('Example: git commit -m "feat: add new installer features"'));
  console.log(chalk.dim('Then push to main branch to trigger automatic release.'));

  return null;
}

async function main() {
  await initializeModules();

  const type = process.argv[2] || 'patch';
  const currentVersion = getCurrentVersion();

  console.log(chalk.blue(`Current version: ${currentVersion}`));

  // Check if working directory is clean
  try {
    execSync('git diff-index --quiet HEAD --');
  } catch (error) {
    console.error(chalk.red('❌ Working directory is not clean. Commit your changes first.'));
    process.exit(1);
  }

  const newVersion = await bumpVersion(type);

  console.log(chalk.green(`\n🎉 Version bump complete!`));
  console.log(chalk.blue(`📦 ${currentVersion} → ${newVersion}`));
}

if (require.main === module) {
  main().catch(error => {
    console.error('Error:', error);
    process.exit(1);
  });
}

module.exports = { bumpVersion, getCurrentVersion };

#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const yaml = require('js-yaml');

const args = process.argv.slice(2);

if (args.length < 2) {
  console.log('Usage: node update-expansion-version.js <expansion-pack-id> <new-version>');
  console.log('Example: node update-expansion-version.js bmad-creator-tools 1.1.0');
  process.exit(1);
}

const [packId, newVersion] = args;

// Validate version format
if (!/^\d+\.\d+\.\d+$/.test(newVersion)) {
  console.error('Error: Version must be in format X.Y.Z (e.g., 1.2.3)');
  process.exit(1);
}

async function updateVersion() {
  try {
    // Update in config.yaml
    const configPath = path.join(__dirname, '..', 'expansion-packs', packId, 'config.yaml');

    if (!fs.existsSync(configPath)) {
      console.error(`Error: Expansion pack '${packId}' not found`);
      process.exit(1);
    }

    const configContent = fs.readFileSync(configPath, 'utf8');
    const config = yaml.load(configContent);
    const oldVersion = config.version || 'unknown';

    config.version = newVersion;

    const updatedYaml = yaml.dump(config, { indent: 2 });
    fs.writeFileSync(configPath, updatedYaml);

    console.log(`✓ Updated ${packId}/config.yaml: ${oldVersion} → ${newVersion}`);
    console.log(`\n✓ Successfully updated ${packId} to version ${newVersion}`);
    console.log('\nNext steps:');
    console.log('1. Test the changes');
    console.log('2. Commit: git add -A && git commit -m "chore: bump ' + packId + ' to v' + newVersion + '"');

  } catch (error) {
    console.error('Error updating version:', error.message);
    process.exit(1);
  }
}

updateVersion();

#!/usr/bin/env node

/**
 * Sync installer package.json version with main package.json
 * Used by semantic-release to keep versions in sync
 */

const fs = require('fs');
const path = require('path');

function syncInstallerVersion() {
  // Read main package.json
  const mainPackagePath = path.join(__dirname, '..', 'package.json');
  const mainPackage = JSON.parse(fs.readFileSync(mainPackagePath, 'utf8'));

  // Read installer package.json
  const installerPackagePath = path.join(__dirname, 'installer', 'package.json');
  const installerPackage = JSON.parse(fs.readFileSync(installerPackagePath, 'utf8'));

  // Update installer version to match main version
  installerPackage.version = mainPackage.version;

  // Write back installer package.json
  fs.writeFileSync(installerPackagePath, JSON.stringify(installerPackage, null, 2) + '\n');

  console.log(`Synced installer version to ${mainPackage.version}`);
}

// Run if called directly
if (require.main === module) {
  syncInstallerVersion();
}

module.exports = { syncInstallerVersion };

/**
 * Semantic-release plugin to sync installer package.json version
 */

const fs = require('fs');
const path = require('path');

// This function runs during the "prepare" step of semantic-release
function prepare(_, { nextRelease, logger }) {
  // Define the path to the installer package.json file
  const file = path.join(process.cwd(), 'tools/installer/package.json');

  // If the file does not exist, skip syncing and log a message
  if (!fs.existsSync(file)) return logger.log('Installer package.json not found, skipping');

  // Read and parse the package.json file
  const pkg = JSON.parse(fs.readFileSync(file, 'utf8'));

  // Update the version field with the next release version
  pkg.version = nextRelease.version;

  // Write the updated JSON back to the file
  fs.writeFileSync(file, JSON.stringify(pkg, null, 2) + '\n');

  // Log success message
  logger.log(`Synced installer package.json to version ${nextRelease.version}`);
}

// Export the prepare function so semantic-release can use it
module.exports = { prepare };

#!/usr/bin/env node

const { Command } = require('commander');
const WebBuilder = require('./builders/web-builder');
const V3ToV4Upgrader = require('./upgraders/v3-to-v4-upgrader');
const IdeSetup = require('./installer/lib/ide-setup');
const path = require('path');

const program = new Command();

program
  .name('bmad-build')
  .description('BMad-Method build tool for creating web bundles')
  .version('4.0.0');

program
  .command('build')
  .description('Build web bundles for agents and teams')
  .option('-a, --agents-only', 'Build only agent bundles')
  .option('-t, --teams-only', 'Build only team bundles')
  .option('-e, --expansions-only', 'Build only expansion pack bundles')
  .option('--no-expansions', 'Skip building expansion packs')
  .option('--no-clean', 'Skip cleaning output directories')
  .action(async (options) => {
    const builder = new WebBuilder({
      rootDir: process.cwd()
    });

    try {
      if (options.clean) {
        console.log('Cleaning output directories...');
        await builder.cleanOutputDirs();
      }

      if (options.expansionsOnly) {
        console.log('Building expansion pack bundles...');
        await builder.buildAllExpansionPacks({ clean: false });
      } else {
        if (!options.teamsOnly) {
          console.log('Building agent bundles...');
          await builder.buildAgents();
        }

        if (!options.agentsOnly) {
          console.log('Building team bundles...');
          await builder.buildTeams();
        }

        if (!options.noExpansions) {
          console.log('Building expansion pack bundles...');
          await builder.buildAllExpansionPacks({ clean: false });
        }
      }

      console.log('Build completed successfully!');
    } catch (error) {
      console.error('Build failed:', error.message);
      process.exit(1);
    }
  });

program
  .command('build:expansions')
  .description('Build web bundles for all expansion packs')
  .option('--expansion <name>', 'Build specific expansion pack only')
  .option('--no-clean', 'Skip cleaning output directories')
  .action(async (options) => {
    const builder = new WebBuilder({
      rootDir: process.cwd()
    });

    try {
      if (options.expansion) {
        console.log(`Building expansion pack: ${options.expansion}`);
        await builder.buildExpansionPack(options.expansion, { clean: options.clean });
      } else {
        console.log('Building all expansion packs...');
        await builder.buildAllExpansionPacks({ clean: options.clean });
      }

      console.log('Expansion pack build completed successfully!');
    } catch (error) {
      console.error('Expansion pack build failed:', error.message);
      process.exit(1);
    }
  });

program
  .command('list:agents')
  .description('List all available agents')
  .action(async () => {
    const builder = new WebBuilder({ rootDir: process.cwd() });
    const agents = await builder.resolver.listAgents();
    console.log('Available agents:');
    agents.forEach(agent => console.log(`  - ${agent}`));
  });

program
  .command('list:expansions')
  .description('List all available expansion packs')
  .action(async () => {
    const builder = new WebBuilder({ rootDir: process.cwd() });
    const expansions = await builder.listExpansionPacks();
    console.log('Available expansion packs:');
    expansions.forEach(expansion => console.log(`  - ${expansion}`));
  });

program
  .command('validate')
  .description('Validate agent and team configurations')
  .action(async () => {
    const builder = new WebBuilder({ rootDir: process.cwd() });
    try {
      // Validate by attempting to build all agents and teams
      const agents = await builder.resolver.listAgents();
      const teams = await builder.resolver.listTeams();

      console.log('Validating agents...');
      for (const agent of agents) {
        await builder.resolver.resolveAgentDependencies(agent);
        console.log(`  ✓ ${agent}`);
      }

      console.log('\nValidating teams...');
      for (const team of teams) {
        await builder.resolver.resolveTeamDependencies(team);
        console.log(`  ✓ ${team}`);
      }

      console.log('\nAll configurations are valid!');
    } catch (error) {
      console.error('Validation failed:', error.message);
      process.exit(1);
    }
  });

program
  .command('upgrade')
  .description('Upgrade a BMad-Method V3 project to V4')
  .option('-p, --project <path>', 'Path to V3 project (defaults to current directory)')
  .option('--dry-run', 'Show what would be changed without making changes')
  .option('--no-backup', 'Skip creating backup (not recommended)')
  .action(async (options) => {
    const upgrader = new V3ToV4Upgrader();
    await upgrader.upgrade({
      projectPath: options.project,
      dryRun: options.dryRun,
      backup: options.backup
    });
  });

program.parse();

#!/usr/bin/env node

// Load required modules
const fs = require('fs');
const path = require('path');
const yaml = require('js-yaml');

// Parse CLI arguments
const args = process.argv.slice(2);
const packId = args[0];
const bumpType = args[1] || 'minor';

// Validate arguments
if (!packId || args.length > 2) {
  console.log('Usage: node bump-expansion-version.js <expansion-pack-id> [major|minor|patch]');
  console.log('Default: minor');
  console.log('Example: node bump-expansion-version.js bmad-creator-tools patch');
  process.exit(1);
}

if (!['major', 'minor', 'patch'].includes(bumpType)) {
  console.error('Error: Bump type must be major, minor, or patch');
  process.exit(1);
}

// Version bump logic
function bumpVersion(currentVersion, type) {
  const [major, minor, patch] = currentVersion.split('.').map(Number);

  switch (type) {
    case 'major': return `${major + 1}.0.0`;
    case 'minor': return `${major}.${minor + 1}.0`;
    case 'patch': return `${major}.${minor}.${patch + 1}`;
    default: return currentVersion;
  }
}

// Main function to bump version
async function updateVersion() {
  const configPath = path.join(__dirname, '..', 'expansion-packs', packId, 'config.yaml');

  // Check if config exists
  if (!fs.existsSync(configPath)) {
    console.error(`Error: Expansion pack '${packId}' not found`);
    console.log('\nAvailable expansion packs:');

    const packsDir = path.join(__dirname, '..', 'expansion-packs');
    const entries = fs.readdirSync(packsDir, { withFileTypes: true });

    entries.forEach(entry => {
      if (entry.isDirectory() && !entry.name.startsWith('.')) {
        console.log(`  - ${entry.name}`);
      }
    });

    process.exit(1);
  }

  try {
    const configContent = fs.readFileSync(configPath, 'utf8');
    const config = yaml.load(configContent);

    const oldVersion = config.version || '1.0.0';
    const newVersion = bumpVersion(oldVersion, bumpType);

    config.version = newVersion;

    const updatedYaml = yaml.dump(config, { indent: 2 });
    fs.writeFileSync(configPath, updatedYaml);

    console.log(`✓ ${packId}: ${oldVersion} → ${newVersion}`);
    console.log(`\n✓ Successfully bumped ${packId} with ${bumpType} version bump`);
    console.log('\nNext steps:');
    console.log(`1. Test the changes`);
    console.log(`2. Commit: git add -A && git commit -m "chore: bump ${packId} version (${bumpType})"`);

  } catch (error) {
    console.error('Error updating version:', error.message);
    process.exit(1);
  }
}

updateVersion();

#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const yaml = require('js-yaml');

const args = process.argv.slice(2);
const bumpType = args[0] || 'minor'; // default to minor

if (!['major', 'minor', 'patch'].includes(bumpType)) {
  console.log('Usage: node bump-all-versions.js [major|minor|patch]');
  console.log('Default: minor');
  process.exit(1);
}

function bumpVersion(currentVersion, type) {
  const [major, minor, patch] = currentVersion.split('.').map(Number);

  switch (type) {
    case 'major':
      return `${major + 1}.0.0`;
    case 'minor':
      return `${major}.${minor + 1}.0`;
    case 'patch':
      return `${major}.${minor}.${patch + 1}`;
    default:
      return currentVersion;
  }
}

async function bumpAllVersions() {
  const updatedItems = [];

  // First, bump the core version (package.json)
  const packagePath = path.join(__dirname, '..', 'package.json');
  try {
    const packageContent = fs.readFileSync(packagePath, 'utf8');
    const packageJson = JSON.parse(packageContent);
    const oldCoreVersion = packageJson.version || '1.0.0';
    const newCoreVersion = bumpVersion(oldCoreVersion, bumpType);

    packageJson.version = newCoreVersion;

    fs.writeFileSync(packagePath, JSON.stringify(packageJson, null, 2) + '\n');

    updatedItems.push({ type: 'core', name: 'BMad Core', oldVersion: oldCoreVersion, newVersion: newCoreVersion });
    console.log(`✓ BMad Core (package.json): ${oldCoreVersion} → ${newCoreVersion}`);
  } catch (error) {
    console.error(`✗ Failed to update BMad Core: ${error.message}`);
  }

  // Then, bump all expansion packs
  const expansionPacksDir = path.join(__dirname, '..', 'expansion-packs');

  try {
    const entries = fs.readdirSync(expansionPacksDir, { withFileTypes: true });

    for (const entry of entries) {
      if (entry.isDirectory() && !entry.name.startsWith('.') && entry.name !== 'README.md') {
        const packId = entry.name;
        const configPath = path.join(expansionPacksDir, packId, 'config.yaml');

        if (fs.existsSync(configPath)) {
          try {
            const configContent = fs.readFileSync(configPath, 'utf8');
            const config = yaml.load(configContent);
            const oldVersion = config.version || '1.0.0';
            const newVersion = bumpVersion(oldVersion, bumpType);

            config.version = newVersion;

            const updatedYaml = yaml.dump(config, { indent: 2 });
            fs.writeFileSync(configPath, updatedYaml);

            updatedItems.push({ type: 'expansion', name: packId, oldVersion, newVersion });
            console.log(`✓ ${packId}: ${oldVersion} → ${newVersion}`);

          } catch (error) {
            console.error(`✗ Failed to update ${packId}: ${error.message}`);
          }
        }
      }
    }

    if (updatedItems.length > 0) {
      const coreCount = updatedItems.filter(i => i.type === 'core').length;
      const expansionCount = updatedItems.filter(i => i.type === 'expansion').length;

      console.log(`\n✓ Successfully bumped ${updatedItems.length} item(s) with ${bumpType} version bump`);
      if (coreCount > 0) console.log(`  - ${coreCount} core`);
      if (expansionCount > 0) console.log(`  - ${expansionCount} expansion pack(s)`);

      console.log('\nNext steps:');
      console.log('1. Test the changes');
      console.log('2. Commit: git add -A && git commit -m "chore: bump all versions (' + bumpType + ')"');
    } else {
      console.log('No items found to update');
    }

  } catch (error) {
    console.error('Error reading expansion packs directory:', error.message);
    process.exit(1);
  }
}

bumpAllVersions();

#!/usr/bin/env node

/**
 * BMad Method CLI - Direct execution wrapper for npx
 * This file ensures proper execution when run via npx from GitHub
 */

const { execSync } = require('child_process');
const path = require('path');
const fs = require('fs');

// Check if we're running in an npx temporary directory
const isNpxExecution = __dirname.includes('_npx') || __dirname.includes('.npm');

// If running via npx, we need to handle things differently
if (isNpxExecution) {
  const args = process.argv.slice(2);

  // Use the installer for all commands
  const bmadScriptPath = path.join(__dirname, 'installer', 'bin', 'bmad.js');

  if (!fs.existsSync(bmadScriptPath)) {
    console.error('Error: Could not find bmad.js at', bmadScriptPath);
    console.error('Current directory:', __dirname);
    process.exit(1);
  }

  try {
    execSync(`node "${bmadScriptPath}" ${args.join(' ')}`, {
      stdio: 'inherit',
      cwd: path.dirname(__dirname)
    });
  } catch (error) {
    process.exit(error.status || 1);
  }
} else {
  // Local execution - use installer for all commands
  require('./installer/bin/bmad.js');
}

"""
Enhanced validation utilities for the application.

This module provides comprehensive validation patterns including:
- Custom Pydantic validators
- Business rule validation
- Input sanitization
- Type safety helpers
"""
import re
from datetime import datetime, timezone
from typing import Any, Dict, List, Optional, Union, Type, get_type_hints
from pydantic import validator, BaseModel, Field
from pydantic.validators import str_validator
from functools import wraps

from app.core.exceptions import ValidationError


class DiscordUserIdValidator:
    """Validator for Discord user IDs."""

    @staticmethod
    def validate_discord_user_id(v: Any) -> str:
        """Validate Discord user ID format."""
        if not v:
            raise ValueError("Discord user ID is required")

        # Convert to string if integer
        v_str = str(v)

        # Discord user IDs are 17-19 digit numbers
        if not re.match(r'^\d{17,19}$', v_str):
            raise ValueError("Invalid Discord user ID format")

        return v_str


class GameValueValidator:
    """Validator for game-specific values."""

    @staticmethod
    def validate_level(v: int) -> int:
        """Validate player level."""
        if not isinstance(v, int):
            raise ValueError("Level must be an integer")

        if v < 1:
            raise ValueError("Level must be at least 1")

        if v > 1000:  # Reasonable upper bound
            raise ValueError("Level cannot exceed 1000")

        return v

    @staticmethod
    def validate_xp(v: int) -> int:
        """Validate experience points."""
        if not isinstance(v, int):
            raise ValueError("XP must be an integer")

        if v < 0:
            raise ValueError("XP cannot be negative")

        if v > 1_000_000_000:  # 1 billion max
            raise ValueError("XP value too large")

        return v

    @staticmethod
    def validate_aura(v: int) -> int:
        """Validate aura value."""
        if not isinstance(v, int):
            raise ValueError("Aura must be an integer")

        if v < 0:
            raise ValueError("Aura cannot be negative")

        if v > 100_000:  # Reasonable upper bound
            raise ValueError("Aura value too large")

        return v

    @staticmethod
    def validate_dungeon_level(v: int) -> int:
        """Validate dungeon level."""
        if not isinstance(v, int):
            raise ValueError("Dungeon level must be an integer")

        if v < 1:
            raise ValueError("Dungeon level must be at least 1")

        if v > 100:  # Current max dungeon level
            raise ValueError("Dungeon level cannot exceed 100")

        return v


class StringSanitizer:
    """String sanitization utilities."""

    @staticmethod
    def sanitize_user_input(v: str, max_length: int = 1000) -> str:
        """Sanitize user input strings."""
        if not isinstance(v, str):
            v = str(v)

        # Strip whitespace
        v = v.strip()

        # Check length
        if len(v) > max_length:
            raise ValueError(f"Input too long (max {max_length} characters)")

        # Remove null bytes and control characters (except newlines and tabs)
        v = re.sub(r'[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]', '', v)

        return v

    @staticmethod
    def sanitize_discord_message(v: str) -> str:
        """Sanitize Discord message content."""
        v = StringSanitizer.sanitize_user_input(v, max_length=2000)

        # Remove Discord markdown that could be problematic
        # Keep basic formatting but remove @everyone/@here mentions
        v = re.sub(r'@(everyone|here)', '@\u200b\\1', v)  # Zero-width space

        return v


class BusinessRuleValidator:
    """Business rule validation utilities."""

    @staticmethod
    def validate_dungeon_entry_requirements(
        player_level: int,
        player_aura: int,
        dungeon_level: int,
        required_aura: int
    ) -> None:
        """Validate if player meets dungeon entry requirements."""
        errors = []

        # Check level requirements (must be at least dungeon level)
        if player_level < dungeon_level:
            errors.append(f"Player level {player_level} is below required level {dungeon_level}")

        # Check aura requirements
        if player_aura < required_aura:
            errors.append(f"Player aura {player_aura} is below required aura {required_aura}")

        if errors:
            raise ValidationError(
                "Dungeon entry requirements not met",
                error_code="DUNGEON_REQUIREMENTS_NOT_MET",
                context={"errors": errors}
            )

    @staticmethod
    def validate_skill_unlock_requirements(
        player_stats: Dict[str, int],
        required_stats: Dict[str, int]
    ) -> None:
        """Validate if player meets skill unlock requirements."""
        errors = []

        for stat_name, required_value in required_stats.items():
            player_value = player_stats.get(stat_name, 0)
            if player_value < required_value:
                errors.append(
                    f"{stat_name}: {player_value}/{required_value}"
                )

        if errors:
            raise ValidationError(
                "Skill unlock requirements not met",
                error_code="SKILL_REQUIREMENTS_NOT_MET",
                context={"missing_requirements": errors}
            )

    @staticmethod
    def validate_session_timeout(
        session_created_at: datetime,
        timeout_hours: int = 1
    ) -> None:
        """Validate if session has not timed out."""
        if not session_created_at.tzinfo:
            session_created_at = session_created_at.replace(tzinfo=timezone.utc)

        now = datetime.now(timezone.utc)
        elapsed_hours = (now - session_created_at).total_seconds() / 3600

        if elapsed_hours > timeout_hours:
            raise ValidationError(
                f"Session expired ({elapsed_hours:.1f}h > {timeout_hours}h)",
                error_code="SESSION_EXPIRED",
                context={
                    "created_at": session_created_at.isoformat(),
                    "elapsed_hours": elapsed_hours,
                    "timeout_hours": timeout_hours
                }
            )


def validate_model_fields(model_class: Type[BaseModel]):
    """Decorator to add comprehensive field validation to Pydantic models."""

    def decorator(cls):
        # Get type hints for the model
        type_hints = get_type_hints(cls)

        # Add validators based on field types and names
        for field_name, field_type in type_hints.items():
            if hasattr(cls, field_name):
                field_info = getattr(cls, field_name)

                # Skip if not a Field
                if not isinstance(field_info, type(Field())):
                    continue

                # Add Discord user ID validation
                if 'discord_user_id' in field_name.lower():
                    setattr(cls, f'validate_{field_name}', 
                           validator(field_name, allow_reuse=True)(
                               DiscordUserIdValidator.validate_discord_user_id
                           ))

                # Add level validation
                elif 'level' in field_name.lower():
                    setattr(cls, f'validate_{field_name}',
                           validator(field_name, allow_reuse=True)(
                               GameValueValidator.validate_level
                           ))

                # Add XP validation
                elif field_name.lower() in ['xp', 'experience']:
                    setattr(cls, f'validate_{field_name}',
                           validator(field_name, allow_reuse=True)(
                               GameValueValidator.validate_xp
                           ))

                # Add aura validation
                elif 'aura' in field_name.lower():
                    setattr(cls, f'validate_{field_name}',
                           validator(field_name, allow_reuse=True)(
                               GameValueValidator.validate_aura
                           ))

        return cls

    return decorator


def validate_request_data(
    data: Dict[str, Any],
    schema: Dict[str, Dict[str, Any]]
) -> Dict[str, Any]:
    """
    Validate request data against a schema.

    Args:
        data: The data to validate
        schema: Validation schema with field requirements

    Returns:
        Validated and sanitized data

    Raises:
        ValidationError: If validation fails
    """
    validated_data = {}
    errors = []

    for field_name, field_config in schema.items():
        field_value = data.get(field_name)
        is_required = field_config.get('required', False)
        field_type = field_config.get('type', str)
        min_value = field_config.get('min')
        max_value = field_config.get('max')
        pattern = field_config.get('pattern')

        # Check required fields
        if is_required and field_value is None:
            errors.append(f"Field '{field_name}' is required")
            continue

        # Skip validation for optional None values
        if field_value is None:
            validated_data[field_name] = None
            continue

        # Type validation
        try:
            if field_type == int:
                field_value = int(field_value)
            elif field_type == float:
                field_value = float(field_value)
            elif field_type == str:
                field_value = str(field_value).strip()
            elif field_type == bool:
                field_value = bool(field_value)
        except (ValueError, TypeError):
            errors.append(f"Field '{field_name}' must be of type {field_type.__name__}")
            continue

        # Range validation for numbers
        if isinstance(field_value, (int, float)):
            if min_value is not None and field_value < min_value:
                errors.append(f"Field '{field_name}' must be >= {min_value}")
                continue
            if max_value is not None and field_value > max_value:
                errors.append(f"Field '{field_name}' must be <= {max_value}")
                continue

        # Pattern validation for strings
        if isinstance(field_value, str) and pattern:
            if not re.match(pattern, field_value):
                errors.append(f"Field '{field_name}' does not match required pattern")
                continue

        # String sanitization
        if isinstance(field_value, str):
            try:
                field_value = StringSanitizer.sanitize_user_input(field_value)
            except ValueError as e:
                errors.append(f"Field '{field_name}': {str(e)}")
                continue

        validated_data[field_name] = field_value

    if errors:
        raise ValidationError(
            "Request validation failed",
            error_code="VALIDATION_FAILED",
            context={"field_errors": errors}
        )

    return validated_data


class ValidationMixin:
    """Mixin class to add validation methods to services."""

    def validate_discord_user_id(self, user_id: Any) -> str:
        """Validate Discord user ID."""
        return DiscordUserIdValidator.validate_discord_user_id(user_id)

    def validate_game_values(self, **kwargs) -> Dict[str, Any]:
        """Validate multiple game values."""
        validated = {}

        for key, value in kwargs.items():
            if 'level' in key.lower():
                validated[key] = GameValueValidator.validate_level(value)
            elif key.lower() in ['xp', 'experience']:
                validated[key] = GameValueValidator.validate_xp(value)
            elif 'aura' in key.lower():
                validated[key] = GameValueValidator.validate_aura(value)
            else:
                validated[key] = value

        return validated

    def sanitize_user_input(self, text: str, max_length: int = 1000) -> str:
        """Sanitize user input."""
        return StringSanitizer.sanitize_user_input(text, max_length)


# Export commonly used validators
__all__ = [
    'DiscordUserIdValidator',
    'GameValueValidator', 
    'StringSanitizer',
    'BusinessRuleValidator',
    'validate_model_fields',
    'validate_request_data',
    'ValidationMixin'
]

"""
Standardized API response handling utilities.

This module provides consistent response formatting, error handling,
and status management across all API endpoints.
"""
import logging
from typing import Any, Dict, Optional, List
from datetime import datetime
from fastapi import HTTPException, status
from fastapi.responses import JSONResponse

from app.core.exceptions import (
    RoSBaseException,
    ValidationError,
    BusinessLogicError,
    ResourceNotFoundError,
    InsufficientPermissionsError,
    ExternalServiceError,
    DatabaseError
)

logger = logging.getLogger(__name__)


class APIResponseHandler:
    """Handles standardized API responses and error formatting."""

    @staticmethod
    def success(
        data: Any = None,
        message: str = "Operation completed successfully",
        status_code: int = status.HTTP_200_OK
    ) -> JSONResponse:
        """Create a successful API response."""
        response_data = {
            "status": "success",
            "message": message,
            "data": data,
            "timestamp": datetime.utcnow().isoformat()
        }
        return JSONResponse(content=response_data, status_code=status_code)

    @staticmethod
    def created(
        data: Any = None,
        message: str = "Resource created successfully"
    ) -> JSONResponse:
        """Create a 201 Created response."""
        return APIResponseHandler.success(
            data=data,
            message=message,
            status_code=status.HTTP_201_CREATED
        )

    @staticmethod
    def error(
        message: str,
        error_code: Optional[str] = None,
        details: Optional[Dict[str, Any]] = None,
        status_code: int = status.HTTP_500_INTERNAL_SERVER_ERROR
    ) -> JSONResponse:
        """Create an error API response."""
        response_data = {
            "status": "error",
            "message": message,
            "error_code": error_code,
            "details": details,
            "timestamp": datetime.utcnow().isoformat()
        }

        # Log the error
        logger.error(
            f"API Error {status_code}: {message}",
            extra={
                "error_code": error_code,
                "details": details
            }
        )

        return JSONResponse(content=response_data, status_code=status_code)

    @staticmethod
    def validation_error(
        message: str,
        field_errors: Optional[Dict[str, List[str]]] = None
    ) -> JSONResponse:
        """Create a validation error response."""
        return APIResponseHandler.error(
            message=message,
            error_code="VALIDATION_ERROR",
            details={"field_errors": field_errors} if field_errors else None,
            status_code=status.HTTP_422_UNPROCESSABLE_ENTITY
        )

    @staticmethod
    def not_found(
        message: str = "Resource not found",
        resource_type: Optional[str] = None,
        resource_id: Optional[str] = None
    ) -> JSONResponse:
        """Create a 404 Not Found response."""
        details = {}
        if resource_type:
            details["resource_type"] = resource_type
        if resource_id:
            details["resource_id"] = resource_id

        return APIResponseHandler.error(
            message=message,
            error_code="RESOURCE_NOT_FOUND",
            details=details if details else None,
            status_code=status.HTTP_404_NOT_FOUND
        )

    @staticmethod
    def forbidden(
        message: str = "Access forbidden",
        required_permission: Optional[str] = None
    ) -> JSONResponse:
        """Create a 403 Forbidden response."""
        details = {}
        if required_permission:
            details["required_permission"] = required_permission

        return APIResponseHandler.error(
            message=message,
            error_code="ACCESS_FORBIDDEN",
            details=details if details else None,
            status_code=status.HTTP_403_FORBIDDEN
        )

    @staticmethod
    def handle_exception(exception: Exception) -> JSONResponse:
        """Convert exceptions to appropriate HTTP responses."""
        if isinstance(exception, ValidationError):
            return APIResponseHandler.validation_error(
                message=exception.message,
                field_errors=exception.context.get("field_errors")
            )

        elif isinstance(exception, ResourceNotFoundError):
            return APIResponseHandler.not_found(
                message=exception.message,
                resource_type=exception.context.get("resource_type"),
                resource_id=exception.context.get("resource_id")
            )

        elif isinstance(exception, InsufficientPermissionsError):
            return APIResponseHandler.forbidden(
                message=exception.message,
                required_permission=exception.context.get("required_permission")
            )

        elif isinstance(exception, BusinessLogicError):
            return APIResponseHandler.error(
                message=exception.message,
                error_code=exception.error_code or "BUSINESS_LOGIC_ERROR",
                details=exception.context,
                status_code=status.HTTP_400_BAD_REQUEST
            )

        elif isinstance(exception, (DatabaseError, ExternalServiceError)):
            return APIResponseHandler.error(
                message="Service temporarily unavailable",
                error_code=exception.error_code or "SERVICE_ERROR",
                status_code=status.HTTP_503_SERVICE_UNAVAILABLE
            )

        elif isinstance(exception, RoSBaseException):
            return APIResponseHandler.error(
                message=exception.message,
                error_code=exception.error_code,
                details=exception.context,
                status_code=status.HTTP_500_INTERNAL_SERVER_ERROR
            )

        else:
            # Log unexpected errors
            logger.exception("Unexpected error occurred", exc_info=exception)
            return APIResponseHandler.error(
                message="An unexpected error occurred",
                error_code="INTERNAL_ERROR",
                status_code=status.HTTP_500_INTERNAL_SERVER_ERROR
            )


class PaginatedResponseHandler:
    """Handles paginated API responses."""

    @staticmethod
    def paginate(
        items: List[Any],
        total: int,
        page: int,
        limit: int,
        message: str = "Data retrieved successfully"
    ) -> JSONResponse:
        """Create a paginated response."""
        pages = (total + limit - 1) // limit  # Ceiling division

        response_data = {
            "status": "success",
            "message": message,
            "data": {
                "items": items,
                "pagination": {
                    "total": total,
                    "page": page,
                    "limit": limit,
                    "pages": pages,
                    "has_next": page < pages,
                    "has_prev": page > 1
                }
            },
            "timestamp": datetime.utcnow().isoformat()
        }

        return JSONResponse(content=response_data, status_code=status.HTTP_200_OK)

