            description="Reduced cooldowns for 1 hour",
            effects={"cooldown_reduction": 0.5},
            stacks=1,
            expires_at=datetime.now() + timedelta(minutes=45),
            time_remaining=45
        )
    ]

    return BuffInventory(
        consumable_buffs=[],
