class WorkspaceSetup {
  constructor() {
    this.workspaceStructure = {
      '.workspace': {
        'sessions': {},
        'context': {},
        'handoffs': {},
        'decisions': {},
        'progress': {},
        'quality': {},
        'archive': {}
      }
