  async setupRoo(installDir, selectedAgent) {
    const agents = selectedAgent ? [selectedAgent] : await this.getAllAgentIds(installDir);

    // Check for existing .roomodes file in project root
    const roomodesPath = path.join(installDir, ".roomodes");
    let existingModes = [];
    let existingContent = "";

    if (await fileManager.pathExists(roomodesPath)) {
      existingContent = await fileManager.readFile(roomodesPath);
      // Parse existing modes to avoid duplicates
      const modeMatches = existingContent.matchAll(/- slug: ([\w-]+)/g);
      for (const match of modeMatches) {
        existingModes.push(match[1]);
      }
      console.log(chalk.yellow(`Found existing .roomodes file with ${existingModes.length} modes`));
    }

    // Create new modes content
    let newModesContent = "";

    // Load dynamic agent permissions from configuration
    const config = await this.loadIdeAgentConfig();
    const agentPermissions = config['roo-permissions'] || {};

    for (const agentId of agents) {
      // Skip if already exists
      // Check both with and without bmad- prefix to handle both cases
      const checkSlug = agentId.startsWith('bmad-') ? agentId : `bmad-${agentId}`;
      if (existingModes.includes(checkSlug)) {
        console.log(chalk.dim(`Skipping ${agentId} - already exists in .roomodes`));
        continue;
      }

      // Read agent file to extract all information
      const agentPath = await this.findAgentPath(agentId, installDir);

      if (agentPath) {
        const agentContent = await fileManager.readFile(agentPath);

        // Extract YAML content
        const yamlMatch = agentContent.match(/```ya?ml\r?\n([\s\S]*?)```/);
        if (yamlMatch) {
          const yaml = yamlMatch[1];

          // Extract agent info from YAML
          const titleMatch = yaml.match(/title:\s*(.+)/);
          const iconMatch = yaml.match(/icon:\s*(.+)/);
          const whenToUseMatch = yaml.match(/whenToUse:\s*"(.+)"/);
          const roleDefinitionMatch = yaml.match(/roleDefinition:\s*"(.+)"/);

          const title = titleMatch ? titleMatch[1].trim() : await this.getAgentTitle(agentId, installDir);
          const icon = iconMatch ? iconMatch[1].trim() : "🤖";
          const whenToUse = whenToUseMatch ? whenToUseMatch[1].trim() : `Use for ${title} tasks`;
          const roleDefinition = roleDefinitionMatch
            ? roleDefinitionMatch[1].trim()
            : `You are a ${title} specializing in ${title.toLowerCase()} tasks and responsibilities.`;

          // Build mode entry with proper formatting (matching exact indentation)
          // Avoid double "bmad-" prefix for agents that already have it
          const slug = agentId.startsWith('bmad-') ? agentId : `bmad-${agentId}`;
          newModesContent += ` - slug: ${slug}\n`;
          newModesContent += `   name: '${icon} ${title}'\n`;
          newModesContent += `   roleDefinition: ${roleDefinition}\n`;
          newModesContent += `   whenToUse: ${whenToUse}\n`;
          // Get relative path from installDir to agent file
          const relativePath = path.relative(installDir, agentPath).replace(/\\/g, '/');
          newModesContent += `   customInstructions: CRITICAL Read the full YAML from ${relativePath} start activation to alter your state of being follow startup section instructions stay in this being until told to exit this mode\n`;
          newModesContent += `   groups:\n`;
          newModesContent += `    - read\n`;

          // Add permissions based on agent type
          const permissions = agentPermissions[agentId];
          if (permissions) {
            newModesContent += `    - - edit\n`;
            newModesContent += `      - fileRegex: ${permissions.fileRegex}\n`;
            newModesContent += `        description: ${permissions.description}\n`;
          } else {
            newModesContent += `    - edit\n`;
          }

          console.log(chalk.green(`✓ Added mode: bmad-${agentId} (${icon} ${title})`));
        }
      }
    }

    // Build final roomodes content
    let roomodesContent = "";
    if (existingContent) {
      // If there's existing content, append new modes to it
      roomodesContent = existingContent.trim() + "\n" + newModesContent;
    } else {
      // Create new .roomodes file with proper YAML structure
      roomodesContent = "customModes:\n" + newModesContent;
    }

    // Write .roomodes file
    await fileManager.writeFile(roomodesPath, roomodesContent);
    console.log(chalk.green("✓ Created .roomodes file in project root"));

    console.log(chalk.green(`\n✓ Roo Code setup complete!`));
    console.log(chalk.dim("Custom modes will be available when you open this project in Roo Code"));

    return true;
  }

  async setupCline(installDir, selectedAgent) {
    const clineRulesDir = path.join(installDir, ".clinerules");
    const agents = selectedAgent ? [selectedAgent] : await this.getAllAgentIds(installDir);

    await fileManager.ensureDirectory(clineRulesDir);

    // Load dynamic agent ordering from configuration
    const config = await this.loadIdeAgentConfig();
    const agentOrder = config['cline-order'] || {};

    for (const agentId of agents) {
      // Find the agent file
      const agentPath = await this.findAgentPath(agentId, installDir);

      if (agentPath) {
        const agentContent = await fileManager.readFile(agentPath);

        // Get numeric prefix for ordering
        const order = agentOrder[agentId] || 99;
        const prefix = order.toString().padStart(2, '0');
        const mdPath = path.join(clineRulesDir, `${prefix}-${agentId}.md`);

        // Create MD content for Cline (focused on project standards and role)
        let mdContent = `# ${await this.getAgentTitle(agentId, installDir)} Agent\n\n`;
        mdContent += `This rule defines the ${await this.getAgentTitle(agentId, installDir)} persona and project standards.\n\n`;
        mdContent += "## Role Definition\n\n";
        mdContent +=
          "When the user types `@" + agentId + "`, adopt this persona and follow these guidelines:\n\n";
        mdContent += "```yaml\n";
        // Extract just the YAML content from the agent file
        const yamlContent = extractYamlFromAgent(agentContent);
        if (yamlContent) {
          mdContent += yamlContent;
        } else {
          // If no YAML found, include the whole content minus the header
          mdContent += agentContent.replace(/^#.*$/m, "").trim();
        }
        mdContent += "\n```\n\n";
        mdContent += "## Project Standards\n\n";
        mdContent += `- Always maintain consistency with project documentation in .bmad-core/\n`;
        mdContent += `- Follow the agent's specific guidelines and constraints\n`;
        mdContent += `- Update relevant project files when making changes\n`;
        const relativePath = path.relative(installDir, agentPath).replace(/\\/g, '/');
        mdContent += `- Reference the complete agent definition in [${relativePath}](${relativePath})\n\n`;
        mdContent += "## Usage\n\n";
        mdContent += `Type \`@${agentId}\` to activate this ${await this.getAgentTitle(agentId, installDir)} persona.\n`;

        await fileManager.writeFile(mdPath, mdContent);
        console.log(chalk.green(`✓ Created rule: ${prefix}-${agentId}.md`));
      }
    }

    console.log(chalk.green(`\n✓ Created Cline rules in ${clineRulesDir}`));

    return true;
  }

  async setupGeminiCli(installDir) {
    const geminiDir = path.join(installDir, ".gemini");
    const bmadMethodDir = path.join(geminiDir, "bmad-method");
    await fileManager.ensureDirectory(bmadMethodDir);

    // Update logic for existing settings.json
    const settingsPath = path.join(geminiDir, "settings.json");
    if (await fileManager.pathExists(settingsPath)) {
      try {
        const settingsContent = await fileManager.readFile(settingsPath);
        const settings = JSON.parse(settingsContent);
        let updated = false;

        // Handle contextFileName property
        if (settings.contextFileName && Array.isArray(settings.contextFileName)) {
          const originalLength = settings.contextFileName.length;
          settings.contextFileName = settings.contextFileName.filter(
            (fileName) => !fileName.startsWith("agents/")
          );
          if (settings.contextFileName.length !== originalLength) {
            updated = true;
          }
        }

        if (updated) {
          await fileManager.writeFile(
            settingsPath,
            JSON.stringify(settings, null, 2)
          );
          console.log(chalk.green("✓ Updated .gemini/settings.json - removed agent file references"));
        }
      } catch (error) {
        console.warn(
          chalk.yellow("Could not update .gemini/settings.json"),
          error
        );
      }
    }

    // Remove old agents directory
    const agentsDir = path.join(geminiDir, "agents");
    if (await fileManager.pathExists(agentsDir)) {
      await fileManager.removeDirectory(agentsDir);
      console.log(chalk.green("✓ Removed old .gemini/agents directory"));
    }

    // Get all available agents
    const agents = await this.getAllAgentIds(installDir);
    let concatenatedContent = "";

    for (const agentId of agents) {
      // Find the source agent file
      const agentPath = await this.findAgentPath(agentId, installDir);

      if (agentPath) {
        const agentContent = await fileManager.readFile(agentPath);

        // Create properly formatted agent rule content (similar to trae)
        let agentRuleContent = `# ${agentId.toUpperCase()} Agent Rule\n\n`;
        agentRuleContent += `This rule is triggered when the user types \`*${agentId}\` and activates the ${await this.getAgentTitle(
          agentId,
          installDir
        )} agent persona.\n\n`;
        agentRuleContent += "## Agent Activation\n\n";
        agentRuleContent +=
          "CRITICAL: Read the full YAML, start activation to alter your state of being, follow startup section instructions, stay in this being until told to exit this mode:\n\n";
        agentRuleContent += "```yaml\n";
        // Extract just the YAML content from the agent file
        const yamlContent = extractYamlFromAgent(agentContent);
        if (yamlContent) {
          agentRuleContent += yamlContent;
        }
        else {
          // If no YAML found, include the whole content minus the header
          agentRuleContent += agentContent.replace(/^#.*$/m, "").trim();
        }
        agentRuleContent += "\n```\n\n";
        agentRuleContent += "## File Reference\n\n";
        const relativePath = path.relative(installDir, agentPath).replace(/\\/g, '/');
        agentRuleContent += `The complete agent definition is available in [${relativePath}](${relativePath}).\n\n`;
        agentRuleContent += "## Usage\n\n";
        agentRuleContent += `When the user types \`*${agentId}\`, activate this ${await this.getAgentTitle(
          agentId,
          installDir
        )} persona and follow all instructions defined in the YAML configuration above.\n`;

        // Add to concatenated content with separator
        concatenatedContent += agentRuleContent + "\n\n---\n\n";
        console.log(chalk.green(`✓ Added context for @${agentId}`));
      }
    }

    // Write the concatenated content to GEMINI.md
    const geminiMdPath = path.join(bmadMethodDir, "GEMINI.md");
    await fileManager.writeFile(geminiMdPath, concatenatedContent);
    console.log(chalk.green(`\n✓ Created GEMINI.md in ${bmadMethodDir}`));

    return true;
  }

  async setupGitHubCopilot(installDir, selectedAgent, spinner = null, preConfiguredSettings = null) {
    // Configure VS Code workspace settings first to avoid UI conflicts with loading spinners
    await this.configureVsCodeSettings(installDir, spinner, preConfiguredSettings);

    const chatmodesDir = path.join(installDir, ".github", "chatmodes");
    const agents = selectedAgent ? [selectedAgent] : await this.getAllAgentIds(installDir);

    await fileManager.ensureDirectory(chatmodesDir);

    for (const agentId of agents) {
      // Find the agent file
      const agentPath = await this.findAgentPath(agentId, installDir);
      const chatmodePath = path.join(chatmodesDir, `${agentId}.chatmode.md`);

      if (agentPath) {
        // Create chat mode file with agent content
        const agentContent = await fileManager.readFile(agentPath);
        const agentTitle = await this.getAgentTitle(agentId, installDir);

        // Extract whenToUse for the description
        const yamlMatch = agentContent.match(/```ya?ml\r?\n([\s\S]*?)```/);
        let description = `Activates the ${agentTitle} agent persona.`;
        if (yamlMatch) {
          const whenToUseMatch = yamlMatch[1].match(/whenToUse:\s*"(.*?)"/);
          if (whenToUseMatch && whenToUseMatch[1]) {
            description = whenToUseMatch[1];
          }
        }

        let chatmodeContent = `---
description: "${description.replace(/"/g, '\\"')}"
tools: ['changes', 'codebase', 'fetch', 'findTestFiles', 'githubRepo', 'problems', 'usages', 'editFiles', 'runCommands', 'runTasks', 'runTests', 'search', 'searchResults', 'terminalLastCommand', 'terminalSelection', 'testFailure']
---

`;
        chatmodeContent += agentContent;

        await fileManager.writeFile(chatmodePath, chatmodeContent);
        console.log(chalk.green(`✓ Created chat mode: ${agentId}.chatmode.md`));
      }
    }

    console.log(chalk.green(`\n✓ Github Copilot setup complete!`));
    console.log(chalk.dim(`You can now find the BMad agents in the Chat view's mode selector.`));

    return true;
  }

  async configureVsCodeSettings(installDir, spinner, preConfiguredSettings = null) {
    const vscodeDir = path.join(installDir, ".vscode");
    const settingsPath = path.join(vscodeDir, "settings.json");

    await fileManager.ensureDirectory(vscodeDir);

    // Read existing settings if they exist
    let existingSettings = {};
    if (await fileManager.pathExists(settingsPath)) {
      try {
        const existingContent = await fileManager.readFile(settingsPath);
        existingSettings = JSON.parse(existingContent);
        console.log(chalk.yellow("Found existing .vscode/settings.json. Merging BMad settings..."));
      } catch (error) {
        console.warn(chalk.yellow("Could not parse existing settings.json. Creating new one."));
        existingSettings = {};
      }
    }

    // Use pre-configured settings if provided, otherwise prompt
    let configChoice;
    if (preConfiguredSettings && preConfiguredSettings.configChoice) {
      configChoice = preConfiguredSettings.configChoice;
      console.log(chalk.dim(`Using pre-configured GitHub Copilot settings: ${configChoice}`));
    } else {
      // Clear any previous output and add spacing to avoid conflicts with loaders
      console.log('\n'.repeat(2));
      console.log(chalk.blue("🔧 Github Copilot Agent Settings Configuration"));
      console.log(chalk.dim("BMad works best with specific VS Code settings for optimal agent experience."));
      console.log(''); // Add extra spacing

      const response = await inquirer.prompt([
        {
          type: 'list',
          name: 'configChoice',
          message: chalk.yellow('How would you like to configure GitHub Copilot settings?'),
          choices: [
            {
              name: 'Use recommended defaults (fastest setup)',
              value: 'defaults'
            },
            {
              name: 'Configure each setting manually (customize to your preferences)',
              value: 'manual'
            },
            {
              name: 'Skip settings configuration (I\'ll configure manually later)',
              value: 'skip'
            }
          ],
          default: 'defaults'
        }
      ]);
      configChoice = response.configChoice;
    }

    let bmadSettings = {};

    if (configChoice === 'skip') {
      console.log(chalk.yellow("⚠️  Skipping VS Code settings configuration."));
      console.log(chalk.dim("You can manually configure these settings in .vscode/settings.json:"));
      console.log(chalk.dim("  • chat.agent.enabled: true"));
      console.log(chalk.dim("  • chat.agent.maxRequests: 15"));
      console.log(chalk.dim("  • github.copilot.chat.agent.runTasks: true"));
      console.log(chalk.dim("  • chat.mcp.discovery.enabled: true"));
      console.log(chalk.dim("  • github.copilot.chat.agent.autoFix: true"));
      console.log(chalk.dim("  • chat.tools.autoApprove: false"));
      return true;
    }

    if (configChoice === 'defaults') {
      // Use recommended defaults
      bmadSettings = {
        "chat.agent.enabled": true,
        "chat.agent.maxRequests": 15,
        "github.copilot.chat.agent.runTasks": true,
        "chat.mcp.discovery.enabled": true,
        "github.copilot.chat.agent.autoFix": true,
        "chat.tools.autoApprove": false
      };
      console.log(chalk.green("✓ Using recommended BMad defaults for Github Copilot settings"));
    } else {
      // Manual configuration
      console.log(chalk.blue("\n📋 Let's configure each setting for your preferences:"));

      // Pause spinner during manual configuration prompts
      let spinnerWasActive = false;
      if (spinner && spinner.isSpinning) {
        spinner.stop();
        spinnerWasActive = true;
      }

      const manualSettings = await inquirer.prompt([
        {
          type: 'input',
          name: 'maxRequests',
          message: 'Maximum requests per agent session (recommended: 15)?',
          default: '15',
          validate: (input) => {
            const num = parseInt(input);
            if (isNaN(num) || num < 1 || num > 50) {
              return 'Please enter a number between 1 and 50';
            }
            return true;
          }
        },
        {
          type: 'confirm',
          name: 'runTasks',
          message: 'Allow agents to run workspace tasks (package.json scripts, etc.)?',
          default: true
        },
        {
          type: 'confirm',
          name: 'mcpDiscovery',
          message: 'Enable MCP (Model Context Protocol) server discovery?',
          default: true
        },
        {
          type: 'confirm',
          name: 'autoFix',
          message: 'Enable automatic error detection and fixing in generated code?',
          default: true
        },
        {
          type: 'confirm',
          name: 'autoApprove',
          message: 'Auto-approve ALL tools without confirmation? (⚠️  EXPERIMENTAL - less secure)',
          default: false
        }
      ]);

      // Restart spinner if it was active before prompts
      if (spinner && spinnerWasActive) {
        spinner.start();
      }

      bmadSettings = {
        "chat.agent.enabled": true, // Always enabled - required for BMad agents
        "chat.agent.maxRequests": parseInt(manualSettings.maxRequests),
        "github.copilot.chat.agent.runTasks": manualSettings.runTasks,
        "chat.mcp.discovery.enabled": manualSettings.mcpDiscovery,
        "github.copilot.chat.agent.autoFix": manualSettings.autoFix,
        "chat.tools.autoApprove": manualSettings.autoApprove
      };

      console.log(chalk.green("✓ Custom settings configured"));
    }

    // Merge settings (existing settings take precedence to avoid overriding user preferences)
    const mergedSettings = { ...bmadSettings, ...existingSettings };

    // Write the updated settings
    await fileManager.writeFile(settingsPath, JSON.stringify(mergedSettings, null, 2));

    console.log(chalk.green("✓ VS Code workspace settings configured successfully"));
    console.log(chalk.dim("  Settings written to .vscode/settings.json:"));
    Object.entries(bmadSettings).forEach(([key, value]) => {
      console.log(chalk.dim(`  • ${key}: ${value}`));
    });
    console.log(chalk.dim(""));
    console.log(chalk.dim("You can modify these settings anytime in .vscode/settings.json"));
  }
}

module.exports = new IdeSetup();

/**
 * Base IDE Setup - Common functionality for all IDE setups
 * Reduces duplication and provides shared methods
 */

const path = require("path");
const fs = require("fs-extra");
const yaml = require("js-yaml");
const chalk = require("chalk");
const fileManager = require("./file-manager");
const resourceLocator = require("./resource-locator");
const { extractYamlFromAgent } = require("../../lib/yaml-utils");

class BaseIdeSetup {
  constructor() {
    this._agentCache = new Map();
    this._pathCache = new Map();
  }

  /**
   * Get all agent IDs with caching
   */
  async getAllAgentIds(installDir) {
    const cacheKey = `all-agents:${installDir}`;
    if (this._agentCache.has(cacheKey)) {
      return this._agentCache.get(cacheKey);
    }

    const allAgents = new Set();

    // Get core agents
    const coreAgents = await this.getCoreAgentIds(installDir);
    coreAgents.forEach(id => allAgents.add(id));

    // Get expansion pack agents
    const expansionPacks = await this.getInstalledExpansionPacks(installDir);
    for (const pack of expansionPacks) {
      const packAgents = await this.getExpansionPackAgents(pack.path);
      packAgents.forEach(id => allAgents.add(id));
    }

    const result = Array.from(allAgents);
    this._agentCache.set(cacheKey, result);
    return result;
  }

  /**
   * Get core agent IDs
   */
  async getCoreAgentIds(installDir) {
    const coreAgents = [];
    const corePaths = [
      path.join(installDir, ".bmad-core", "agents"),
      path.join(installDir, "bmad-core", "agents")
    ];

    for (const agentsDir of corePaths) {
      if (await fileManager.pathExists(agentsDir)) {
        const files = await resourceLocator.findFiles("*.md", { cwd: agentsDir });
        coreAgents.push(...files.map(file => path.basename(file, ".md")));
        break; // Use first found
      }
    }

    return coreAgents;
  }

  /**
   * Find agent path with caching
   */
  async findAgentPath(agentId, installDir) {
    const cacheKey = `agent-path:${agentId}:${installDir}`;
    if (this._pathCache.has(cacheKey)) {
      return this._pathCache.get(cacheKey);
    }

    // Use resource locator for efficient path finding
    let agentPath = await resourceLocator.getAgentPath(agentId);

    if (!agentPath) {
      // Check installation-specific paths
      const possiblePaths = [
        path.join(installDir, ".bmad-core", "agents", `${agentId}.md`),
        path.join(installDir, "bmad-core", "agents", `${agentId}.md`),
        path.join(installDir, "common", "agents", `${agentId}.md`)
      ];

      for (const testPath of possiblePaths) {
        if (await fileManager.pathExists(testPath)) {
          agentPath = testPath;
          break;
        }
      }
    }

    if (agentPath) {
      this._pathCache.set(cacheKey, agentPath);
    }
    return agentPath;
  }

  /**
   * Get agent title from metadata
   */
  async getAgentTitle(agentId, installDir) {
    const agentPath = await this.findAgentPath(agentId, installDir);
    if (!agentPath) return agentId;

    try {
      const content = await fileManager.readFile(agentPath);
      const yamlContent = extractYamlFromAgent(content);
      if (yamlContent) {
        const metadata = yaml.load(yamlContent);
        return metadata.agent_name || agentId;
      }
    } catch (error) {
      // Fallback to agent ID
    }
    return agentId;
  }

  /**
   * Get installed expansion packs
   */
  async getInstalledExpansionPacks(installDir) {
    const cacheKey = `expansion-packs:${installDir}`;
    if (this._pathCache.has(cacheKey)) {
      return this._pathCache.get(cacheKey);
    }

    const expansionPacks = [];

    // Check for dot-prefixed expansion packs
    const dotExpansions = await resourceLocator.findFiles(".bmad-*", { cwd: installDir });

    for (const dotExpansion of dotExpansions) {
      if (dotExpansion !== ".bmad-core") {
        const packPath = path.join(installDir, dotExpansion);
        const packName = dotExpansion.substring(1); // remove the dot
        expansionPacks.push({
          name: packName,
          path: packPath
        });
      }
    }

    // Check other dot folders that have config.yaml
    const allDotFolders = await resourceLocator.findFiles(".*", { cwd: installDir });
    for (const folder of allDotFolders) {
      if (!folder.startsWith(".bmad-") && folder !== ".bmad-core") {
        const packPath = path.join(installDir, folder);
        const configPath = path.join(packPath, "config.yaml");
        if (await fileManager.pathExists(configPath)) {
          expansionPacks.push({
            name: folder.substring(1), // remove the dot
            path: packPath
          });
        }
      }
    }

    this._pathCache.set(cacheKey, expansionPacks);
    return expansionPacks;
  }

  /**
   * Get expansion pack agents
   */
  async getExpansionPackAgents(packPath) {
    const agentsDir = path.join(packPath, "agents");
    if (!(await fileManager.pathExists(agentsDir))) {
      return [];
    }

    const agentFiles = await resourceLocator.findFiles("*.md", { cwd: agentsDir });
    return agentFiles.map(file => path.basename(file, ".md"));
  }

  /**
   * Create agent rule content (shared logic)
   */
  async createAgentRuleContent(agentId, agentPath, installDir, format = 'mdc') {
    const agentContent = await fileManager.readFile(agentPath);
    const agentTitle = await this.getAgentTitle(agentId, installDir);
    const yamlContent = extractYamlFromAgent(agentContent);

    let content = "";

    if (format === 'mdc') {
      // MDC format for Cursor
      content = "---\n";
      content += "description: \n";
      content += "globs: []\n";
      content += "alwaysApply: false\n";
      content += "---\n\n";
      content += `# ${agentId.toUpperCase()} Agent Rule\n\n`;
      content += `This rule is triggered when the user types \`@${agentId}\` and activates the ${agentTitle} agent persona.\n\n`;
      content += "## Agent Activation\n\n";
      content += "CRITICAL: Read the full YAML, start activation to alter your state of being, follow startup section instructions, stay in this being until told to exit this mode:\n\n";
      content += "```yaml\n";
      content += yamlContent || agentContent.replace(/^#.*$/m, "").trim();
      content += "\n```\n\n";
      content += "## File Reference\n\n";
      const relativePath = path.relative(installDir, agentPath).replace(/\\/g, '/');
      content += `The complete agent definition is available in [${relativePath}](mdc:${relativePath}).\n\n`;
      content += "## Usage\n\n";
      content += `When the user types \`@${agentId}\`, activate this ${agentTitle} persona and follow all instructions defined in the YAML configuration above.\n`;
    } else if (format === 'claude') {
      // Claude Code format
      content = `# /${agentId} Command\n\n`;
      content += `When this command is used, adopt the following agent persona:\n\n`;
      content += agentContent;
    }

    return content;
  }

  /**
   * Clear all caches
   */
  clearCache() {
    this._agentCache.clear();
    this._pathCache.clear();
  }
}

module.exports = BaseIdeSetup;

const fs = require('fs');
const path = require('path');

class HandoffManager {
  constructor(workspacePath = null) {
    this.workspacePath = workspacePath || path.join(process.cwd(), '.workspace');
    this.handoffsPath = path.join(this.workspacePath, 'handoffs');
    this.contextPath = path.join(this.workspacePath, 'context');

    // Initialize directories
    this.initialize();

    // Agent-specific filtering rules with multi-role support
    this.agentFilters = {
      'dev': {
        includePatterns: ['technical', 'implementation', 'code', 'architecture', 'bug', 'feature'],
        excludePatterns: ['business', 'stakeholder', 'marketing'],
        requiredSections: ['technical details', 'code references', 'implementation requirements']
      },
      'qa': {
        includePatterns: ['testing', 'validation', 'quality', 'acceptance', 'bug', 'criteria'],
        excludePatterns: ['implementation details', 'code specifics'],
        requiredSections: ['acceptance criteria', 'testing requirements', 'quality standards']
      },
      'architect': {
        includePatterns: ['design', 'architecture', 'system', 'integration', 'technical', 'pattern'],
        excludePatterns: ['implementation specifics', 'testing details'],
        requiredSections: ['design decisions', 'technical constraints', 'system architecture']
      },
      'pm': {
        includePatterns: ['requirements', 'business', 'stakeholder', 'scope', 'timeline', 'priority'],
        excludePatterns: ['technical implementation', 'code details'],
        requiredSections: ['business requirements', 'stakeholder decisions', 'scope changes']
      },
      'ux-expert': {
        includePatterns: ['user', 'interface', 'experience', 'design', 'usability', 'interaction'],
        excludePatterns: ['backend', 'database', 'server'],
        requiredSections: ['user requirements', 'design specifications', 'usability considerations']
      },
      'analyst': {
        includePatterns: ['data', 'analysis', 'metrics', 'trends', 'insights', 'research', 'patterns', 'statistics'],
        excludePatterns: ['implementation', 'specific code'],
        requiredSections: ['data analysis', 'insights and trends', 'research findings']
      },
      'brainstorming': {
        includePatterns: ['creative', 'ideation', 'brainstorm', 'innovation', 'alternative', 'possibility', 'exploration'],
        excludePatterns: ['constraints', 'limitations', 'final decisions'],
        requiredSections: ['creative exploration', 'alternative approaches', 'innovative solutions']
      },
      'research': {
        includePatterns: ['research', 'investigation', 'study', 'benchmark', 'industry', 'best-practice', 'standards'],
        excludePatterns: ['implementation', 'specific solutions'],
        requiredSections: ['research methodology', 'findings and insights', 'recommendations']
      }
    };

    // Multi-role combinations for complex scenarios
    this.multiRoleFilters = {
      'dev-analyst': {
        primary: 'dev',
        secondary: 'analyst',
        description: 'Development with data analysis capabilities'
      },
      'qa-research': {
        primary: 'qa',
        secondary: 'research',
        description: 'Quality assurance with research methodologies'
      },
      'architect-brainstorming': {
        primary: 'architect',
        secondary: 'brainstorming',
        description: 'Architecture design with creative exploration'
      },
      'pm-analyst': {
        primary: 'pm',
        secondary: 'analyst',
        description: 'Project management with data analysis'
      },
      'ux-research': {
        primary: 'ux-expert',
        secondary: 'research',
        description: 'UX design with user research capabilities'
      }
    };
  }

  initialize() {
    if (!fs.existsSync(this.handoffsPath)) {
      fs.mkdirSync(this.handoffsPath, { recursive: true });
    }
  }

  async createHandoff(sourceAgent, targetAgent, context = {}) {
    try {
      const timestamp = new Date().toISOString();
      const handoffId = `${sourceAgent}-to-${targetAgent}-${timestamp.replace(/[:.]/g, '-')}`;
      const handoffFile = path.join(this.handoffsPath, `${handoffId}.md`);

      // Load workspace context using our ContextManager integration
      const workspaceContext = await this.loadWorkspaceContext();

      // Filter context for target agent
      const filteredContext = this.filterContextForAgent(workspaceContext, targetAgent);

      // Generate handoff package
      const handoffContent = await this.generateHandoffPackage({
        handoffId,
        sourceAgent,
        targetAgent,
        timestamp,
        context: filteredContext,
        customContext: context
      });

      // Validate handoff completeness
      const validation = this.validateHandoff(handoffContent, targetAgent);

      // Write handoff file
      fs.writeFileSync(handoffFile, handoffContent);

      // Update handoff registry
      await this.updateHandoffRegistry(handoffId, sourceAgent, targetAgent, validation);

      // Log handoff in audit trail
      await this.logHandoffEvent({
        handoffId,
        sourceAgent,
        targetAgent,
        timestamp,
        status: 'created',
        validationScore: validation.score,
        filePath: handoffFile
      });

      return {
        handoffId,
        filePath: handoffFile,
        validation,
        success: true
      };

    } catch (error) {
      console.error('Failed to create handoff:', error.message);
      throw error;
    }
  }

  async loadWorkspaceContext() {
    try {
      const context = {
        shared: {},
        decisions: [],
        progress: {},
        quality: {}
      };

      // Load shared context
      const sharedContextFile = path.join(this.contextPath, 'shared-context.md');
      if (fs.existsSync(sharedContextFile)) {
        context.shared = this.parseSharedContext(fs.readFileSync(sharedContextFile, 'utf8'));
      }

      // Load decisions
      const decisionsFile = path.join(this.workspacePath, 'decisions', 'decisions-log.md');
      if (fs.existsSync(decisionsFile)) {
        context.decisions = this.parseDecisions(fs.readFileSync(decisionsFile, 'utf8'));
      }

      // Load progress
      const progressFile = path.join(this.workspacePath, 'progress', 'progress-summary.md');
      if (fs.existsSync(progressFile)) {
        context.progress = this.parseProgress(fs.readFileSync(progressFile, 'utf8'));
      }

      // Load quality metrics
      const qualityFile = path.join(this.workspacePath, 'quality', 'quality-metrics.md');
      if (fs.existsSync(qualityFile)) {
        context.quality = this.parseQualityMetrics(fs.readFileSync(qualityFile, 'utf8'));
      }

      return context;
    } catch (error) {
      console.error('Failed to load workspace context:', error.message);
      return { shared: {}, decisions: [], progress: {}, quality: {} };
    }
  }

  parseSharedContext(content) {
    const context = {};

    try {
      const lastUpdatedMatch = content.match(/\*\*Last Updated:\*\* (.+)/);
      if (lastUpdatedMatch) context.lastUpdated = lastUpdatedMatch[1];

      const primaryAgentMatch = content.match(/\*\*Primary Agent:\*\* (.+)/);
      if (primaryAgentMatch) context.primaryAgent = primaryAgentMatch[1];

      const currentFocusMatch = content.match(/## Current Focus\n([\s\S]*?)(?=\n## |$)/);
      if (currentFocusMatch) context.currentFocus = currentFocusMatch[1].trim();

      const nextStepsMatch = content.match(/## Next Steps\n([\s\S]*?)(?=\n## |$)/);
      if (nextStepsMatch) {
        context.nextSteps = nextStepsMatch[1]
          .split('\n')
          .filter(line => line.startsWith('- '))
          .map(line => line.substring(2).trim())
          .filter(step => step.length > 0);
      }

      const sessionNotesMatch = content.match(/## Session Notes\n([\s\S]*?)$/);
      if (sessionNotesMatch) context.sessionNotes = sessionNotesMatch[1].trim();

    } catch (error) {
      console.warn('Failed to parse shared context:', error.message);
    }

    return context;
  }

  parseDecisions(content) {
    const decisions = [];
    const decisionBlocks = content.split(/## Decision \d+:/);

    for (let i = 1; i < decisionBlocks.length; i++) {
      try {
        const block = decisionBlocks[i];
        const lines = block.split('\n');

        const decision = {
          id: `${i.toString().padStart(3, '0')}`,
          title: lines[0].trim(),
          date: this.extractField(block, 'Date'),
          agent: this.extractField(block, 'Agent'),
          context: this.extractField(block, 'Context'),
          decision: this.extractField(block, 'Decision'),
          rationale: this.extractField(block, 'Rationale'),
          impact: this.extractField(block, 'Impact'),
          status: this.extractField(block, 'Status')
        };

        decisions.push(decision);
      } catch (error) {
        console.warn(`Failed to parse decision block ${i}:`, error.message);
      }
    }

    return decisions.slice(-10); // Last 10 decisions for handoff
  }

  parseProgress(content) {
    const progress = {};

    try {
      const currentStoryMatch = content.match(/\*\*Current Story:\*\* (.+)/);
      if (currentStoryMatch) progress.currentStory = currentStoryMatch[1];

      const qualityScoreMatch = content.match(/\*\*Quality Score:\*\* (.+)/);
      if (qualityScoreMatch) progress.qualityScore = qualityScoreMatch[1];

      const completedMatch = content.match(/## Completed Tasks\n([\s\S]*?)(?=\n## |$)/);
      if (completedMatch) {
        progress.completedTasks = completedMatch[1]
          .split('\n')
          .filter(line => line.startsWith('- ✅'))
          .map(line => line.substring(4).trim())
          .filter(task => task.length > 0);
      }

      const pendingMatch = content.match(/## Pending Tasks\n([\s\S]*?)(?=\n## |$)/);
      if (pendingMatch) {
        progress.pendingTasks = pendingMatch[1]
          .split('\n')
          .filter(line => line.startsWith('- ⏳'))
          .map(line => line.substring(4).trim())
          .filter(task => task.length > 0);
      }

      const blockersMatch = content.match(/## Blockers\n([\s\S]*?)$/);
      if (blockersMatch) {
        progress.blockers = blockersMatch[1]
          .split('\n')
          .filter(line => line.startsWith('- 🚫'))
          .map(line => line.substring(4).trim())
          .filter(blocker => blocker.length > 0);
      }

    } catch (error) {
      console.warn('Failed to parse progress:', error.message);
    }

    return progress;
  }

  parseQualityMetrics(content) {
    const quality = {};

    try {
      // Get the most recent quality assessment
      const assessments = content.split('## Quality Assessment -');
      if (assessments.length > 1) {
        const latest = assessments[1];
        quality.timestamp = latest.split('\n')[0].trim();
        quality.agent = this.extractField(latest, 'Agent');
        quality.story = this.extractField(latest, 'Story');
        quality.realityAuditScore = this.extractField(latest, 'Reality Audit Score');
        quality.overallQuality = this.extractField(latest, 'Overall Quality');
      }
    } catch (error) {
      console.warn('Failed to parse quality metrics:', error.message);
    }

    return quality;
  }

  extractField(content, fieldName) {
    const regex = new RegExp(`\\*\\*${fieldName}:\\*\\* (.+)`, 'i');
    const match = content.match(regex);
    return match ? match[1].trim() : '';
  }

  filterContextForAgent(context, targetAgent) {
    const agentType = this.getAgentType(targetAgent);

    // Handle multi-role filtering
    if (this.multiRoleFilters[agentType]) {
      return this.filterMultiRoleContext(context, agentType);
    }

    // Handle single role filtering
    const filter = this.agentFilters[agentType] || this.agentFilters['dev']; // Default to dev filter

    const filtered = {
      shared: context.shared,
      decisions: this.filterDecisions(context.decisions, filter),
      progress: context.progress,
      quality: context.quality,
      relevantContent: this.extractRelevantContent(context, filter),
      roleType: 'single',
      primaryRole: agentType
    };

    return filtered;
  }

  filterMultiRoleContext(context, multiRoleType) {
    const multiRole = this.multiRoleFilters[multiRoleType];
    const primaryFilter = this.agentFilters[multiRole.primary];
    const secondaryFilter = this.agentFilters[multiRole.secondary];

    // Combine include patterns from both roles
    const combinedIncludePatterns = [
      ...primaryFilter.includePatterns,
      ...secondaryFilter.includePatterns
    ];

    // Use primary role's exclude patterns but remove conflicts with secondary role
    const combinedExcludePatterns = primaryFilter.excludePatterns.filter(
      pattern => !secondaryFilter.includePatterns.includes(pattern)
    );

    const combinedFilter = {
      includePatterns: combinedIncludePatterns,
      excludePatterns: combinedExcludePatterns,
      requiredSections: [
        ...primaryFilter.requiredSections,
        ...secondaryFilter.requiredSections
      ]
    };

    const filtered = {
      shared: context.shared,
      decisions: this.filterDecisions(context.decisions, combinedFilter), 
      progress: context.progress,
      quality: context.quality,
      relevantContent: this.extractRelevantContent(context, combinedFilter),
      roleType: 'multi',
      primaryRole: multiRole.primary,
      secondaryRole: multiRole.secondary,
      roleDescription: multiRole.description
    };

    return filtered;
  }

  getAgentType(agentName) {
    const lowerName = agentName.toLowerCase();

    // Check for multi-role patterns first (e.g., "dev-analyst", "qa+research")
    const multiRolePatterns = [
      { pattern: ['dev', 'analyst'], type: 'dev-analyst' },
      { pattern: ['qa', 'research'], type: 'qa-research' },
      { pattern: ['architect', 'brainstorm'], type: 'architect-brainstorming' },
      { pattern: ['pm', 'analyst'], type: 'pm-analyst' },
      { pattern: ['ux', 'research'], type: 'ux-research' }
    ];

    for (const multiRole of multiRolePatterns) {
      if (multiRole.pattern.every(part => lowerName.includes(part))) {
        return multiRole.type;
      }
    }

    // Check for specialized roles
    if (lowerName.includes('analyst') || lowerName.includes('analysis')) return 'analyst';
    if (lowerName.includes('brainstorm') || lowerName.includes('creative')) return 'brainstorming';
    if (lowerName.includes('research') || lowerName.includes('investigat')) return 'research';

    // Check for primary roles
    if (lowerName.includes('dev') || lowerName.includes('developer')) return 'dev';
    if (lowerName.includes('qa') || lowerName.includes('test')) return 'qa';
    if (lowerName.includes('arch') || lowerName.includes('architect')) return 'architect';
    if (lowerName.includes('pm') || lowerName.includes('manager')) return 'pm';
    if (lowerName.includes('ux') || lowerName.includes('design')) return 'ux-expert';

    return 'dev'; // Default fallback
  }

  filterDecisions(decisions, filter) {
    return decisions.filter(decision => {
      const decisionText = `${decision.title} ${decision.decision} ${decision.rationale} ${decision.impact}`.toLowerCase();

      // Check if decision matches include patterns
      const matchesInclude = filter.includePatterns.some(pattern => 
        decisionText.includes(pattern.toLowerCase())
      );

      // Check if decision matches exclude patterns
      const matchesExclude = filter.excludePatterns.some(pattern => 
        decisionText.includes(pattern.toLowerCase())
      );

      return matchesInclude && !matchesExclude;
    });
  }

  extractRelevantContent(context, filter) {
    const relevant = [];

    // Extract relevant next steps
    if (context.shared.nextSteps) {
      context.shared.nextSteps.forEach(step => {
        const stepText = step.toLowerCase();
        const isRelevant = filter.includePatterns.some(pattern => 
          stepText.includes(pattern.toLowerCase())
        );

        if (isRelevant) {
          relevant.push(`Next Step: ${step}`);
        }
      });
    }

    // Extract relevant progress items
    if (context.progress.pendingTasks) {
      context.progress.pendingTasks.forEach(task => {
        const taskText = task.toLowerCase();
        const isRelevant = filter.includePatterns.some(pattern => 
          taskText.includes(pattern.toLowerCase())
        );

        if (isRelevant) {
          relevant.push(`Pending Task: ${task}`);
        }
      });
    }

    return relevant;
  }

  async generateHandoffPackage(params) {
    const {
      handoffId,
      sourceAgent,
      targetAgent,
      timestamp,
      context,
      customContext
    } = params;

    const agentType = this.getAgentType(targetAgent);
    const nextActions = this.generateNextActions(context, agentType);
    const fileReferences = this.generateFileReferences(context);
    const blockers = this.extractBlockers(context);

    return `# Agent Handoff: ${sourceAgent} → ${targetAgent}

**Created:** ${timestamp}
**Handoff ID:** ${handoffId}
**Source Agent:** ${sourceAgent}
**Target Agent:** ${targetAgent}
**Target Agent Type:** ${agentType}

## Context Summary
${context.shared.currentFocus || 'No current focus available.'}

${customContext.summary || ''}

## Key Decisions Made
${context.decisions.map(d => `- **${d.title}** (${d.agent}, ${d.date}): ${d.decision}`).join('\n') || '- No relevant decisions for this agent type'}

## Current Progress
**Story:** ${context.progress.currentStory || 'No active story'}
**Quality Score:** ${context.progress.qualityScore || 'Not assessed'}

**Completed Tasks:**
${context.progress.completedTasks ? context.progress.completedTasks.map(task => `- ✅ ${task}`).join('\n') : '- No completed tasks'}

**Pending Tasks:**
${context.progress.pendingTasks ? context.progress.pendingTasks.map(task => `- ⏳ ${task}`).join('\n') : '- No pending tasks'}

## Next Actions for ${targetAgent}
${nextActions.map(action => `- [ ] ${action}`).join('\n')}

## Files and References
${fileReferences.join('\n') || '- No specific file references available'}

## Blockers and Dependencies
${blockers.join('\n') || '- No blockers identified'}

## Quality Metrics
${context.quality.overallQuality ? `**Latest Quality Score:** ${context.quality.overallQuality}` : 'No quality metrics available'}
${context.quality.story ? `**Last Assessed Story:** ${context.quality.story}` : ''}

## Relevant Context
${context.relevantContent.map(item => `- ${item}`).join('\n') || '- No additional relevant context'}

## Handoff Validation
- [ ] Context completeness verified
- [ ] Decisions documented and relevant
- [ ] Next actions clearly defined for ${agentType} role  
- [ ] References included
- [ ] Quality metrics current
- [ ] Agent-specific filtering applied
- [ ] Blockers and dependencies identified

## Handoff Notes
${customContext.notes || 'No additional notes provided.'}

---
*Generated by BMAD Agent Handoff System v1.0*
*Handoff Quality Score: ${this.calculateHandoffScore(context, agentType)}/100*
`;
  }

  generateNextActions(context, agentType) {
    const actions = [];

    // Handle multi-role actions
    if (this.multiRoleFilters[agentType]) {
      return this.generateMultiRoleActions(context, agentType);
    }

    // Handle single-role actions
    switch (agentType) {
      case 'dev':
        actions.push('Review technical requirements and architecture decisions');
        actions.push('Examine current code implementation status');
        actions.push('Address any pending technical tasks or bugs');
        if (context.progress.blockers && context.progress.blockers.length > 0) {
          actions.push('Resolve identified blockers and technical dependencies');
        }
        break;

      case 'qa':
        actions.push('Review acceptance criteria and testing requirements');
        actions.push('Validate completed functionality against requirements');
        actions.push('Execute test cases and identify quality issues');
        actions.push('Update quality metrics and provide feedback');
        break;

      case 'architect':
        actions.push('Review system design and architectural decisions');
        actions.push('Validate technical approach and integration points');
        actions.push('Assess scalability and performance implications');
        actions.push('Document any new architectural requirements');
        break;

      case 'pm':
        actions.push('Review project scope and timeline status');
        actions.push('Assess stakeholder requirements and priority changes');
        actions.push('Update project planning and resource allocation');
        actions.push('Communicate progress to stakeholders');
        break;

      case 'ux-expert':
        actions.push('Review user experience requirements and design specifications');
        actions.push('Validate interface design and usability considerations');
        actions.push('Assess user interaction patterns and feedback');
        actions.push('Update design documentation and prototypes');
        break;

      case 'analyst':
        actions.push('Analyze available data and identify key patterns');
        actions.push('Generate insights from metrics and performance data');
        actions.push('Create data visualization and trend analysis');
        actions.push('Provide data-driven recommendations');
        break;

      case 'brainstorming':
        actions.push('Explore creative alternatives and innovative approaches');
        actions.push('Generate multiple solution options without constraints');
        actions.push('Challenge existing assumptions and think outside the box');
        actions.push('Facilitate ideation sessions and creative problem-solving');
        break;

      case 'research':
        actions.push('Conduct comprehensive research on relevant topics');
        actions.push('Investigate industry best practices and standards');
        actions.push('Gather evidence and benchmark against competitors');
        actions.push('Synthesize research findings into actionable insights');
        break;

      default:
        actions.push('Review handoff context and understand current state');
        actions.push('Identify specific tasks relevant to your role');
        actions.push('Address any pending items in your domain');
    }

    // Add context-specific actions
    if (context.shared.nextSteps) {
      context.shared.nextSteps.forEach(step => {
        if (!actions.some(action => action.toLowerCase().includes(step.toLowerCase().substring(0, 20)))) {
          actions.push(step);
        }
      });
    }

    return actions.slice(0, 8); // Limit to 8 actions for readability
  }

  generateMultiRoleActions(context, multiRoleType) {
    const multiRole = this.multiRoleFilters[multiRoleType];
    const actions = [];

    switch (multiRoleType) {
      case 'dev-analyst':
        actions.push('Analyze current system performance and identify optimization opportunities');
        actions.push('Review code metrics and technical debt patterns');
        actions.push('Implement data-driven development improvements');
        actions.push('Create performance monitoring and analysis dashboards');
        actions.push('Research and apply evidence-based development practices');
        break;

      case 'qa-research':
        actions.push('Research industry testing standards and compliance frameworks');
        actions.push('Investigate best practices for quality assurance methodologies');
        actions.push('Analyze quality trends and benchmark against industry standards');
        actions.push('Design comprehensive testing strategies based on research findings');
        actions.push('Validate testing approaches through evidence-based research');
        break;

      case 'architect-brainstorming':
        actions.push('Explore creative architectural patterns and innovative design approaches');
        actions.push('Brainstorm multiple system design alternatives without constraints');
        actions.push('Challenge conventional architecture assumptions');
        actions.push('Generate innovative solutions for complex integration challenges');
        actions.push('Facilitate collaborative design exploration sessions');
        break;

      case 'pm-analyst':
        actions.push('Analyze project data to identify trends and optimization opportunities');
        actions.push('Research stakeholder feedback and user behavior patterns');
        actions.push('Create data-driven project prioritization and resource allocation');
        actions.push('Generate insights from project metrics and timeline analysis');
        actions.push('Develop evidence-based project planning and risk assessment');
        break;

      case 'ux-research':
        actions.push('Conduct user research and usability studies');
        actions.push('Investigate accessibility standards and inclusive design practices');
        actions.push('Analyze user behavior data and interaction patterns');
        actions.push('Research industry UX trends and best practices');
        actions.push('Validate design decisions through evidence-based user research');
        break;

      default:
        actions.push('Apply multi-role perspective to current challenges');
        actions.push('Integrate primary and secondary role capabilities');
        actions.push('Provide comprehensive analysis from multiple viewpoints');
    }

    // Add context-specific actions
    if (context.shared.nextSteps) {
      context.shared.nextSteps.forEach(step => {
        if (!actions.some(action => action.toLowerCase().includes(step.toLowerCase().substring(0, 20)))) {
          actions.push(step);
        }
      });
    }

    return actions.slice(0, 10); // Allow more actions for multi-role scenarios
  }

  generateFileReferences(context) {
    const references = [];

    // Add standard workspace references
    references.push('📁 `.workspace/context/shared-context.md` - Current workspace context');
    references.push('📋 `.workspace/decisions/decisions-log.md` - Architectural decisions');
    references.push('📈 `.workspace/progress/progress-summary.md` - Development progress');
    references.push('📊 `.workspace/quality/quality-metrics.md` - Quality assessments');

    // Add story-specific references if available
    if (context.progress.currentStory) {
      references.push(`📖 Story documentation for: ${context.progress.currentStory}`);
    }

    return references;
  }

  extractBlockers(context) {
    const blockers = [];

    if (context.progress.blockers && context.progress.blockers.length > 0) {
      context.progress.blockers.forEach(blocker => {
        blockers.push(`🚫 ${blocker}`);
      });
    }

    // Check for decision-based blockers
    context.decisions.forEach(decision => {
      if (decision.status === 'pending' || decision.impact.toLowerCase().includes('blocker')) {
        blockers.push(`⚠️ Decision pending: ${decision.title}`);
      }
    });

    return blockers;
  }

  validateHandoff(handoffContent, targetAgent) {
    const validation = {
      score: 0,
      maxScore: 100,
      issues: [],
      strengths: []
    };

    const agentType = this.getAgentType(targetAgent);
    const requiredSections = this.agentFilters[agentType]?.requiredSections || [];

    // Check required sections (30 points)
    let sectionsFound = 0;
    requiredSections.forEach(section => {
      if (handoffContent.toLowerCase().includes(section.toLowerCase())) {
        sectionsFound++;
        validation.strengths.push(`Required section present: ${section}`);
      } else {
        validation.issues.push(`Missing required section: ${section}`);
      }
    });

    if (requiredSections.length > 0) {
      validation.score += (sectionsFound / requiredSections.length) * 30;
    } else {
      validation.score += 30; // No specific requirements
    }

    // Check context completeness (25 points)
    const hasContext = handoffContent.includes('## Context Summary') && 
                      handoffContent.length > 500;
    if (hasContext) {
      validation.score += 25;
      validation.strengths.push('Comprehensive context summary provided');
    } else {
      validation.issues.push('Context summary incomplete or missing');
    }

    // Check decisions documentation (20 points)
    const hasDecisions = handoffContent.includes('## Key Decisions Made');
    if (hasDecisions) {
      validation.score += 20;
      validation.strengths.push('Key decisions documented');
    } else {
      validation.issues.push('Key decisions not documented');
    }

    // Check next actions (15 points)
    const hasNextActions = handoffContent.includes('## Next Actions for') &&
                          handoffContent.includes('- [ ]');
    if (hasNextActions) {
      validation.score += 15;
      validation.strengths.push('Clear next actions defined');
    } else {
      validation.issues.push('Next actions unclear or missing');
    }

    // Check references (10 points)
    const hasReferences = handoffContent.includes('## Files and References');
    if (hasReferences) {
      validation.score += 10;
      validation.strengths.push('File references provided');
    } else {
      validation.issues.push('File references missing');
    }

    validation.grade = this.scoreToGrade(validation.score);

    return validation;
  }

  scoreToGrade(score) {
    if (score >= 90) return 'A';
    if (score >= 80) return 'B';
    if (score >= 70) return 'C';
    if (score >= 60) return 'D';
    return 'F';
  }

  calculateHandoffScore(context, agentType) {
    let score = 50; // Base score

    // Add points for context richness
    if (context.shared.currentFocus) score += 10;
    if (context.decisions.length > 0) score += 15;
    if (context.progress.currentStory) score += 10;
    if (context.quality.overallQuality) score += 10;
    if (context.relevantContent.length > 0) score += 5;

    return Math.min(score, 100);
  }

  async updateHandoffRegistry(handoffId, sourceAgent, targetAgent, validation) {
    try {
      const registryFile = path.join(this.handoffsPath, 'handoff-registry.json');
      let registry = [];

      if (fs.existsSync(registryFile)) {
        const content = fs.readFileSync(registryFile, 'utf8');
        registry = JSON.parse(content);
      }

      registry.push({
        handoffId,
        sourceAgent,
        targetAgent,
        timestamp: new Date().toISOString(),
        validationScore: validation.score,
        grade: validation.grade,
        status: 'pending'
      });

      // Keep only last 100 handoffs
      if (registry.length > 100) {
        registry = registry.slice(-100);
      }

      fs.writeFileSync(registryFile, JSON.stringify(registry, null, 2));
    } catch (error) {
      console.error('Failed to update handoff registry:', error.message);
    }
  }

  async logHandoffEvent(event) {
    try {
      const auditFile = path.join(this.handoffsPath, 'audit-trail.md');
      let auditContent = '';

      if (fs.existsSync(auditFile)) {
        auditContent = fs.readFileSync(auditFile, 'utf8');
      } else {
        auditContent = '# Handoff Audit Trail\n\n';
      }

      const logEntry = `## Handoff ${event.handoffId}
**Timestamp:** ${event.timestamp}
**Source:** ${event.sourceAgent}
**Target:** ${event.targetAgent}
**Status:** ${event.status}
**Validation Score:** ${event.validationScore}/100
**File:** ${event.filePath}

---

`;

      auditContent += logEntry;
      fs.writeFileSync(auditFile, auditContent);
    } catch (error) {
      console.error('Failed to log handoff event:', error.message);
    }
  }

  async getPendingHandoffs(targetAgent = null) {
    try {
      const registryFile = path.join(this.handoffsPath, 'handoff-registry.json');

      if (!fs.existsSync(registryFile)) {
        return [];
      }

      const content = fs.readFileSync(registryFile, 'utf8');
      const registry = JSON.parse(content);

      let pending = registry.filter(handoff => handoff.status === 'pending');

      if (targetAgent) {
        pending = pending.filter(handoff => handoff.targetAgent === targetAgent);
      }

      return pending.sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));
    } catch (error) {
      console.error('Failed to get pending handoffs:', error.message);
      return [];
    }
  }

  async getHandoffStats() {
    try {
      const registryFile = path.join(this.handoffsPath, 'handoff-registry.json');

      if (!fs.existsSync(registryFile)) {
        return { total: 0, pending: 0, avgScore: 0, gradeDistribution: {} };
      }

      const content = fs.readFileSync(registryFile, 'utf8');
      const registry = JSON.parse(content);

      const stats = {
        total: registry.length,
        pending: registry.filter(h => h.status === 'pending').length,
        avgScore: registry.reduce((sum, h) => sum + h.validationScore, 0) / registry.length,
        gradeDistribution: {}
      };

      // Calculate grade distribution
      registry.forEach(handoff => {
        stats.gradeDistribution[handoff.grade] = (stats.gradeDistribution[handoff.grade] || 0) + 1;
      });

      return stats;
    } catch (error) {
      console.error('Failed to get handoff stats:', error.message);
      return { total: 0, pending: 0, avgScore: 0, gradeDistribution: {} };
    }
  }
}

module.exports = HandoffManager;

const fs = require("fs-extra");
const path = require("path");
const crypto = require("crypto");
const yaml = require("js-yaml");
const chalk = require("chalk");
const { createReadStream, createWriteStream, promises: fsPromises } = require('fs');
const { pipeline } = require('stream/promises');
const resourceLocator = require('./resource-locator');

class FileManager {
  constructor() {
    this.manifestDir = ".bmad-core";
    this.manifestFile = "install-manifest.yaml";
  }

  async copyFile(source, destination) {
    try {
      await fs.ensureDir(path.dirname(destination));

      // Use streaming for large files (> 10MB)
      const stats = await fs.stat(source);
      if (stats.size > 10 * 1024 * 1024) {
        await pipeline(
          createReadStream(source),
          createWriteStream(destination)
        );
      } else {
        await fs.copy(source, destination);
      }
      return true;
    } catch (error) {
      console.error(chalk.red(`Failed to copy ${source}:`), error.message);
      return false;
    }
  }

  async copyDirectory(source, destination) {
    try {
      await fs.ensureDir(destination);

      // Use streaming copy for large directories
      const files = await resourceLocator.findFiles('**/*', {
        cwd: source,
        nodir: true
      });

      // Process files in batches to avoid memory issues
      const batchSize = 50;
      for (let i = 0; i < files.length; i += batchSize) {
        const batch = files.slice(i, i + batchSize);
        await Promise.all(
          batch.map(file => 
            this.copyFile(
              path.join(source, file),
              path.join(destination, file)
            )
          )
        );
      }
      return true;
    } catch (error) {
      console.error(
        chalk.red(`Failed to copy directory ${source}:`),
        error.message
      );
      return false;
    }
  }

  async copyGlobPattern(pattern, sourceDir, destDir, rootValue = null) {
    const files = await resourceLocator.findFiles(pattern, { cwd: sourceDir });
    const copied = [];

    for (const file of files) {
      const sourcePath = path.join(sourceDir, file);
      const destPath = path.join(destDir, file);

      // Use root replacement if rootValue is provided and file needs it
      const needsRootReplacement = rootValue && (file.endsWith('.md') || file.endsWith('.yaml') || file.endsWith('.yml'));

      let success = false;
      if (needsRootReplacement) {
        success = await this.copyFileWithRootReplacement(sourcePath, destPath, rootValue);
      } else {
        success = await this.copyFile(sourcePath, destPath);
      }

      if (success) {
        copied.push(file);
      }
    }

    return copied;
  }

  async calculateFileHash(filePath) {
    try {
      // Use streaming for hash calculation to reduce memory usage
      const stream = createReadStream(filePath);
      const hash = crypto.createHash("sha256");

      for await (const chunk of stream) {
        hash.update(chunk);
      }

      return hash.digest("hex").slice(0, 16);
    } catch (error) {
      return null;
    }
  }

  async createManifest(installDir, config, files) {
    const manifestPath = path.join(
      installDir,
      this.manifestDir,
      this.manifestFile
    );

    // Read version from package.json
    let coreVersion = "unknown";
    try {
      const packagePath = path.join(__dirname, '..', '..', '..', 'package.json');
      const packageJson = require(packagePath);
      coreVersion = packageJson.version;
    } catch (error) {
      console.warn("Could not read version from package.json, using 'unknown'");
    }

    const manifest = {
      version: coreVersion,
      installed_at: new Date().toISOString(),
      install_type: config.installType,
      agent: config.agent || null,
      ides_setup: config.ides || [],
      expansion_packs: config.expansionPacks || [],
      files: [],
    };

    // Add file information
    for (const file of files) {
      const filePath = path.join(installDir, file);
      const hash = await this.calculateFileHash(filePath);

      manifest.files.push({
        path: file,
        hash: hash,
        modified: false,
      });
    }

    // Write manifest
    await fs.ensureDir(path.dirname(manifestPath));
    await fs.writeFile(manifestPath, yaml.dump(manifest, { indent: 2 }));

    return manifest;
  }

  async readManifest(installDir) {
    const manifestPath = path.join(
      installDir,
      this.manifestDir,
      this.manifestFile
    );

    try {
      const content = await fs.readFile(manifestPath, "utf8");
      return yaml.load(content);
    } catch (error) {
      return null;
    }
  }

  async readExpansionPackManifest(installDir, packId) {
    const manifestPath = path.join(
      installDir,
      `.${packId}`,
      this.manifestFile
    );

    try {
      const content = await fs.readFile(manifestPath, "utf8");
      return yaml.load(content);
    } catch (error) {
      return null;
    }
  }

  async checkModifiedFiles(installDir, manifest) {
    const modified = [];

    for (const file of manifest.files) {
      const filePath = path.join(installDir, file.path);
      const currentHash = await this.calculateFileHash(filePath);

      if (currentHash && currentHash !== file.hash) {
        modified.push(file.path);
      }
    }

    return modified;
  }

  async checkFileIntegrity(installDir, manifest) {
    const result = {
      missing: [],
      modified: []
    };

    for (const file of manifest.files) {
      const filePath = path.join(installDir, file.path);

      // Skip checking the manifest file itself - it will always be different due to timestamps
      if (file.path.endsWith('install-manifest.yaml')) {
        continue;
      }

      if (!(await this.pathExists(filePath))) {
        result.missing.push(file.path);
      } else {
        const currentHash = await this.calculateFileHash(filePath);
        if (currentHash && currentHash !== file.hash) {
          result.modified.push(file.path);
        }
      }
    }

    return result;
  }

  async backupFile(filePath) {
    const backupPath = filePath + ".bak";
    let counter = 1;
    let finalBackupPath = backupPath;

    // Find a unique backup filename
    while (await fs.pathExists(finalBackupPath)) {
      finalBackupPath = `${filePath}.bak${counter}`;
      counter++;
    }

    await fs.copy(filePath, finalBackupPath);
    return finalBackupPath;
  }

  async ensureDirectory(dirPath) {
    try {
      await fs.ensureDir(dirPath);
      return true;
    } catch (error) {
      throw error;
    }
  }

  async pathExists(filePath) {
    return fs.pathExists(filePath);
  }

  async readFile(filePath) {
    return fs.readFile(filePath, "utf8");
  }

  async writeFile(filePath, content) {
    await fs.ensureDir(path.dirname(filePath));
    await fs.writeFile(filePath, content);
  }

  async removeDirectory(dirPath) {
    await fs.remove(dirPath);
  }

  async createExpansionPackManifest(installDir, packId, config, files) {
    const manifestPath = path.join(
      installDir,
      `.${packId}`,
      this.manifestFile
    );

    const manifest = {
      version: config.expansionPackVersion || require("../../../package.json").version,
      installed_at: new Date().toISOString(),
      install_type: config.installType,
      expansion_pack_id: config.expansionPackId,
      expansion_pack_name: config.expansionPackName,
      ides_setup: config.ides || [],
      files: [],
    };

    // Add file information
    for (const file of files) {
      const filePath = path.join(installDir, file);
      const hash = await this.calculateFileHash(filePath);

      manifest.files.push({
        path: file,
        hash: hash,
        modified: false,
      });
    }

    // Write manifest
    await fs.ensureDir(path.dirname(manifestPath));
    await fs.writeFile(manifestPath, yaml.dump(manifest, { indent: 2 }));

    return manifest;
  }

  async modifyCoreConfig(installDir, config) {
    const coreConfigPath = path.join(installDir, '.bmad-core', 'core-config.yaml');

    try {
      // Read the existing core-config.yaml
      const coreConfigContent = await fs.readFile(coreConfigPath, 'utf8');
      const coreConfig = yaml.load(coreConfigContent);

      // Modify sharding settings if provided
      if (config.prdSharded !== undefined) {
        coreConfig.prd.prdSharded = config.prdSharded;
      }

      if (config.architectureSharded !== undefined) {
        coreConfig.architecture.architectureSharded = config.architectureSharded;
      }

      // Write back the modified config
      await fs.writeFile(coreConfigPath, yaml.dump(coreConfig, { indent: 2 }));

      return true;
    } catch (error) {
      console.error(chalk.red(`Failed to modify core-config.yaml:`), error.message);
      return false;
    }
  }

  async copyFileWithRootReplacement(source, destination, rootValue) {
    try {
      // Check file size to determine if we should stream
      const stats = await fs.stat(source);

      if (stats.size > 5 * 1024 * 1024) { // 5MB threshold
        // Use streaming for large files
        const { Transform } = require('stream');
        const replaceStream = new Transform({
          transform(chunk, encoding, callback) {
            const modified = chunk.toString().replace(/\{root\}/g, rootValue);
            callback(null, modified);
          }
        });

        await this.ensureDirectory(path.dirname(destination));
        await pipeline(
          createReadStream(source, { encoding: 'utf8' }),
          replaceStream,
          createWriteStream(destination, { encoding: 'utf8' })
        );
      } else {
        // Regular approach for smaller files
        const content = await fsPromises.readFile(source, 'utf8');
        const updatedContent = content.replace(/\{root\}/g, rootValue);
        await this.ensureDirectory(path.dirname(destination));
        await fsPromises.writeFile(destination, updatedContent, 'utf8');
      }

      return true;
    } catch (error) {
      console.error(chalk.red(`Failed to copy ${source} with root replacement:`), error.message);
      return false;
    }
  }

  async copyDirectoryWithRootReplacement(source, destination, rootValue, fileExtensions = ['.md', '.yaml', '.yml']) {
    try {
      await this.ensureDirectory(destination);

      // Get all files in source directory
      const files = await resourceLocator.findFiles('**/*', { 
        cwd: source, 
        nodir: true 
      });

      let replacedCount = 0;

      for (const file of files) {
        const sourcePath = path.join(source, file);
        const destPath = path.join(destination, file);

        // Check if this file type should have {root} replacement
        const shouldReplace = fileExtensions.some(ext => file.endsWith(ext));

        if (shouldReplace) {
          if (await this.copyFileWithRootReplacement(sourcePath, destPath, rootValue)) {
            replacedCount++;
          }
        } else {
          // Regular copy for files that don't need replacement
          await this.copyFile(sourcePath, destPath);
        }
      }

      if (replacedCount > 0) {
        console.log(chalk.dim(`  Processed ${replacedCount} files with {root} replacement`));
      }

      return true;
    } catch (error) {
      console.error(chalk.red(`Failed to copy directory ${source} with root replacement:`), error.message);
      return false;
    }
  }
}

module.exports = new FileManager();

const fs = require('fs');
const path = require('path');

class ContextManager {
  constructor(workspacePath = null) {
    this.workspacePath = workspacePath || path.join(process.cwd(), '.workspace');
    this.contextPath = path.join(this.workspacePath, 'context');
    this.decisionsPath = path.join(this.workspacePath, 'decisions');
    this.progressPath = path.join(this.workspacePath, 'progress');
    this.qualityPath = path.join(this.workspacePath, 'quality');
    this.archivePath = path.join(this.workspacePath, 'archive');
    this.versionsPath = path.join(this.workspacePath, 'versions');
    this.locksPath = path.join(this.workspacePath, 'locks');

    // Context file size threshold for compaction (10MB default)
    this.maxContextSize = 10 * 1024 * 1024;

    // Context versioning settings
    this.maxVersions = 50; // Keep last 50 versions
    this.conflictResolutionStrategy = 'merge'; // 'merge', 'overwrite', 'manual'

    // Initialize if needed
    this.initialize();
  }

  initialize() {
    // Ensure all context directories exist
    const dirs = [this.contextPath, this.decisionsPath, this.progressPath, this.qualityPath, this.archivePath, this.versionsPath, this.locksPath];
    for (const dir of dirs) {
      if (!fs.existsSync(dir)) {
        fs.mkdirSync(dir, { recursive: true });
      }
    }
  }

  // SHARED CONTEXT MANAGEMENT
  async updateSharedContext(updates) {
    try {
      const contextFile = path.join(this.contextPath, 'shared-context.md');
      let context = await this.loadSharedContext();

      // Merge updates with existing context
      const updatedContext = {
        ...context,
        ...updates,
        lastUpdated: new Date().toISOString()
      };

      const contextContent = this.formatSharedContext(updatedContext);
      fs.writeFileSync(contextFile, contextContent);

      // Check if compaction is needed
      await this.checkContextCompaction(contextFile);

      return updatedContext;
    } catch (error) {
      console.error('Failed to update shared context:', error.message);
      throw error;
    }
  }

  async loadSharedContext() {
    try {
      const contextFile = path.join(this.contextPath, 'shared-context.md');

      if (!fs.existsSync(contextFile)) {
        return this.getDefaultSharedContext();
      }

      const content = fs.readFileSync(contextFile, 'utf8');
      return this.parseSharedContext(content);
    } catch (error) {
      console.error('Failed to load shared context:', error.message);
      return this.getDefaultSharedContext();
    }
  }

  getDefaultSharedContext() {
    return {
      lastUpdated: new Date().toISOString(),
      activeSessions: [],
      primaryAgent: 'unknown',
      currentFocus: 'No active development focus',
      keyDecisions: [],
      nextSteps: [],
      sessionNotes: ''
    };
  }

  formatSharedContext(context) {
    return `# Workspace Context

**Last Updated:** ${context.lastUpdated}
**Active Sessions:** ${context.activeSessions.join(', ') || 'None'}
**Primary Agent:** ${context.primaryAgent}

## Current Focus
${context.currentFocus}

## Key Decisions
${context.keyDecisions.map(decision => `- ${decision}`).join('\n') || '- No decisions recorded yet'}

## Next Steps
${context.nextSteps.map(step => `- ${step}`).join('\n') || '- No next steps defined yet'}

## Session Notes
${context.sessionNotes || 'No session notes available'}
`;
  }

  parseSharedContext(content) {
    const context = this.getDefaultSharedContext();

    try {
      // Extract metadata
      const lastUpdatedMatch = content.match(/\*\*Last Updated:\*\* (.+)/);
      if (lastUpdatedMatch) context.lastUpdated = lastUpdatedMatch[1];

      const activeSessionsMatch = content.match(/\*\*Active Sessions:\*\* (.+)/);
      if (activeSessionsMatch && activeSessionsMatch[1] !== 'None') {
        context.activeSessions = activeSessionsMatch[1].split(', ').map(s => s.trim());
      }

      const primaryAgentMatch = content.match(/\*\*Primary Agent:\*\* (.+)/);
      if (primaryAgentMatch) context.primaryAgent = primaryAgentMatch[1];

      // Extract sections
      const currentFocusMatch = content.match(/## Current Focus\n([\s\S]*?)(?=\n## |$)/);
      if (currentFocusMatch) context.currentFocus = currentFocusMatch[1].trim();

      const keyDecisionsMatch = content.match(/## Key Decisions\n([\s\S]*?)(?=\n## |$)/);
      if (keyDecisionsMatch) {
        context.keyDecisions = keyDecisionsMatch[1]
          .split('\n')
          .filter(line => line.startsWith('- '))
          .map(line => line.substring(2).trim())
          .filter(decision => decision && !decision.includes('No decisions recorded'));
      }

      const nextStepsMatch = content.match(/## Next Steps\n([\s\S]*?)(?=\n## |$)/);
      if (nextStepsMatch) {
        context.nextSteps = nextStepsMatch[1]
          .split('\n')
          .filter(line => line.startsWith('- '))
          .map(line => line.substring(2).trim())
          .filter(step => step && !step.includes('No next steps defined'));
      }

      const sessionNotesMatch = content.match(/## Session Notes\n([\s\S]*?)$/);
      if (sessionNotesMatch) context.sessionNotes = sessionNotesMatch[1].trim();

    } catch (error) {
      console.warn('Failed to parse shared context, using defaults:', error.message);
    }

    return context;
  }

  // DECISIONS LOGGING
  async logDecision(decision) {
    try {
      const decisionsFile = path.join(this.decisionsPath, 'decisions-log.md');
      let existingContent = '';

      if (fs.existsSync(decisionsFile)) {
        existingContent = fs.readFileSync(decisionsFile, 'utf8');
      } else {
        existingContent = '# Architectural & Design Decisions\n\n';
      }

      // Generate decision ID
      const decisionCount = (existingContent.match(/## Decision \d+:/g) || []).length;
      const decisionId = String(decisionCount + 1).padStart(3, '0');

      const decisionEntry = `## Decision ${decisionId}: ${decision.title}
**Date:** ${decision.date || new Date().toISOString()}
**Agent:** ${decision.agent || 'unknown'}
**Context:** ${decision.context || 'No context provided'}
**Decision:** ${decision.decision}
**Rationale:** ${decision.rationale || 'No rationale provided'}
**Alternatives:** ${decision.alternatives || 'No alternatives considered'}
**Impact:** ${decision.impact || 'Impact not assessed'}
**Status:** ${decision.status || 'active'}

`;

      const updatedContent = existingContent + decisionEntry;
      fs.writeFileSync(decisionsFile, updatedContent);

      // Update shared context with new decision
      const context = await this.loadSharedContext();
      context.keyDecisions.push(`${decision.title} (${decision.date || new Date().toISOString().split('T')[0]})`);
      await this.updateSharedContext(context);

      return decisionId;
    } catch (error) {
      console.error('Failed to log decision:', error.message);
      throw error;
    }
  }

  async getDecisions(filters = {}) {
    try {
      const decisionsFile = path.join(this.decisionsPath, 'decisions-log.md');

      if (!fs.existsSync(decisionsFile)) {
        return [];
      }

      const content = fs.readFileSync(decisionsFile, 'utf8');
      const decisions = this.parseDecisions(content);

      // Apply filters
      let filteredDecisions = decisions;

      if (filters.agent) {
        filteredDecisions = filteredDecisions.filter(d => d.agent === filters.agent);
      }

      if (filters.status) {
        filteredDecisions = filteredDecisions.filter(d => d.status === filters.status);
      }

      if (filters.dateFrom) {
        const fromDate = new Date(filters.dateFrom);
        filteredDecisions = filteredDecisions.filter(d => new Date(d.date) >= fromDate);
      }

      if (filters.dateTo) {
        const toDate = new Date(filters.dateTo);
        filteredDecisions = filteredDecisions.filter(d => new Date(d.date) <= toDate);
      }

      return filteredDecisions;
    } catch (error) {
      console.error('Failed to get decisions:', error.message);
      return [];
    }
  }

  parseDecisions(content) {
    const decisions = [];
    const decisionBlocks = content.split(/## Decision \d+:/);

    for (let i = 1; i < decisionBlocks.length; i++) {
      try {
        const block = decisionBlocks[i];
        const lines = block.split('\n');

        const decision = {
          id: `${i.toString().padStart(3, '0')}`,
          title: lines[0].trim(),
          date: this.extractField(block, 'Date'),
          agent: this.extractField(block, 'Agent'),
          context: this.extractField(block, 'Context'),
          decision: this.extractField(block, 'Decision'),
          rationale: this.extractField(block, 'Rationale'),
          alternatives: this.extractField(block, 'Alternatives'),
          impact: this.extractField(block, 'Impact'),
          status: this.extractField(block, 'Status')
        };

        decisions.push(decision);
      } catch (error) {
        console.warn(`Failed to parse decision block ${i}:`, error.message);
      }
    }

    return decisions;
  }

  extractField(content, fieldName) {
    const regex = new RegExp(`\\*\\*${fieldName}:\\*\\* (.+)`, 'i');
    const match = content.match(regex);
    return match ? match[1].trim() : '';
  }

  // PROGRESS TRACKING
  async updateProgress(progressUpdate) {
    try {
      const progressFile = path.join(this.progressPath, 'progress-summary.md');
      let progress = await this.loadProgress();

      // Merge updates
      const updatedProgress = {
        ...progress,
        ...progressUpdate,
        lastUpdated: new Date().toISOString()
      };

      const progressContent = this.formatProgress(updatedProgress);
      fs.writeFileSync(progressFile, progressContent);

      // Update shared context
      const context = await this.loadSharedContext();
      if (progressUpdate.currentStory) {
        context.currentFocus = progressUpdate.currentStory;
      }
      if (progressUpdate.nextSteps) {
        context.nextSteps = progressUpdate.nextSteps;
      }
      await this.updateSharedContext(context);

      return updatedProgress;
    } catch (error) {
      console.error('Failed to update progress:', error.message);
      throw error;
    }
  }

  async loadProgress() {
    try {
      const progressFile = path.join(this.progressPath, 'progress-summary.md');

      if (!fs.existsSync(progressFile)) {
        return this.getDefaultProgress();
      }

      const content = fs.readFileSync(progressFile, 'utf8');
      return this.parseProgress(content);
    } catch (error) {
      console.error('Failed to load progress:', error.message);
      return this.getDefaultProgress();
    }
  }

  getDefaultProgress() {
    return {
      lastUpdated: new Date().toISOString(),
      currentStory: 'No active story',
      completedTasks: [],
      pendingTasks: [],
      blockers: [],
      qualityScore: 'Not assessed'
    };
  }

  formatProgress(progress) {
    return `# Development Progress Summary

**Last Updated:** ${progress.lastUpdated}
**Current Story:** ${progress.currentStory}
**Quality Score:** ${progress.qualityScore}

## Completed Tasks
${progress.completedTasks.map(task => `- ✅ ${task}`).join('\n') || '- No tasks completed yet'}

## Pending Tasks
${progress.pendingTasks.map(task => `- ⏳ ${task}`).join('\n') || '- No pending tasks'}

## Blockers
${progress.blockers.map(blocker => `- 🚫 ${blocker}`).join('\n') || '- No blockers identified'}
`;
  }

  parseProgress(content) {
    const progress = this.getDefaultProgress();

    try {
      // Extract metadata
      const lastUpdatedMatch = content.match(/\*\*Last Updated:\*\* (.+)/);
      if (lastUpdatedMatch) progress.lastUpdated = lastUpdatedMatch[1];

      const currentStoryMatch = content.match(/\*\*Current Story:\*\* (.+)/);
      if (currentStoryMatch) progress.currentStory = currentStoryMatch[1];

      const qualityScoreMatch = content.match(/\*\*Quality Score:\*\* (.+)/);
      if (qualityScoreMatch) progress.qualityScore = qualityScoreMatch[1];

      // Extract task lists
      const completedMatch = content.match(/## Completed Tasks\n([\s\S]*?)(?=\n## |$)/);
      if (completedMatch) {
        progress.completedTasks = completedMatch[1]
          .split('\n')
          .filter(line => line.startsWith('- ✅'))
          .map(line => line.substring(4).trim())
          .filter(task => task && !task.includes('No tasks completed'));
      }

      const pendingMatch = content.match(/## Pending Tasks\n([\s\S]*?)(?=\n## |$)/);
      if (pendingMatch) {
        progress.pendingTasks = pendingMatch[1]
          .split('\n')
          .filter(line => line.startsWith('- ⏳'))
          .map(line => line.substring(4).trim())
          .filter(task => task && !task.includes('No pending tasks'));
      }

      const blockersMatch = content.match(/## Blockers\n([\s\S]*?)$/);
      if (blockersMatch) {
        progress.blockers = blockersMatch[1]
          .split('\n')
          .filter(line => line.startsWith('- 🚫'))
          .map(line => line.substring(4).trim())
          .filter(blocker => blocker && !blocker.includes('No blockers'));
      }

    } catch (error) {
      console.warn('Failed to parse progress, using defaults:', error.message);
    }

    return progress;
  }

  // QUALITY METRICS
  async updateQualityMetrics(metrics) {
    try {
      const qualityFile = path.join(this.qualityPath, 'quality-metrics.md');
      const timestamp = new Date().toISOString();

      let existingContent = '';
      if (fs.existsSync(qualityFile)) {
        existingContent = fs.readFileSync(qualityFile, 'utf8');
      } else {
        existingContent = '# Quality Metrics History\n\n';
      }

      const metricsEntry = `## Quality Assessment - ${timestamp}
**Agent:** ${metrics.agent || 'unknown'}
**Story:** ${metrics.story || 'unknown'}
**Reality Audit Score:** ${metrics.realityAuditScore || 'N/A'}
**Pattern Compliance:** ${metrics.patternCompliance || 'N/A'}
**Technical Debt Score:** ${metrics.technicalDebtScore || 'N/A'}
**Overall Quality:** ${metrics.overallQuality || 'N/A'}

**Details:**
${metrics.details || 'No additional details provided'}

---

`;

      const updatedContent = existingContent + metricsEntry;
      fs.writeFileSync(qualityFile, updatedContent);

      // Update progress with quality score
      const progress = await this.loadProgress();
      progress.qualityScore = metrics.overallQuality || metrics.realityAuditScore || 'Updated';
      await this.updateProgress(progress);

      return metrics;
    } catch (error) {
      console.error('Failed to update quality metrics:', error.message);
      throw error;
    }
  }

  async getLatestQualityMetrics() {
    try {
      const qualityFile = path.join(this.qualityPath, 'quality-metrics.md');

      if (!fs.existsSync(qualityFile)) {
        return null;
      }

      const content = fs.readFileSync(qualityFile, 'utf8');
      const assessments = content.split('## Quality Assessment -');

      if (assessments.length < 2) {
        return null;
      }

      // Get the most recent assessment
      const latestAssessment = assessments[1];

      return {
        timestamp: latestAssessment.split('\n')[0].trim(),
        agent: this.extractField(latestAssessment, 'Agent'),
        story: this.extractField(latestAssessment, 'Story'),
        realityAuditScore: this.extractField(latestAssessment, 'Reality Audit Score'),
        patternCompliance: this.extractField(latestAssessment, 'Pattern Compliance'),
        technicalDebtScore: this.extractField(latestAssessment, 'Technical Debt Score'),
        overallQuality: this.extractField(latestAssessment, 'Overall Quality'),
        details: this.extractField(latestAssessment, 'Details')
      };
    } catch (error) {
      console.error('Failed to get latest quality metrics:', error.message);
      return null;
    }
  }

  // CONTEXT COMPACTION
  async checkContextCompaction(filePath) {
    try {
      const stats = fs.statSync(filePath);

      if (stats.size > this.maxContextSize) {
        await this.compactContext(filePath);
      }
    } catch (error) {
      console.error('Failed to check context compaction:', error.message);
    }
  }

  async compactContext(filePath) {
    try {
      const fileName = path.basename(filePath);
      const archiveFileName = `archived-${Date.now()}-${fileName}`;
      const archiveFilePath = path.join(this.archivePath, archiveFileName);

      // Move original to archive
      const originalContent = fs.readFileSync(filePath, 'utf8');
      fs.writeFileSync(archiveFilePath, originalContent);

      // Create summarized version
      const summarizedContent = await this.summarizeContext(originalContent, fileName);
      fs.writeFileSync(filePath, summarizedContent);

      console.log(`Context compacted: ${fileName} archived as ${archiveFileName}`);
    } catch (error) {
      console.error('Failed to compact context:', error.message);
    }
  }

  async summarizeContext(content, fileName) {
    // Intelligent summarization preserving key decisions and recent activity
    const timestamp = new Date().toISOString();

    if (fileName === 'shared-context.md') {
      const context = this.parseSharedContext(content);

      // Keep only most recent 5 decisions and next steps
      context.keyDecisions = context.keyDecisions.slice(-5);
      context.nextSteps = context.nextSteps.slice(-5);
      context.sessionNotes = `[Archived ${timestamp}] Context compacted - full history available in archive.`;

      return this.formatSharedContext(context);
    }

    // For other file types, create a basic summary
    return `# ${fileName.replace('.md', '')} - Compacted Summary

**Compacted:** ${timestamp}
**Original Size:** ${content.length} characters

This file was automatically compacted to manage size. Full historical context is available in the archive directory.

**Recent Activity Summary:**
${content.substring(content.length - 1000)} 

[Full historical context archived - use archive restoration if detailed history is needed]
`;
  }

  // SESSION INTEGRATION
  async onSessionStart(sessionId, agent) {
    try {
      const context = await this.loadSharedContext();

      if (!context.activeSessions.includes(sessionId)) {
        context.activeSessions.push(sessionId);
      }

      context.primaryAgent = agent;
      context.sessionNotes = `Session ${sessionId} started by ${agent} at ${new Date().toISOString()}`;

      await this.updateSharedContext(context);
    } catch (error) {
      console.error('Failed to handle session start:', error.message);
    }
  }

  async onSessionEnd(sessionId) {
    try {
      const context = await this.loadSharedContext();

      context.activeSessions = context.activeSessions.filter(id => id !== sessionId);
      context.sessionNotes += `\nSession ${sessionId} ended at ${new Date().toISOString()}`;

      await this.updateSharedContext(context);
    } catch (error) {
      console.error('Failed to handle session end:', error.message);
    }
  }

  // UTILITY METHODS
  async getWorkspaceStatus() {
    try {
      const context = await this.loadSharedContext();
      const progress = await this.loadProgress();
      const latestQuality = await this.getLatestQualityMetrics();
      const recentDecisions = await this.getDecisions({ dateFrom: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString() });

      return {
        context,
        progress,
        latestQuality,
        recentDecisions: recentDecisions.slice(-5)
      };
    } catch (error) {
      console.error('Failed to get workspace status:', error.message);
      return null;
    }
  }

  async exportContextSummary() {
    try {
      const status = await this.getWorkspaceStatus();

      return `# Workspace Context Export
**Generated:** ${new Date().toISOString()}

## Current Status
- **Primary Agent:** ${status.context.primaryAgent}
- **Active Sessions:** ${status.context.activeSessions.join(', ') || 'None'}
- **Current Focus:** ${status.context.currentFocus}
- **Quality Score:** ${status.progress.qualityScore}

## Recent Decisions (Last 7 Days)
${status.recentDecisions.map(d => `- ${d.title} (${d.agent})`).join('\n') || '- No recent decisions'}

## Progress Summary
- **Completed Tasks:** ${status.progress.completedTasks.length}
- **Pending Tasks:** ${status.progress.pendingTasks.length}
- **Blockers:** ${status.progress.blockers.length}

## Next Steps
${status.context.nextSteps.map(step => `- ${step}`).join('\n') || '- No next steps defined'}
`;
    } catch (error) {
      console.error('Failed to export context summary:', error.message);
      return 'Error generating context summary';
    }
  }

  // CONTEXT VERSIONING AND CONFLICT RESOLUTION
  async createContextVersion(contextType, content, sessionId, agent) {
    try {
      const timestamp = new Date().toISOString();
      const versionId = `${contextType}-${timestamp.replace(/[:.]/g, '-')}-${sessionId}`;
      const versionFile = path.join(this.versionsPath, `${versionId}.json`);

      const version = {
        id: versionId,
        contextType,
        timestamp,
        sessionId,
        agent,
        content,
        hash: this.generateContentHash(content)
      };

      fs.writeFileSync(versionFile, JSON.stringify(version, null, 2));

      // Cleanup old versions
      await this.cleanupOldVersions(contextType);

      return versionId;
    } catch (error) {
      console.error('Failed to create context version:', error.message);
      throw error;
    }
  }

  generateContentHash(content) {
    // Simple hash function for content comparison
    let hash = 0;
    if (content.length === 0) return hash;
    for (let i = 0; i < content.length; i++) {
      const char = content.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash; // Convert to 32-bit integer
    }
    return hash.toString();
  }

  async cleanupOldVersions(contextType) {
    try {
      const versionFiles = fs.readdirSync(this.versionsPath)
        .filter(file => file.startsWith(contextType) && file.endsWith('.json'))
        .map(file => {
          const filePath = path.join(this.versionsPath, file);
          const stats = fs.statSync(filePath);
          return { file, path: filePath, mtime: stats.mtime };
        })
        .sort((a, b) => b.mtime - a.mtime);

      // Keep only the most recent versions
      if (versionFiles.length > this.maxVersions) {
        const filesToDelete = versionFiles.slice(this.maxVersions);
        for (const fileInfo of filesToDelete) {
          fs.unlinkSync(fileInfo.path);
        }
      }
    } catch (error) {
      console.error('Failed to cleanup old versions:', error.message);
    }
  }

  async detectContextConflicts(contextType, newContent, sessionId) {
    try {
      const currentContextFile = path.join(this.getContextFilePath(contextType));

      if (!fs.existsSync(currentContextFile)) {
        return { hasConflict: false, conflict: null };
      }

      const currentContent = fs.readFileSync(currentContextFile, 'utf8');
      const currentHash = this.generateContentHash(currentContent);
      const newHash = this.generateContentHash(newContent);

      if (currentHash === newHash) {
        return { hasConflict: false, conflict: null };
      }

      // Check if there are concurrent modifications
      const recentVersions = await this.getRecentVersions(contextType, 5);
      const concurrentVersions = recentVersions.filter(v => 
        v.sessionId !== sessionId && 
        new Date() - new Date(v.timestamp) < 5 * 60 * 1000 // Within last 5 minutes
      );

      if (concurrentVersions.length > 0) {
        return {
          hasConflict: true,
          conflict: {
            type: 'concurrent_modification',
            currentContent,
            newContent,
            concurrentVersions
          }
        };
      }

      return { hasConflict: false, conflict: null };
    } catch (error) {
      console.error('Failed to detect context conflicts:', error.message);
      return { hasConflict: false, conflict: null };
    }
  }

  getContextFilePath(contextType) {
    switch (contextType) {
      case 'shared-context': return path.join(this.contextPath, 'shared-context.md');
      case 'decisions': return path.join(this.decisionsPath, 'decisions-log.md');
      case 'progress': return path.join(this.progressPath, 'progress-summary.md');
      case 'quality': return path.join(this.qualityPath, 'quality-metrics.md');
      default: return path.join(this.contextPath, `${contextType}.md`);
    }
  }

  async getRecentVersions(contextType, limit = 10) {
    try {
      const versionFiles = fs.readdirSync(this.versionsPath)
        .filter(file => file.startsWith(contextType) && file.endsWith('.json'))
        .map(file => {
          const filePath = path.join(this.versionsPath, file);
          const content = JSON.parse(fs.readFileSync(filePath, 'utf8'));
          return content;
        })
        .sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp))
        .slice(0, limit);

      return versionFiles;
    } catch (error) {
      console.error('Failed to get recent versions:', error.message);
      return [];
    }
  }

  async mergeContextChanges(contextType, baseContent, changes1, changes2) {
    try {
      // Simple merge strategy - combine unique elements
      switch (contextType) {
        case 'shared-context':
          return this.mergeSharedContext(baseContent, changes1, changes2);
        case 'decisions':
          return this.mergeDecisions(baseContent, changes1, changes2);
        case 'progress':
          return this.mergeProgress(baseContent, changes1, changes2);
        default:
          // Default merge - prefer more recent changes
          return changes2.timestamp > changes1.timestamp ? changes2.content : changes1.content;
      }
    } catch (error) {
      console.error('Failed to merge context changes:', error.message);
      throw error;
    }
  }

  mergeSharedContext(base, changes1, changes2) {
    try {
      const baseCtx = this.parseSharedContext(base);
      const ctx1 = this.parseSharedContext(changes1.content);
      const ctx2 = this.parseSharedContext(changes2.content);

      // Merge strategy: combine unique items, prefer most recent timestamps
      const merged = {
        lastUpdated: new Date().toISOString(),
        activeSessions: [...new Set([...ctx1.activeSessions, ...ctx2.activeSessions])],
        primaryAgent: ctx2.lastUpdated > ctx1.lastUpdated ? ctx2.primaryAgent : ctx1.primaryAgent,
        currentFocus: ctx2.lastUpdated > ctx1.lastUpdated ? ctx2.currentFocus : ctx1.currentFocus,
        keyDecisions: [...new Set([...ctx1.keyDecisions, ...ctx2.keyDecisions])],
        nextSteps: [...new Set([...ctx1.nextSteps, ...ctx2.nextSteps])],
        sessionNotes: `${ctx1.sessionNotes}\n${ctx2.sessionNotes}`.trim()
      };

      return this.formatSharedContext(merged);
    } catch (error) {
      console.error('Failed to merge shared context:', error.message);
      return changes2.content; // Fallback to most recent
    }
  }

  mergeDecisions(base, changes1, changes2) {
    try {
      // Decisions are append-only, so merge by combining unique decisions
      const decisions1 = this.parseDecisions(changes1.content);
      const decisions2 = this.parseDecisions(changes2.content);

      const allDecisions = [...decisions1, ...decisions2];
      const uniqueDecisions = allDecisions.filter((decision, index, self) => 
        index === self.findIndex(d => d.title === decision.title)
      );

      // Sort by date
      uniqueDecisions.sort((a, b) => new Date(a.date) - new Date(b.date));

      let mergedContent = '# Architectural & Design Decisions\n\n';
      uniqueDecisions.forEach((decision, index) => {
        const decisionId = String(index + 1).padStart(3, '0');
        mergedContent += `## Decision ${decisionId}: ${decision.title}
**Date:** ${decision.date}
**Agent:** ${decision.agent}
**Context:** ${decision.context}
**Decision:** ${decision.decision}
**Rationale:** ${decision.rationale}
**Alternatives:** ${decision.alternatives}
**Impact:** ${decision.impact}
**Status:** ${decision.status}

`;
      });

      return mergedContent;
    } catch (error) {
      console.error('Failed to merge decisions:', error.message);
      return changes2.content; // Fallback to most recent
    }
  }

  mergeProgress(base, changes1, changes2) {
    try {
      const progress1 = this.parseProgress(changes1.content);
      const progress2 = this.parseProgress(changes2.content);

      // Merge strategy: combine tasks, keep most recent story and quality score
      const merged = {
        lastUpdated: new Date().toISOString(),
        currentStory: progress2.lastUpdated > progress1.lastUpdated ? progress2.currentStory : progress1.currentStory,
        completedTasks: [...new Set([...progress1.completedTasks, ...progress2.completedTasks])],
        pendingTasks: [...new Set([...progress1.pendingTasks, ...progress2.pendingTasks])],
        blockers: [...new Set([...progress1.blockers, ...progress2.blockers])],
        qualityScore: progress2.lastUpdated > progress1.lastUpdated ? progress2.qualityScore : progress1.qualityScore
      };

      return this.formatProgress(merged);
    } catch (error) {
      console.error('Failed to merge progress:', error.message);
      return changes2.content; // Fallback to most recent
    }
  }

  async rollbackToVersion(contextType, versionId) {
    try {
      const versionFile = path.join(this.versionsPath, `${versionId}.json`);

      if (!fs.existsSync(versionFile)) {
        throw new Error(`Version ${versionId} not found`);
      }

      const version = JSON.parse(fs.readFileSync(versionFile, 'utf8'));
      const contextFile = this.getContextFilePath(contextType);

      // Create backup of current version
      await this.createContextVersion(contextType, fs.readFileSync(contextFile, 'utf8'), 'system', 'rollback-backup');

      // Restore the version
      fs.writeFileSync(contextFile, version.content);

      return {
        success: true,
        rolledBackTo: version.timestamp,
        agent: version.agent,
        sessionId: version.sessionId
      };
    } catch (error) {
      console.error('Failed to rollback to version:', error.message);
      throw error;
    }
  }

  // CONTEXT LOCKING FOR CONCURRENT ACCESS
  async acquireContextLock(contextType, sessionId, timeout = 30000) {
    try {
      const lockFile = path.join(this.locksPath, `${contextType}.lock`);
      const lockInfo = {
        sessionId,
        timestamp: new Date().toISOString(),
        expires: new Date(Date.now() + timeout).toISOString()
      };

      // Check for existing lock
      if (fs.existsSync(lockFile)) {
        const existingLock = JSON.parse(fs.readFileSync(lockFile, 'utf8'));

        // Check if lock has expired
        if (new Date(existingLock.expires) > new Date()) {
          if (existingLock.sessionId !== sessionId) {
            return { acquired: false, lockedBy: existingLock.sessionId, expiresAt: existingLock.expires };
          }
          // Same session, extend the lock
          lockInfo.timestamp = existingLock.timestamp;
        }
      }

      fs.writeFileSync(lockFile, JSON.stringify(lockInfo, null, 2));

      return { acquired: true, lockInfo };
    } catch (error) {
      console.error('Failed to acquire context lock:', error.message);
      return { acquired: false, error: error.message };
    }
  }

  async releaseContextLock(contextType, sessionId) {
    try {
      const lockFile = path.join(this.locksPath, `${contextType}.lock`);

      if (!fs.existsSync(lockFile)) {
        return { released: true, message: 'No lock existed' };
      }

      const existingLock = JSON.parse(fs.readFileSync(lockFile, 'utf8'));

      if (existingLock.sessionId !== sessionId) {
        return { released: false, message: 'Lock owned by different session' };
      }

      fs.unlinkSync(lockFile);

      return { released: true, message: 'Lock released successfully' };
    } catch (error) {
      console.error('Failed to release context lock:', error.message);
      return { released: false, error: error.message };
    }
  }

  async cleanupExpiredLocks() {
    try {
      const lockFiles = fs.readdirSync(this.locksPath).filter(f => f.endsWith('.lock'));
      let cleanedCount = 0;

      for (const lockFile of lockFiles) {
        const lockPath = path.join(this.locksPath, lockFile);
        const lock = JSON.parse(fs.readFileSync(lockPath, 'utf8'));

        if (new Date(lock.expires) < new Date()) {
          fs.unlinkSync(lockPath);
          cleanedCount++;
        }
      }

      return { cleanedCount };
    } catch (error) {
      console.error('Failed to cleanup expired locks:', error.message);
      return { cleanedCount: 0, error: error.message };
    }
  }

  // BMAD AGENT INTEGRATION HOOKS
  async onStoryStart(storyId, agent, sessionId) {
    try {
      // Automatically update context when a story starts
      await this.updateSharedContext({
        currentFocus: `Story ${storyId} started by ${agent}`,
        primaryAgent: agent
      });

      // Log story start as a progress update
      await this.updateProgress({
        currentStory: storyId,
        lastUpdated: new Date().toISOString()
      });

      console.log(`✅ Context updated for story start: ${storyId} by ${agent}`);
    } catch (error) {
      console.error('Failed to handle story start:', error.message);
    }
  }

  async onDecisionMade(decision, agent, sessionId) {
    try {
      // Automatically log decisions made during agent operations
      await this.logDecision({
        title: decision.title,
        agent: agent,
        context: decision.context || 'Auto-captured during agent operation',
        decision: decision.decision,
        rationale: decision.rationale || 'No rationale provided',
        alternatives: decision.alternatives || 'No alternatives considered',
        impact: decision.impact || 'Impact not assessed',
        status: decision.status || 'active'
      });

      console.log(`✅ Decision auto-logged: ${decision.title} by ${agent}`);
    } catch (error) {
      console.error('Failed to handle decision made:', error.message);
    }
  }

  async onQualityAudit(results, agent, sessionId) {
    try {
      // Automatically capture quality audit results
      await this.updateQualityMetrics({
        agent: agent,
        story: results.story || 'Unknown story',
        realityAuditScore: results.realityAuditScore || results.score,
        patternCompliance: results.patternCompliance,
        technicalDebtScore: results.technicalDebtScore,
        overallQuality: results.overallQuality || results.grade,
        details: results.details || 'Auto-captured quality audit results'
      });

      console.log(`✅ Quality metrics auto-captured: ${results.overallQuality || results.grade} by ${agent}`);
    } catch (error) {
      console.error('Failed to handle quality audit:', error.message);
    }
  }

  async onAgentHandoff(fromAgent, toAgent, sessionId, handoffContext) {
    try {
      // Automatically update context during agent handoffs
      await this.updateSharedContext({
        primaryAgent: toAgent,
        sessionNotes: `Agent handoff: ${fromAgent} → ${toAgent} at ${new Date().toISOString()}`
      });

      // Log handoff as a decision if it includes important context
      if (handoffContext && handoffContext.length > 50) {
        await this.logDecision({
          title: `Agent handoff: ${fromAgent} to ${toAgent}`,
          agent: fromAgent,
          context: 'Agent transition',
          decision: `Handed off work context to ${toAgent}`,
          rationale: handoffContext,
          impact: `${toAgent} can continue work with full context`,
          status: 'active'
        });
      }

      console.log(`✅ Context updated for agent handoff: ${fromAgent} → ${toAgent}`);
    } catch (error) {
      console.error('Failed to handle agent handoff:', error.message);
    }
  }
}

module.exports = ContextManager;

const fs = require('fs-extra');
const path = require('path');
const yaml = require('js-yaml');
const { extractYamlFromAgent } = require('../../lib/yaml-utils');

class ConfigLoader {
  constructor() {
    this.configPath = path.join(__dirname, '..', 'config', 'install.config.yaml');
    this.config = null;
  }

  async load() {
    if (this.config) return this.config;

    try {
      const configContent = await fs.readFile(this.configPath, 'utf8');
      this.config = yaml.load(configContent);
      return this.config;
    } catch (error) {
      throw new Error(`Failed to load configuration: ${error.message}`);
    }
  }

  async getInstallationOptions() {
    const config = await this.load();
    return config['installation-options'] || {};
  }

  async getAvailableAgents() {
    const agentsDir = path.join(this.getBmadCorePath(), 'agents');

    try {
      const entries = await fs.readdir(agentsDir, { withFileTypes: true });
      const agents = [];

      for (const entry of entries) {
        if (entry.isFile() && entry.name.endsWith('.md')) {
          const agentPath = path.join(agentsDir, entry.name);
          const agentId = path.basename(entry.name, '.md');

          try {
            const agentContent = await fs.readFile(agentPath, 'utf8');

            // Extract YAML block from agent file
            const yamlContentText = extractYamlFromAgent(agentContent);
            if (yamlContentText) {
              const yamlContent = yaml.load(yamlContentText);
              const agentConfig = yamlContent.agent || {};

              agents.push({
                id: agentId,
                name: agentConfig.title || agentConfig.name || agentId,
                file: `bmad-core/agents/${entry.name}`,
                description: agentConfig.whenToUse || 'No description available'
              });
            }
          } catch (error) {
            console.warn(`Failed to read agent ${entry.name}: ${error.message}`);
          }
        }
      }

      // Sort agents by name for consistent display
      agents.sort((a, b) => a.name.localeCompare(b.name));

      return agents;
    } catch (error) {
      console.warn(`Failed to read agents directory: ${error.message}`);
      return [];
    }
  }

  async getAvailableExpansionPacks() {
    const expansionPacksDir = path.join(this.getBmadCorePath(), '..', 'expansion-packs');

    try {
      const entries = await fs.readdir(expansionPacksDir, { withFileTypes: true });
      const expansionPacks = [];

      for (const entry of entries) {
        if (entry.isDirectory() && !entry.name.startsWith('.')) {
          const packPath = path.join(expansionPacksDir, entry.name);
          const configPath = path.join(packPath, 'config.yaml');

          try {
            // Read config.yaml
            const configContent = await fs.readFile(configPath, 'utf8');
            const config = yaml.load(configContent);

            expansionPacks.push({
              id: entry.name,
              name: config.name || entry.name,
              description: config['short-title'] || config.description || 'No description available',
              fullDescription: config.description || config['short-title'] || 'No description available',
              version: config.version || '1.0.0',
              author: config.author || 'BMad Team',
              packPath: packPath,
              dependencies: config.dependencies?.agents || []
            });
          } catch (error) {
            // Fallback if config.yaml doesn't exist or can't be read
            console.warn(`Failed to read config for expansion pack ${entry.name}: ${error.message}`);

            // Try to derive info from directory name as fallback
            const name = entry.name
              .split('-')
              .map(word => word.charAt(0).toUpperCase() + word.slice(1))
              .join(' ');

            expansionPacks.push({
              id: entry.name,
              name: name,
              description: 'No description available',
              fullDescription: 'No description available',
              version: '1.0.0',
              author: 'BMad Team',
              packPath: packPath,
              dependencies: []
            });
          }
        }
      }

      return expansionPacks;
    } catch (error) {
      console.warn(`Failed to read expansion packs directory: ${error.message}`);
      return [];
    }
  }

  async getAgentDependencies(agentId) {
    // Use DependencyResolver to dynamically parse agent dependencies
    const DependencyResolver = require('../../lib/dependency-resolver');
    const resolver = new DependencyResolver(path.join(__dirname, '..', '..', '..'));

    const agentDeps = await resolver.resolveAgentDependencies(agentId);

    // Convert to flat list of file paths
    const depPaths = [];

    // Core files and utilities are included automatically by DependencyResolver

    // Add agent file itself is already handled by installer

    // Add all resolved resources
    for (const resource of agentDeps.resources) {
      const filePath = `.bmad-core/${resource.type}/${resource.id}.md`;
      if (!depPaths.includes(filePath)) {
        depPaths.push(filePath);
      }
    }

    return depPaths;
  }

  async getIdeConfiguration(ide) {
    const config = await this.load();
    const ideConfigs = config['ide-configurations'] || {};
    return ideConfigs[ide] || null;
  }

  getBmadCorePath() {
    // Get the path to bmad-core relative to the installer (now under tools)
    return path.join(__dirname, '..', '..', '..', 'bmad-core');
  }

  getDistPath() {
    // Get the path to dist directory relative to the installer
    return path.join(__dirname, '..', '..', '..', 'dist');
  }

  getAgentPath(agentId) {
    return path.join(this.getBmadCorePath(), 'agents', `${agentId}.md`);
  }

  async getAvailableTeams() {
    const teamsDir = path.join(this.getBmadCorePath(), 'agent-teams');

    try {
      const entries = await fs.readdir(teamsDir, { withFileTypes: true });
      const teams = [];

      for (const entry of entries) {
        if (entry.isFile() && entry.name.endsWith('.yaml')) {
          const teamPath = path.join(teamsDir, entry.name);

          try {
            const teamContent = await fs.readFile(teamPath, 'utf8');
            const teamConfig = yaml.load(teamContent);

            if (teamConfig.bundle) {
              teams.push({
                id: path.basename(entry.name, '.yaml'),
                name: teamConfig.bundle.name || entry.name,
                description: teamConfig.bundle.description || 'Team configuration',
                icon: teamConfig.bundle.icon || '📋'
              });
            }
          } catch (error) {
            console.warn(`Warning: Could not load team config ${entry.name}: ${error.message}`);
          }
        }
      }

      return teams;
    } catch (error) {
      console.warn(`Warning: Could not scan teams directory: ${error.message}`);
      return [];
    }
  }

  getTeamPath(teamId) {
    return path.join(this.getBmadCorePath(), 'agent-teams', `${teamId}.yaml`);
  }

  async getTeamDependencies(teamId) {
    // Use DependencyResolver to dynamically parse team dependencies
    const DependencyResolver = require('../../lib/dependency-resolver');
    const resolver = new DependencyResolver(path.join(__dirname, '..', '..', '..'));

    try {
      const teamDeps = await resolver.resolveTeamDependencies(teamId);

      // Convert to flat list of file paths
      const depPaths = [];

      // Add team config file
      depPaths.push(`.bmad-core/agent-teams/${teamId}.yaml`);

      // Add all agents
      for (const agent of teamDeps.agents) {
        const filePath = `.bmad-core/agents/${agent.id}.md`;
        if (!depPaths.includes(filePath)) {
          depPaths.push(filePath);
        }
      }

      // Add all resolved resources
      for (const resource of teamDeps.resources) {
        const filePath = `.bmad-core/${resource.type}/${resource.id}.${resource.type === 'workflows' ? 'yaml' : 'md'}`;
        if (!depPaths.includes(filePath)) {
          depPaths.push(filePath);
        }
      }

      return depPaths;
    } catch (error) {
      throw new Error(`Failed to resolve team dependencies for ${teamId}: ${error.message}`);
    }
  }
}

module.exports = new ConfigLoader();

const ClaudeCodeSessionManager = require('./claude-code-session-manager');
const path = require('path');
const fs = require('fs');

/**
 * Claude Code CLI Native Workspace Commands
 * Provides seamless integration of workspace functionality within Claude Code CLI sessions
 */
class ClaudeCodeWorkspaceCommands {
  constructor(workspaceDir) {
    this.workspaceDir = workspaceDir;
    this.sessionManager = new ClaudeCodeSessionManager(workspaceDir);
    this.commandHistory = [];
  }

  /**
   * Initialize workspace and start session
   */
  async workspaceInit(agentType = 'dev', options = {}) {
    const startTime = Date.now();

    try {
      console.log('🚀 Initializing Claude Code CLI collaborative workspace...');

      // Detect project context
      const projectContext = await this.detectProjectContext();

      // Initialize session
      const sessionResult = await this.sessionManager.initializeSession(agentType, projectContext);

      if (sessionResult.status === 'failed') {
        throw new Error(sessionResult.error);
      }

      // Perform integrity check
      const integrityResults = await this.sessionManager.performIntegrityCheck();

      // Load existing workspace context
      const workspaceContext = await this.sessionManager.loadWorkspaceContext();

      // Register command execution
      this.sessionManager.registerCommandExecution('workspace-init', {
        agentType: agentType,
        options: options,
        projectContext: projectContext
      });

      const duration = Date.now() - startTime;

      console.log('✅ Workspace initialization complete!');
      console.log(`⏱️  Completed in ${duration}ms`);
      console.log('');
      console.log('📋 Session Details:');
      console.log(`   • Session ID: ${sessionResult.sessionId}`);
      console.log(`   • Agent Type: ${agentType}`);
      console.log(`   • Project: ${projectContext.name || 'Unknown'}`);
      console.log(`   • Capabilities: Native commands, Auto-handoff, Context-aware`);
      console.log('');
      console.log('🎯 Ready for collaborative development!');
      console.log('   • Use *workspace-status to see current state');
      console.log('   • Use *workspace-handoff [agent] to transfer context');
      console.log('   • Workspace operations are now automatic');

      if (workspaceContext) {
        console.log('♻️  Previous workspace context restored');
      }

      if (integrityResults.issues.length > 0) {
        console.log(`🔧 Workspace maintenance: ${integrityResults.issues.length} issues auto-repaired`);
      }

      return {
        status: 'initialized',
        sessionId: sessionResult.sessionId,
        duration: duration,
        contextRestored: !!workspaceContext,
        issuesRepaired: integrityResults.issues.length
      };

    } catch (error) {
      console.error('❌ Workspace initialization failed:', error.message);
      return { status: 'failed', error: error.message };
    }
  }

  /**
   * Show current workspace status
   */
  async workspaceStatus(detailed = false) {
    try {
      console.log('📊 Claude Code CLI Workspace Status');
      console.log('═'.repeat(50));

      // Get session status
      const sessionStatus = this.sessionManager.getSessionStatus();

      if (sessionStatus.status === 'inactive') {
        console.log('⚠️  No active workspace session');
        console.log('   Use *workspace-init to start collaborating');
        return { status: 'inactive' };
      }

      // Display session information
      console.log('🎯 Active Session:');
      console.log(`   • Session ID: ${sessionStatus.sessionId}`);
      console.log(`   • Agent: ${sessionStatus.agentType}`);
      console.log(`   • Status: ${sessionStatus.status}`);
      console.log(`   • Started: ${new Date(sessionStatus.startTime).toLocaleString()}`);
      console.log(`   • Last Activity: ${new Date(sessionStatus.lastActivity).toLocaleString()}`);

      // Display capabilities
      console.log('');
      console.log('⚡ Enhanced Capabilities:');
      const caps = sessionStatus.capabilities || {};
      console.log(`   • Native Commands: ${caps.nativeCommands ? '✅' : '❌'}`);
      console.log(`   • Auto Handoff: ${caps.autoHandoff ? '✅' : '❌'}`);
      console.log(`   • Context Aware: ${caps.contextAware ? '✅' : '❌'}`);
      console.log(`   • Auto Maintenance: ${caps.autoMaintenance ? '✅' : '❌'}`);

      // Display metrics
      console.log('');
      console.log('📈 Session Metrics:');
      const metrics = sessionStatus.metrics || {};
      console.log(`   • Commands Executed: ${metrics.commandsExecuted || 0}`);
      console.log(`   • Context Switches: ${metrics.contextSwitches || 0}`);
      console.log(`   • Handoffs Initiated: ${metrics.handoffsInitiated || 0}`);
      console.log(`   • Handoffs Received: ${metrics.handoffsReceived || 0}`);

      // Check for pending handoffs
      const pendingHandoffs = await this.checkPendingHandoffs();
      if (pendingHandoffs.length > 0) {
        console.log('');
        console.log('📥 Pending Handoffs:');
        pendingHandoffs.forEach((handoff, index) => {
          console.log(`   ${index + 1}. ${handoff.sourceAgent} → ${handoff.targetAgent} (${handoff.timestamp})`);
        });
      }

      // Check workspace health
      const healthCheck = await this.sessionManager.performIntegrityCheck();
      console.log('');
      console.log(`🏥 Workspace Health: ${healthCheck.status.toUpperCase()}`);
      if (healthCheck.issues.length > 0) {
        console.log(`   • Issues Found: ${healthCheck.issues.length} (auto-repaired)`);
      } else {
        console.log('   • All systems operational');
      }

      // Detailed information if requested
      if (detailed) {
        console.log('');
        console.log('🔍 Detailed Information:');

        // Show recent workspace activity
        const recentActivity = await this.getRecentActivity();
        if (recentActivity.length > 0) {
          console.log('   Recent Activity:');
          recentActivity.slice(0, 5).forEach((activity, index) => {
            console.log(`     ${index + 1}. ${activity.type}: ${activity.description} (${activity.timestamp})`);
          });
        }

        // Show workspace file sizes
        const workspaceStats = await this.getWorkspaceStats();
        console.log('   Workspace Statistics:');
        console.log(`     • Total Files: ${workspaceStats.fileCount}`);
        console.log(`     • Total Size: ${workspaceStats.totalSize}`);
        console.log(`     • Context Size: ${workspaceStats.contextSize}`);
      }

      console.log('');
      console.log('💡 Available Commands:');
      console.log('   • *workspace-cleanup - Optimize workspace');
      console.log('   • *workspace-handoff [agent] - Transfer to agent');
      console.log('   • *workspace-sync - Sync latest context');

      return {
        status: 'active',
        session: sessionStatus,
        pendingHandoffs: pendingHandoffs.length,
        health: healthCheck.status
      };

    } catch (error) {
      console.error('❌ Failed to get workspace status:', error.message);
      return { status: 'error', error: error.message };
    }
  }

  /**
   * Clean up workspace and optimize
   */
  async workspaceCleanup(options = {}) {
    const startTime = Date.now();

    try {
      console.log('🧹 Starting workspace cleanup and optimization...');

      let cleanupResults = {
        filesRemoved: 0,
        spaceSaved: 0,
        issuesFixed: 0,
        optimizations: []
      };

      // Perform integrity check and auto-repair
      const integrityResults = await this.sessionManager.performIntegrityCheck();
      cleanupResults.issuesFixed = integrityResults.issues.length;

      // Clean up old sessions (older than 24 hours)
      const sessionCleanup = await this.cleanupOldSessions();
      cleanupResults.filesRemoved += sessionCleanup.filesRemoved;
      cleanupResults.spaceSaved += sessionCleanup.spaceSaved;

      // Clean up expired handoffs (older than 7 days)
      const handoffCleanup = await this.cleanupExpiredHandoffs();
      cleanupResults.filesRemoved += handoffCleanup.filesRemoved;
      cleanupResults.spaceSaved += handoffCleanup.spaceSaved;

      // Optimize context files (compress if over size limit)
      const contextOptimization = await this.optimizeContextFiles();
      cleanupResults.optimizations.push(...contextOptimization.optimizations);
      cleanupResults.spaceSaved += contextOptimization.spaceSaved;

      // Clean up temporary files
      const tempCleanup = await this.cleanupTempFiles();
      cleanupResults.filesRemoved += tempCleanup.filesRemoved;
      cleanupResults.spaceSaved += tempCleanup.spaceSaved;

      // Register command execution
      this.sessionManager.registerCommandExecution('workspace-cleanup', {
        options: options,
        results: cleanupResults
      });

      const duration = Date.now() - startTime;

      console.log('✅ Workspace cleanup complete!');
      console.log(`⏱️  Completed in ${duration}ms`);
      console.log('');
      console.log('📊 Cleanup Results:');
      console.log(`   • Files Removed: ${cleanupResults.filesRemoved}`);
      console.log(`   • Space Saved: ${this.formatBytes(cleanupResults.spaceSaved)}`);
      console.log(`   • Issues Fixed: ${cleanupResults.issuesFixed}`);
      console.log(`   • Optimizations: ${cleanupResults.optimizations.length}`);

      if (cleanupResults.optimizations.length > 0) {
        console.log('');
        console.log('⚡ Optimizations Applied:');
        cleanupResults.optimizations.forEach((opt, index) => {
          console.log(`   ${index + 1}. ${opt}`);
        });
      }

      console.log('');
      console.log('🎯 Workspace is now optimized for peak performance!');

      return {
        status: 'completed',
        duration: duration,
        results: cleanupResults
      };

    } catch (error) {
      console.error('❌ Workspace cleanup failed:', error.message);
      return { status: 'failed', error: error.message };
    }
  }

  /**
   * Prepare agent handoff
   */
  async workspaceHandoff(targetAgent, handoffContext = {}) {
    const startTime = Date.now();

    try {
      if (!targetAgent) {
        console.log('❌ Target agent required for handoff');
        console.log('');
        console.log('💡 Available agents:');
        console.log('   • dev - Full Stack Developer');
        console.log('   • qa - QA Engineer & Quality Architect'); 
        console.log('   • architect - Software Architect');
        console.log('   • pm - Product Manager');
        console.log('   • sm - Scrum Master');
        return { status: 'invalid', error: 'Target agent required' };
      }

      console.log(`🔄 Preparing handoff to ${targetAgent}...`);

      // Prepare handoff package
      const handoffResult = await this.sessionManager.prepareAgentHandoff(targetAgent, handoffContext);

      if (handoffResult.status === 'failed') {
        throw new Error(handoffResult.error);
      }

      // Generate handoff summary
      const sessionStatus = this.sessionManager.getSessionStatus();

      const duration = Date.now() - startTime;

      console.log('✅ Handoff package prepared!');
      console.log(`⏱️  Completed in ${duration}ms`);
      console.log('');
      console.log('📦 Handoff Details:');
      console.log(`   • Handoff ID: ${handoffResult.handoffId}`);
      console.log(`   • From: ${sessionStatus.agentType} (Claude Code CLI)`);
      console.log(`   • To: ${targetAgent}`);
      console.log(`   • Context Preserved: ${handoffResult.contextPreserved ? '✅' : '❌'}`);
      console.log('');
      console.log('🎯 Ready for agent transition!');
      console.log(`   • The ${targetAgent} agent can now access full context`);
      console.log('   • All workspace state has been preserved');
      console.log('   • Session continuity maintained');

      // Register command execution
      this.sessionManager.registerCommandExecution('workspace-handoff', {
        targetAgent: targetAgent,
        handoffId: handoffResult.handoffId,
        context: handoffContext
      });

      return {
        status: 'prepared',
        handoffId: handoffResult.handoffId,
        targetAgent: targetAgent,
        duration: duration
      };

    } catch (error) {
      console.error('❌ Handoff preparation failed:', error.message);
      return { status: 'failed', error: error.message };
    }
  }

  /**
   * Synchronize with latest workspace context
   */
  async workspaceSync(options = {}) {
    const startTime = Date.now();

    try {
      console.log('🔄 Synchronizing workspace context...');

      // Load latest workspace context
      const workspaceContext = await this.sessionManager.loadWorkspaceContext();

      // Check for pending handoffs to this agent
      const sessionStatus = this.sessionManager.getSessionStatus();
      const pendingHandoffs = await this.checkPendingHandoffs(sessionStatus.agentType);

      // Process any pending handoffs
      let handoffsProcessed = 0;
      for (const handoff of pendingHandoffs) {
        const restoreResult = await this.sessionManager.restoreFromHandoff(handoff.handoffId);
        if (restoreResult.status === 'restored') {
          handoffsProcessed++;
        }
      }

      // Update session metrics
      this.sessionManager.registerCommandExecution('workspace-sync', {
        options: options,
        contextLoaded: !!workspaceContext,
        handoffsProcessed: handoffsProcessed
      });

      const duration = Date.now() - startTime;

      console.log('✅ Workspace synchronization complete!');
      console.log(`⏱️  Completed in ${duration}ms`);
      console.log('');
      console.log('📊 Sync Results:');
      console.log(`   • Context Updated: ${workspaceContext ? '✅' : '❌'}`);
      console.log(`   • Handoffs Processed: ${handoffsProcessed}`);

      if (workspaceContext) {
        console.log(`   • Context Version: ${workspaceContext.version}`);
        console.log(`   • Last Modified: ${new Date(workspaceContext.lastModified).toLocaleString()}`);
      }

      if (handoffsProcessed > 0) {
        console.log('');
        console.log('🔄 Context restored from previous agent handoffs');
        console.log('   • Full development context available');
        console.log('   • Ready to continue collaborative work');
      }

      console.log('');
      console.log('🎯 Workspace is now synchronized and ready!');

      return {
        status: 'synchronized',
        duration: duration,
        contextLoaded: !!workspaceContext,
        handoffsProcessed: handoffsProcessed
      };

    } catch (error) {
      console.error('❌ Workspace synchronization failed:', error.message);
      return { status: 'failed', error: error.message };
    }
  }

  // Helper methods

  async detectProjectContext() {
    try {
      const packageJsonPath = path.join(this.workspaceDir, 'package.json');
      if (fs.existsSync(packageJsonPath)) {
        const packageJson = JSON.parse(fs.readFileSync(packageJsonPath, 'utf8'));
        return {
          name: packageJson.name,
          version: packageJson.version,
          type: 'nodejs',
          hasTests: !!packageJson.scripts?.test,
          hasBuild: !!packageJson.scripts?.build
        };
      }

      // Check for other project types
      const projectFiles = fs.readdirSync(this.workspaceDir);
      if (projectFiles.includes('.csproj') || projectFiles.some(f => f.endsWith('.csproj'))) {
        return { type: 'dotnet', name: path.basename(this.workspaceDir) };
      }

      return { type: 'unknown', name: path.basename(this.workspaceDir) };
    } catch (error) {
      return { type: 'unknown', name: 'project' };
    }
  }

  async checkPendingHandoffs(targetAgent = null) {
    try {
      const handoffsDir = path.join(this.workspaceDir, '.workspace', 'handoffs');
      if (!fs.existsSync(handoffsDir)) return [];

      const handoffFiles = fs.readdirSync(handoffsDir).filter(f => f.endsWith('.json'));
      const pendingHandoffs = [];

      for (const file of handoffFiles) {
        try {
          const handoffData = JSON.parse(fs.readFileSync(path.join(handoffsDir, file), 'utf8'));
          if (!targetAgent || handoffData.targetAgent === targetAgent) {
            pendingHandoffs.push({
              handoffId: path.basename(file, '.json'),
              sourceAgent: handoffData.sourceAgent,
              targetAgent: handoffData.targetAgent,
              timestamp: handoffData.timestamp
            });
          }
        } catch (error) {
          // Skip corrupted handoff files
        }
      }

      return pendingHandoffs;
    } catch (error) {
      return [];
    }
  }

  async cleanupOldSessions() {
    // Implementation for cleaning up old session files
    return { filesRemoved: 0, spaceSaved: 0 };
  }

  async cleanupExpiredHandoffs() {
    // Implementation for cleaning up expired handoff files
    return { filesRemoved: 0, spaceSaved: 0 };
  }

  async optimizeContextFiles() {
    // Implementation for optimizing context files
    return { optimizations: [], spaceSaved: 0 };
  }

  async cleanupTempFiles() {
    // Implementation for cleaning up temporary files
    return { filesRemoved: 0, spaceSaved: 0 };
  }

  async getRecentActivity() {
    // Implementation for getting recent workspace activity
    return [];
  }

  async getWorkspaceStats() {
    // Implementation for getting workspace statistics
    return { fileCount: 0, totalSize: '0 B', contextSize: '0 B' };
  }

  formatBytes(bytes) {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  }
}

module.exports = ClaudeCodeWorkspaceCommands;

const ClaudeCodeContextIntegration = require('./claude-code-context-integration');
const path = require('path');
const fs = require('fs');

/**
 * Claude Code CLI Enhanced User Experience Features
 * Provides intelligent suggestions, analytics, and seamless workflow integration
 */
class ClaudeCodeUXEnhancements {
  constructor(workspaceDir) {
    this.workspaceDir = workspaceDir;
    this.contextIntegration = new ClaudeCodeContextIntegration(workspaceDir);
    this.usageAnalytics = {
      sessionsStarted: 0,
      commandsExecuted: 0,
      handoffsCompleted: 0,
      averageSessionDuration: 0,
      mostUsedCommands: {},
      productivityMetrics: {}
    };
  }

  /**
   * Initialize UX enhancements for Claude Code CLI session
   */
  async initializeUXEnhancements(sessionId, agentType) {
    try {
      // Initialize context-aware features
      await this.contextIntegration.initializeContextAware(agentType, sessionId);

      // Load previous analytics
      await this.loadAnalytics();

      // Update session analytics
      this.usageAnalytics.sessionsStarted++;

      console.log('✨ Enhanced UX features activated');
      console.log('   • Intelligent workspace suggestions enabled');
      console.log('   • Context-aware command recommendations active');
      console.log('   • Productivity analytics tracking started');

      return {
        status: 'initialized',
        features: {
          intelligentSuggestions: true,
          contextAware: true,
          productivityAnalytics: true,
          seamlessIntegration: true
        }
      };

    } catch (error) {
      console.warn('Failed to initialize UX enhancements:', error.message);
      return { status: 'partial', error: error.message };
    }
  }

  /**
   * Add workspace status indicators to command responses
   */
  addWorkspaceStatusIndicators(commandResponse, commandName) {
    try {
      const indicators = [];

      // Add session status indicator
      indicators.push('🚀 Claude Code CLI Enhanced Session Active');

      // Add context awareness indicator
      if (this.contextIntegration.sessionContext) {
        indicators.push(`🧠 Context-Aware (${this.contextIntegration.activeAgent})`);
      }

      // Add recent activity indicator
      const recentCommands = this.getRecentCommandHistory();
      if (recentCommands.length > 0) {
        indicators.push(`📊 ${recentCommands.length} recent commands tracked`);
      }

      // Add collaboration indicator
      const collaborationStatus = this.getCollaborationStatus();
      if (collaborationStatus.activeCollaborators > 0) {
        indicators.push(`👥 ${collaborationStatus.activeCollaborators} active collaborators`);
      }

      // Format indicators
      const statusBar = indicators.join(' • ');

      // Add to response
      const enhancedResponse = {
        originalResponse: commandResponse,
        statusIndicators: statusBar,
        timestamp: new Date().toISOString(),
        enhanced: true
      };

      // Track command execution
      this.trackCommandExecution(commandName);

      return enhancedResponse;

    } catch (error) {
      console.warn('Failed to add status indicators:', error.message);
      return commandResponse;
    }
  }

  /**
   * Generate intelligent workspace suggestions
   */
  async generateIntelligentSuggestions() {
    try {
      console.log('🔮 Generating intelligent workspace suggestions...');

      // Get suggestions from context integration
      const contextSuggestions = await this.contextIntegration.generateIntelligentSuggestions();

      // Add productivity-based suggestions
      const productivitySuggestions = await this.generateProductivitySuggestions();

      // Add workflow optimization suggestions
      const workflowSuggestions = await this.generateWorkflowSuggestions();

      // Combine and prioritize suggestions
      const allSuggestions = [
        ...contextSuggestions,
        ...productivitySuggestions,
        ...workflowSuggestions
      ].sort((a, b) => {
        const priorityOrder = { 'high': 3, 'medium': 2, 'low': 1 };
        return priorityOrder[b.priority] - priorityOrder[a.priority];
      });

      // Display suggestions
      if (allSuggestions.length > 0) {
        console.log('');
        console.log('💡 Intelligent Workspace Suggestions:');
        console.log('═'.repeat(50));

        allSuggestions.slice(0, 5).forEach((suggestion, index) => {
          const priorityIcon = {
            'high': '🔥',
            'medium': '⚡',
            'low': '💭'
          }[suggestion.priority];

          console.log(`${index + 1}. ${priorityIcon} ${suggestion.title}`);
          console.log(`   ${suggestion.description}`);
          if (suggestion.action) {
            console.log(`   💻 Try: ${suggestion.action}`);
          }
          console.log(`   📝 Why: ${suggestion.reasoning}`);
          console.log('');
        });

        if (allSuggestions.length > 5) {
          console.log(`   📋 ${allSuggestions.length - 5} more suggestions available`);
          console.log('   Use *workspace-status detailed for full list');
        }
      } else {
        console.log('💡 No specific suggestions at this time - workspace is optimized!');
      }

      return allSuggestions;

    } catch (error) {
      console.warn('Failed to generate intelligent suggestions:', error.message);
      return [];
    }
  }

  /**
   * Generate productivity-based suggestions
   */
  async generateProductivitySuggestions() {
    const suggestions = [];

    try {
      // Analyze command usage patterns
      const commandStats = this.analyzeCommandUsage();

      // Suggest frequently used commands
      if (commandStats.mostUsed.length > 0) {
        const topCommand = commandStats.mostUsed[0];

        if (topCommand.count > 5) {
          suggestions.push({
            type: 'productivity',
            priority: 'medium',
            title: 'Command Usage Pattern Detected',
            description: `You frequently use *${topCommand.command} - consider workflow optimization`,
            reasoning: `Used ${topCommand.count} times in recent sessions`,
            context: { commandStats: topCommand }
          });
        }
      }

      // Analyze session duration patterns
      const sessionStats = this.analyzeSessionPatterns();

      if (sessionStats.averageDuration > 60) { // More than 1 hour
        suggestions.push({
          type: 'productivity',
          priority: 'low',
          title: 'Long Session Detected',
          description: 'Consider taking breaks or using *workspace-handoff for collaboration',
          action: '*workspace-status',
          reasoning: `Average session: ${Math.round(sessionStats.averageDuration)} minutes`
        });
      }

      // Suggest workspace cleanup based on activity
      if (this.usageAnalytics.commandsExecuted > 50) {
        suggestions.push({
          type: 'maintenance',
          priority: 'medium',
          title: 'Workspace Maintenance Recommended',
          description: 'High activity detected - workspace cleanup may improve performance',
          action: '*workspace-cleanup',
          reasoning: `${this.usageAnalytics.commandsExecuted} commands executed`
        });
      }

    } catch (error) {
      console.warn('Failed to generate productivity suggestions:', error.message);
    }

    return suggestions;
  }

  /**
   * Generate workflow optimization suggestions
   */
  async generateWorkflowSuggestions() {
    const suggestions = [];

    try {
      // Analyze handoff patterns
      const handoffPatterns = this.analyzeHandoffPatterns();

      if (handoffPatterns.frequentTransitions.length > 0) {
        const topTransition = handoffPatterns.frequentTransitions[0];

        suggestions.push({
          type: 'workflow',
          priority: 'medium',
          title: 'Workflow Pattern Optimization',
          description: `Frequent ${topTransition.from} → ${topTransition.to} transitions detected`,
          action: `*workspace-handoff ${topTransition.to}`,
          reasoning: `${topTransition.count} transitions in recent sessions`
        });
      }

      // Suggest collaboration opportunities
      const collaborationOpportunities = await this.contextIntegration.detectHandoffOpportunities();

      if (collaborationOpportunities.length > 0) {
        const topOpportunity = collaborationOpportunities[0];

        suggestions.push({
          type: 'collaboration',
          priority: 'high',
          title: 'Collaboration Opportunity Detected',
          description: topOpportunity.reason,
          action: `*workspace-handoff ${topOpportunity.targetAgent}`,
          reasoning: `Confidence: ${Math.round(topOpportunity.confidence * 100)}%`
        });
      }

    } catch (error) {
      console.warn('Failed to generate workflow suggestions:', error.message);
    }

    return suggestions;
  }

  /**
   * Build workspace usage analytics and insights
   */
  async buildUsageAnalytics() {
    try {
      console.log('📊 Workspace Usage Analytics & Insights');
      console.log('═'.repeat(50));

      // Session Analytics
      console.log('🎯 Session Statistics:');
      console.log(`   • Total Sessions: ${this.usageAnalytics.sessionsStarted}`);
      console.log(`   • Commands Executed: ${this.usageAnalytics.commandsExecuted}`);
      console.log(`   • Handoffs Completed: ${this.usageAnalytics.handoffsCompleted}`);

      if (this.usageAnalytics.averageSessionDuration > 0) {
        console.log(`   • Average Session: ${Math.round(this.usageAnalytics.averageSessionDuration)} minutes`);
      }

      // Command Usage Analytics
      const commandStats = this.analyzeCommandUsage();
      if (commandStats.mostUsed.length > 0) {
        console.log('');
        console.log('⚡ Most Used Commands:');
        commandStats.mostUsed.slice(0, 5).forEach((cmd, index) => {
          console.log(`   ${index + 1}. *${cmd.command} (${cmd.count} times)`);
        });
      }

      // Productivity Insights
      const productivityInsights = this.generateProductivityInsights();
      if (productivityInsights.length > 0) {
        console.log('');
        console.log('📈 Productivity Insights:');
        productivityInsights.forEach((insight, index) => {
          console.log(`   ${index + 1}. ${insight.title}: ${insight.value}`);
          if (insight.recommendation) {
            console.log(`      💡 ${insight.recommendation}`);
          }
        });
      }

      // Collaboration Analytics
      const collaborationStats = this.analyzeCollaborationPatterns();
      if (collaborationStats.totalHandoffs > 0) {
        console.log('');
        console.log('🤝 Collaboration Patterns:');
        console.log(`   • Total Handoffs: ${collaborationStats.totalHandoffs}`);
        console.log(`   • Most Common: ${collaborationStats.mostCommonTransition || 'N/A'}`);
        console.log(`   • Collaboration Score: ${collaborationStats.collaborationScore}/100`);
      }

      // Workspace Health Trends
      const healthTrends = await this.analyzeHealthTrends();
      if (healthTrends.length > 0) {
        console.log('');
        console.log('🏥 Workspace Health Trends:');
        healthTrends.forEach((trend, index) => {
          const trendIcon = trend.direction === 'improving' ? '📈' : 
                           trend.direction === 'declining' ? '📉' : '➡️';
          console.log(`   ${index + 1}. ${trendIcon} ${trend.metric}: ${trend.status}`);
        });
      }

      // Save analytics
      await this.saveAnalytics();

      return {
        sessionStats: this.usageAnalytics,
        commandStats: commandStats,
        productivityInsights: productivityInsights,
        collaborationStats: collaborationStats,
        healthTrends: healthTrends
      };

    } catch (error) {
      console.error('Failed to build usage analytics:', error.message);
      return { error: error.message };
    }
  }

  /**
   * Ensure seamless integration with existing Claude Code CLI workflows
   */
  ensureSeamlessIntegration() {
    try {
      // Check for existing Claude Code CLI patterns
      const integrationChecks = {
        toolIntegration: this.checkToolIntegration(),
        workflowCompatibility: this.checkWorkflowCompatibility(),
        performanceImpact: this.checkPerformanceImpact(),
        userExperience: this.checkUserExperience()
      };

      let integrationScore = 0;
      let totalChecks = 0;

      Object.entries(integrationChecks).forEach(([check, result]) => {
        totalChecks++;
        if (result.status === 'good') integrationScore++;
      });

      const integrationPercentage = Math.round((integrationScore / totalChecks) * 100);

      console.log('🔗 Claude Code CLI Integration Status:');
      console.log(`   • Overall Score: ${integrationPercentage}%`);
      console.log(`   • Tool Integration: ${integrationChecks.toolIntegration.status.toUpperCase()}`);
      console.log(`   • Workflow Compatibility: ${integrationChecks.workflowCompatibility.status.toUpperCase()}`);
      console.log(`   • Performance Impact: ${integrationChecks.performanceImpact.status.toUpperCase()}`);
      console.log(`   • User Experience: ${integrationChecks.userExperience.status.toUpperCase()}`);

      if (integrationPercentage < 80) {
        console.log('');
        console.log('⚠️  Integration improvements recommended:');
        Object.entries(integrationChecks).forEach(([check, result]) => {
          if (result.status !== 'good' && result.recommendation) {
            console.log(`   • ${result.recommendation}`);
          }
        });
      }

      return {
        integrationScore: integrationPercentage,
        checks: integrationChecks,
        status: integrationPercentage >= 80 ? 'excellent' : 
                integrationPercentage >= 60 ? 'good' : 'needs_improvement'
      };

    } catch (error) {
      console.warn('Failed to check integration status:', error.message);
      return { status: 'unknown', error: error.message };
    }
  }

  // Helper methods for analytics and integration

  trackCommandExecution(commandName) {
    this.usageAnalytics.commandsExecuted++;

    if (!this.usageAnalytics.mostUsedCommands[commandName]) {
      this.usageAnalytics.mostUsedCommands[commandName] = 0;
    }
    this.usageAnalytics.mostUsedCommands[commandName]++;
  }

  analyzeCommandUsage() {
    const commands = Object.entries(this.usageAnalytics.mostUsedCommands)
      .map(([command, count]) => ({ command, count }))
      .sort((a, b) => b.count - a.count);

    return {
      mostUsed: commands,
      totalCommands: this.usageAnalytics.commandsExecuted,
      uniqueCommands: commands.length
    };
  }

  analyzeSessionPatterns() {
    return {
      averageDuration: this.usageAnalytics.averageSessionDuration,
      totalSessions: this.usageAnalytics.sessionsStarted,
      commandsPerSession: this.usageAnalytics.sessionsStarted > 0 ? 
        Math.round(this.usageAnalytics.commandsExecuted / this.usageAnalytics.sessionsStarted) : 0
    };
  }

  analyzeHandoffPatterns() {
    // Simplified implementation - would analyze actual handoff data
    return {
      frequentTransitions: [
        { from: 'dev', to: 'qa', count: 5 },
        { from: 'qa', to: 'dev', count: 3 }
      ],
      totalHandoffs: this.usageAnalytics.handoffsCompleted
    };
  }

  generateProductivityInsights() {
    const insights = [];

    const commandsPerSession = this.analyzeSessionPatterns().commandsPerSession;
    if (commandsPerSession > 0) {
      insights.push({
        title: 'Commands per Session',
        value: commandsPerSession,
        recommendation: commandsPerSession < 5 ? 
          'Consider using more workspace features for better productivity' :
          commandsPerSession > 20 ?
          'High activity - consider workflow optimization' :
          'Good productivity balance'
      });
    }

    return insights;
  }

  analyzeCollaborationPatterns() {
    return {
      totalHandoffs: this.usageAnalytics.handoffsCompleted,
      mostCommonTransition: 'dev → qa',
      collaborationScore: Math.min(100, this.usageAnalytics.handoffsCompleted * 10)
    };
  }

  async analyzeHealthTrends() {
    // Simplified implementation - would analyze workspace health over time
    return [
      {
        metric: 'Workspace Health',
        status: 'Stable',
        direction: 'stable'
      }
    ];
  }

  checkToolIntegration() {
    // Check if workspace commands integrate well with Claude Code CLI tools
    return {
      status: 'good',
      details: 'Workspace commands integrate seamlessly with Claude Code CLI'
    };
  }

  checkWorkflowCompatibility() {
    // Check if workflows are compatible with existing Claude Code patterns
    return {
      status: 'good',
      details: 'Workflows maintain Claude Code CLI conventions'
    };
  }

  checkPerformanceImpact() {
    // Check performance impact of enhancements
    return {
      status: 'good',
      details: 'Minimal performance impact detected'
    };
  }

  checkUserExperience() {
    // Check overall user experience improvements
    return {
      status: 'good',
      details: 'Enhanced features improve productivity without complexity'
    };
  }

  getRecentCommandHistory() {
    // Simplified implementation
    return Object.entries(this.usageAnalytics.mostUsedCommands)
      .slice(0, 5)
      .map(([command, count]) => ({ command, count }));
  }

  getCollaborationStatus() {
    return {
      activeCollaborators: 0, // Would check actual active sessions
      recentHandoffs: this.usageAnalytics.handoffsCompleted
    };
  }

  async loadAnalytics() {
    try {
      const analyticsFile = path.join(this.workspaceDir, '.workspace', 'analytics.json');

      if (fs.existsSync(analyticsFile)) {
        const data = JSON.parse(fs.readFileSync(analyticsFile, 'utf8'));
        this.usageAnalytics = { ...this.usageAnalytics, ...data };
      }
    } catch (error) {
      // Use default analytics if loading fails
    }
  }

  async saveAnalytics() {
    try {
      const analyticsFile = path.join(this.workspaceDir, '.workspace', 'analytics.json');
      const analyticsDir = path.dirname(analyticsFile);

      if (!fs.existsSync(analyticsDir)) {
        fs.mkdirSync(analyticsDir, { recursive: true });
      }

      fs.writeFileSync(analyticsFile, JSON.stringify(this.usageAnalytics, null, 2));
    } catch (error) {
      console.warn('Failed to save analytics:', error.message);
    }
  }
}

module.exports = ClaudeCodeUXEnhancements;

const path = require('path');
const fs = require('fs');
const crypto = require('crypto');

/**
 * Claude Code CLI Session Manager
 * Provides automatic session management, heartbeat tracking, and context restoration
 * for Claude Code CLI users of the BMAD collaborative workspace system.
 */
class ClaudeCodeSessionManager {
  constructor(workspaceDir) {
    this.workspaceDir = workspaceDir;
    this.sessionsDir = path.join(workspaceDir, '.workspace', 'sessions');
    this.sessionId = null;
    this.heartbeatInterval = null;
    this.sessionData = null;
    this.isClaudeCodeSession = process.env.CLAUDE_CODE_SESSION || false;
  }

  /**
   * Initialize Claude Code CLI session with automatic registration
   */
  async initializeSession(agentType = 'dev', projectContext = {}) {
    try {
      // Generate unique session ID
      this.sessionId = `claude-code-${Date.now()}-${crypto.randomBytes(4).toString('hex')}`;

      // Ensure sessions directory exists
      if (!fs.existsSync(this.sessionsDir)) {
        fs.mkdirSync(this.sessionsDir, { recursive: true });
      }

      // Create session data
      this.sessionData = {
        sessionId: this.sessionId,
        agentType: agentType,
        ide: 'claude-code',
        startTime: new Date().toISOString(),
        lastActivity: new Date().toISOString(),
        status: 'active',
        projectContext: projectContext,
        workspaceVersion: '1.0',
        capabilities: {
          nativeCommands: true,
          autoHandoff: true,
          contextAware: true,
          autoMaintenance: true
        },
        metrics: {
          commandsExecuted: 0,
          contextSwitches: 0,
          handoffsInitiated: 0,
          handoffsReceived: 0
        }
      };

      // Write session file
      const sessionFile = path.join(this.sessionsDir, `${this.sessionId}.json`);
      fs.writeFileSync(sessionFile, JSON.stringify(this.sessionData, null, 2));

      // Start heartbeat monitoring
      this.startHeartbeat();

      // Auto-load workspace context if available
      await this.loadWorkspaceContext();

      console.log(`🚀 Claude Code CLI session initialized: ${this.sessionId}`);
      console.log(`📍 Agent: ${agentType} | Project: ${projectContext.name || 'Unknown'}`);

      return {
        sessionId: this.sessionId,
        status: 'initialized',
        capabilities: this.sessionData.capabilities
      };

    } catch (error) {
      console.error('Failed to initialize Claude Code CLI session:', error.message);
      return { status: 'failed', error: error.message };
    }
  }

  /**
   * Start automatic heartbeat monitoring
   */
  startHeartbeat() {
    // Update heartbeat every 30 seconds
    this.heartbeatInterval = setInterval(() => {
      this.updateHeartbeat();
    }, 30000);

    // Also update on process events
    process.on('beforeExit', () => this.cleanupSession());
    process.on('SIGINT', () => this.cleanupSession());
    process.on('SIGTERM', () => this.cleanupSession());
  }

  /**
   * Update session heartbeat
   */
  updateHeartbeat() {
    if (!this.sessionId || !this.sessionData) return;

    try {
      this.sessionData.lastActivity = new Date().toISOString();

      const sessionFile = path.join(this.sessionsDir, `${this.sessionId}.json`);
      if (fs.existsSync(sessionFile)) {
        fs.writeFileSync(sessionFile, JSON.stringify(this.sessionData, null, 2));
      }
    } catch (error) {
      console.warn('Failed to update session heartbeat:', error.message);
    }
  }

  /**
   * Register command execution
   */
  registerCommandExecution(command, context = {}) {
    if (!this.sessionData) return;

    this.sessionData.metrics.commandsExecuted++;
    this.sessionData.lastCommand = {
      command: command,
      timestamp: new Date().toISOString(),
      context: context
    };

    this.updateHeartbeat();
  }

  /**
   * Prepare agent handoff with context transfer
   */
  async prepareAgentHandoff(targetAgent, handoffContext = {}) {
    if (!this.sessionData) return null;

    try {
      // Increment handoff metrics
      this.sessionData.metrics.handoffsInitiated++;

      // Load current workspace context
      const workspaceContext = await this.loadWorkspaceContext();

      // Generate handoff package
      const handoffData = {
        sourceSession: this.sessionId,
        sourceAgent: this.sessionData.agentType,
        targetAgent: targetAgent,
        timestamp: new Date().toISOString(),
        workspaceContext: workspaceContext,
        sessionContext: {
          metrics: this.sessionData.metrics,
          recentCommands: this.sessionData.lastCommand,
          projectContext: this.sessionData.projectContext
        },
        handoffContext: handoffContext,
        continuity: {
          sessionId: this.sessionId,
          resumable: true,
          contextVersion: workspaceContext?.version || '1.0'
        }
      };

      // Save handoff package
      const handoffId = `${this.sessionData.agentType}-to-${targetAgent}-${Date.now()}`;
      const handoffFile = path.join(this.workspaceDir, '.workspace', 'handoffs', `${handoffId}.json`);

      if (!fs.existsSync(path.dirname(handoffFile))) {
        fs.mkdirSync(path.dirname(handoffFile), { recursive: true });
      }

      fs.writeFileSync(handoffFile, JSON.stringify(handoffData, null, 2));

      console.log(`🔄 Handoff prepared: ${this.sessionData.agentType} → ${targetAgent}`);
      console.log(`📦 Handoff package: ${handoffId}.json`);

      return {
        handoffId: handoffId,
        targetAgent: targetAgent,
        status: 'prepared',
        contextPreserved: true
      };

    } catch (error) {
      console.error('Failed to prepare agent handoff:', error.message);
      return { status: 'failed', error: error.message };
    }
  }

  /**
   * Restore session from handoff
   */
  async restoreFromHandoff(handoffId) {
    try {
      const handoffFile = path.join(this.workspaceDir, '.workspace', 'handoffs', `${handoffId}.json`);

      if (!fs.existsSync(handoffFile)) {
        throw new Error(`Handoff package not found: ${handoffId}`);
      }

      const handoffData = JSON.parse(fs.readFileSync(handoffFile, 'utf8'));

      // Update session data with handoff context
      if (this.sessionData) {
        this.sessionData.metrics.handoffsReceived++;
        this.sessionData.restoredFrom = {
          handoffId: handoffId,
          sourceAgent: handoffData.sourceAgent,
          timestamp: new Date().toISOString()
        };

        // Merge project context
        this.sessionData.projectContext = {
          ...this.sessionData.projectContext,
          ...handoffData.sessionContext.projectContext
        };
      }

      console.log(`♻️  Session restored from handoff: ${handoffData.sourceAgent} → ${this.sessionData?.agentType}`);

      return {
        status: 'restored',
        sourceAgent: handoffData.sourceAgent,
        contextVersion: handoffData.continuity.contextVersion
      };

    } catch (error) {
      console.error('Failed to restore from handoff:', error.message);
      return { status: 'failed', error: error.message };
    }
  }

  /**
   * Load workspace context for session continuity
   */
  async loadWorkspaceContext() {
    try {
      const contextFile = path.join(this.workspaceDir, '.workspace', 'context', 'shared-context.md');

      if (fs.existsSync(contextFile)) {
        const contextContent = fs.readFileSync(contextFile, 'utf8');
        return {
          content: contextContent,
          lastModified: fs.statSync(contextFile).mtime.toISOString(),
          version: '1.0'
        };
      }

      return null;
    } catch (error) {
      console.warn('Failed to load workspace context:', error.message);
      return null;
    }
  }

  /**
   * Get current session status
   */
  getSessionStatus() {
    if (!this.sessionData) {
      return { status: 'inactive' };
    }

    return {
      sessionId: this.sessionId,
      agentType: this.sessionData.agentType,
      status: this.sessionData.status,
      startTime: this.sessionData.startTime,
      lastActivity: this.sessionData.lastActivity,
      metrics: this.sessionData.metrics,
      capabilities: this.sessionData.capabilities
    };
  }

  /**
   * Perform workspace integrity check
   */
  async performIntegrityCheck() {
    const results = {
      timestamp: new Date().toISOString(),
      checks: [],
      status: 'healthy',
      issues: []
    };

    try {
      // Check workspace directory structure
      const requiredDirs = ['sessions', 'context', 'handoffs', 'decisions', 'progress', 'quality'];
      const workspaceRoot = path.join(this.workspaceDir, '.workspace');

      for (const dir of requiredDirs) {
        const dirPath = path.join(workspaceRoot, dir);
        const exists = fs.existsSync(dirPath);

        results.checks.push({
          type: 'directory',
          path: dir,
          status: exists ? 'ok' : 'missing'
        });

        if (!exists) {
          results.issues.push(`Missing directory: .workspace/${dir}`);
          fs.mkdirSync(dirPath, { recursive: true });
          results.checks[results.checks.length - 1].status = 'repaired';
        }
      }

      // Check session file integrity
      if (this.sessionId) {
        const sessionFile = path.join(this.sessionsDir, `${this.sessionId}.json`);
        const sessionExists = fs.existsSync(sessionFile);

        results.checks.push({
          type: 'session',
          sessionId: this.sessionId,
          status: sessionExists ? 'ok' : 'corrupted'
        });

        if (!sessionExists && this.sessionData) {
          fs.writeFileSync(sessionFile, JSON.stringify(this.sessionData, null, 2));
          results.checks[results.checks.length - 1].status = 'repaired';
        }
      }

      // Check for orphaned sessions (older than 2 hours with no activity)
      if (fs.existsSync(this.sessionsDir)) {
        const sessionFiles = fs.readdirSync(this.sessionsDir).filter(f => f.endsWith('.json'));
        const cutoffTime = Date.now() - (2 * 60 * 60 * 1000); // 2 hours ago

        for (const sessionFile of sessionFiles) {
          const sessionPath = path.join(this.sessionsDir, sessionFile);
          try {
            const sessionData = JSON.parse(fs.readFileSync(sessionPath, 'utf8'));
            const lastActivity = new Date(sessionData.lastActivity).getTime();

            if (lastActivity < cutoffTime) {
              results.issues.push(`Orphaned session: ${sessionData.sessionId}`);
              fs.unlinkSync(sessionPath);
              results.checks.push({
                type: 'cleanup',
                sessionId: sessionData.sessionId,
                status: 'removed'
              });
            }
          } catch (error) {
            results.issues.push(`Corrupted session file: ${sessionFile}`);
            fs.unlinkSync(sessionPath);
            results.checks.push({
              type: 'cleanup',
              file: sessionFile,
              status: 'removed'
            });
          }
        }
      }

      results.status = results.issues.length === 0 ? 'healthy' : 'repaired';

      return results;

    } catch (error) {
      results.status = 'failed';
      results.error = error.message;
      return results;
    }
  }

  /**
   * Clean up session on exit
   */
  cleanupSession() {
    if (this.heartbeatInterval) {
      clearInterval(this.heartbeatInterval);
      this.heartbeatInterval = null;
    }

    if (this.sessionId && this.sessionData) {
      try {
        // Mark session as completed
        this.sessionData.status = 'completed';
        this.sessionData.endTime = new Date().toISOString();

        const sessionFile = path.join(this.sessionsDir, `${this.sessionId}.json`);
        fs.writeFileSync(sessionFile, JSON.stringify(this.sessionData, null, 2));

        console.log(`📝 Claude Code CLI session completed: ${this.sessionId}`);
      } catch (error) {
        console.warn('Failed to cleanup session:', error.message);
      }
    }
  }
}

module.exports = ClaudeCodeSessionManager;

const path = require('path');
const fs = require('fs');

/**
 * Claude Code CLI Built-in Maintenance System
 * Provides automatic workspace repair, optimization, and health monitoring
 * specifically designed for Claude Code CLI users
 */
class ClaudeCodeMaintenanceSystem {
  constructor(workspaceDir) {
    this.workspaceDir = workspaceDir;
    this.maintenanceLog = [];
    this.healthMetrics = {
      lastCheck: null,
      overallHealth: 100,
      issues: [],
      optimizations: []
    };
    this.autoRepairEnabled = true;
    this.backgroundOptimization = true;
  }

  /**
   * Perform comprehensive workspace integrity check on session startup
   */
  async performStartupIntegrityCheck() {
    console.log('🔍 Performing workspace integrity check...');

    const checkResults = {
      timestamp: new Date().toISOString(),
      checks: [],
      issues: [],
      repairs: [],
      optimizations: [],
      overallStatus: 'healthy'
    };

    try {
      // Check workspace directory structure
      await this.checkDirectoryStructure(checkResults);

      // Check file integrity
      await this.checkFileIntegrity(checkResults);

      // Check session cleanup
      await this.checkSessionCleanup(checkResults);

      // Check context file sizes
      await this.checkContextSizes(checkResults);

      // Check handoff integrity
      await this.checkHandoffIntegrity(checkResults);

      // Auto-repair issues if enabled
      if (this.autoRepairEnabled && checkResults.issues.length > 0) {
        await this.performAutoRepair(checkResults);
      }

      // Update health metrics
      this.updateHealthMetrics(checkResults);

      // Log results
      this.logMaintenanceActivity('startup-integrity-check', checkResults);

      // Display results to user
      this.displayIntegrityResults(checkResults);

      return checkResults;

    } catch (error) {
      console.error('❌ Integrity check failed:', error.message);
      checkResults.overallStatus = 'failed';
      checkResults.error = error.message;
      return checkResults;
    }
  }

  /**
   * Check and repair workspace directory structure
   */
  async checkDirectoryStructure(results) {
    const requiredDirs = [
      '.workspace',
      '.workspace/sessions',
      '.workspace/context',
      '.workspace/handoffs',
      '.workspace/decisions',
      '.workspace/progress',
      '.workspace/quality',
      '.workspace/archive',
      '.workspace/versions',
      '.workspace/locks'
    ];

    for (const dir of requiredDirs) {
      const dirPath = path.join(this.workspaceDir, dir);
      const exists = fs.existsSync(dirPath);

      results.checks.push({
        type: 'directory',
        path: dir,
        status: exists ? 'ok' : 'missing',
        timestamp: new Date().toISOString()
      });

      if (!exists) {
        results.issues.push({
          type: 'missing_directory',
          path: dir,
          severity: 'medium',
          description: `Required directory missing: ${dir}`
        });

        // Auto-repair: Create missing directory
        try {
          fs.mkdirSync(dirPath, { recursive: true });
          results.repairs.push({
            type: 'directory_created',
            path: dir,
            status: 'success',
            description: `Created missing directory: ${dir}`
          });

          // Update check status
          const checkIndex = results.checks.length - 1;
          results.checks[checkIndex].status = 'repaired';

        } catch (error) {
          results.repairs.push({
            type: 'directory_creation_failed',
            path: dir,
            status: 'failed',
            error: error.message
          });
        }
      }
    }
  }

  /**
   * Check file integrity and corruption
   */
  async checkFileIntegrity(results) {
    const criticalFiles = [
      '.workspace/workspace-config.json',
      '.workspace/context/shared-context.md',
      '.workspace/decisions/decisions-log.md',
      '.workspace/progress/progress-summary.md'
    ];

    for (const file of criticalFiles) {
      const filePath = path.join(this.workspaceDir, file);
      const exists = fs.existsSync(filePath);

      if (exists) {
        try {
          // Check if file is readable and valid
          const content = fs.readFileSync(filePath, 'utf8');

          // Validate JSON files
          if (file.endsWith('.json')) {
            JSON.parse(content);
          }

          results.checks.push({
            type: 'file_integrity',
            path: file,
            status: 'ok',
            size: content.length
          });

        } catch (error) {
          results.issues.push({
            type: 'corrupted_file',
            path: file,
            severity: 'high',
            description: `File corrupted or unreadable: ${file}`,
            error: error.message
          });

          results.checks.push({
            type: 'file_integrity',
            path: file,
            status: 'corrupted',
            error: error.message
          });

          // Auto-repair: Restore from backup or create default
          await this.repairCorruptedFile(file, results);
        }
      } else {
        // Critical file missing
        results.issues.push({
          type: 'missing_file',
          path: file,
          severity: 'medium',
          description: `Critical file missing: ${file}`
        });

        // Auto-repair: Create default file
        await this.createDefaultFile(file, results);
      }
    }
  }

  /**
   * Check and cleanup old sessions
   */
  async checkSessionCleanup(results) {
    try {
      const sessionsDir = path.join(this.workspaceDir, '.workspace', 'sessions');

      if (!fs.existsSync(sessionsDir)) return;

      const sessionFiles = fs.readdirSync(sessionsDir).filter(f => f.endsWith('.json'));
      const cutoffTime = Date.now() - (24 * 60 * 60 * 1000); // 24 hours ago
      let cleanedSessions = 0;

      for (const sessionFile of sessionFiles) {
        const sessionPath = path.join(sessionsDir, sessionFile);

        try {
          const sessionData = JSON.parse(fs.readFileSync(sessionPath, 'utf8'));
          const lastActivity = new Date(sessionData.lastActivity || sessionData.startTime).getTime();

          if (lastActivity < cutoffTime && sessionData.status !== 'active') {
            fs.unlinkSync(sessionPath);
            cleanedSessions++;

            results.optimizations.push({
              type: 'session_cleanup',
              file: sessionFile,
              description: 'Removed old inactive session'
            });
          }
        } catch (error) {
          // Remove corrupted session file
          fs.unlinkSync(sessionPath);
          cleanedSessions++;

          results.repairs.push({
            type: 'corrupted_session_removed',
            file: sessionFile,
            status: 'success',
            description: 'Removed corrupted session file'
          });
        }
      }

      results.checks.push({
        type: 'session_cleanup',
        status: 'completed',
        sessionsProcessed: sessionFiles.length,
        sessionsCleaned: cleanedSessions
      });

    } catch (error) {
      results.checks.push({
        type: 'session_cleanup',
        status: 'failed',
        error: error.message
      });
    }
  }

  /**
   * Check context file sizes and optimize if needed
   */
  async checkContextSizes(results) {
    const contextFiles = [
      '.workspace/context/shared-context.md',
      '.workspace/decisions/decisions-log.md',
      '.workspace/progress/progress-summary.md'
    ];

    const sizeLimits = {
      'shared-context.md': 10 * 1024 * 1024, // 10MB
      'decisions-log.md': 5 * 1024 * 1024,   // 5MB
      'progress-summary.md': 3 * 1024 * 1024  // 3MB
    };

    for (const file of contextFiles) {
      const filePath = path.join(this.workspaceDir, file);

      if (fs.existsSync(filePath)) {
        const stats = fs.statSync(filePath);
        const fileName = path.basename(file);
        const sizeLimit = sizeLimits[fileName] || 10 * 1024 * 1024;

        results.checks.push({
          type: 'file_size',
          path: file,
          size: stats.size,
          sizeLimit: sizeLimit,
          status: stats.size > sizeLimit ? 'oversized' : 'ok'
        });

        if (stats.size > sizeLimit) {
          results.issues.push({
            type: 'oversized_file',
            path: file,
            severity: 'medium',
            description: `File exceeds size limit: ${this.formatBytes(stats.size)} > ${this.formatBytes(sizeLimit)}`,
            currentSize: stats.size,
            sizeLimit: sizeLimit
          });

          // Auto-optimize: Archive and compress
          await this.optimizeOversizedFile(file, results);
        }
      }
    }
  }

  /**
   * Check handoff file integrity
   */
  async checkHandoffIntegrity(results) {
    try {
      const handoffsDir = path.join(this.workspaceDir, '.workspace', 'handoffs');

      if (!fs.existsSync(handoffsDir)) return;

      const handoffFiles = fs.readdirSync(handoffsDir).filter(f => f.endsWith('.json'));
      let corruptedHandoffs = 0;
      let expiredHandoffs = 0;

      const expirationTime = Date.now() - (7 * 24 * 60 * 60 * 1000); // 7 days ago

      for (const handoffFile of handoffFiles) {
        const handoffPath = path.join(handoffsDir, handoffFile);

        try {
          const handoffData = JSON.parse(fs.readFileSync(handoffPath, 'utf8'));
          const handoffTime = new Date(handoffData.timestamp).getTime();

          // Check if handoff is expired
          if (handoffTime < expirationTime) {
            fs.unlinkSync(handoffPath);
            expiredHandoffs++;

            results.optimizations.push({
              type: 'handoff_cleanup',
              file: handoffFile,
              description: 'Removed expired handoff'
            });
          }

        } catch (error) {
          // Remove corrupted handoff file
          fs.unlinkSync(handoffPath);
          corruptedHandoffs++;

          results.repairs.push({
            type: 'corrupted_handoff_removed',
            file: handoffFile,
            status: 'success',
            description: 'Removed corrupted handoff file'
          });
        }
      }

      results.checks.push({
        type: 'handoff_integrity',
        status: 'completed',
        handoffsProcessed: handoffFiles.length,
        corruptedRemoved: corruptedHandoffs,
        expiredRemoved: expiredHandoffs
      });

    } catch (error) {
      results.checks.push({
        type: 'handoff_integrity',
        status: 'failed',
        error: error.message
      });
    }
  }

  /**
   * Perform automatic repairs
   */
  async performAutoRepair(results) {
    console.log(`🔧 Auto-repairing ${results.issues.length} issues...`);

    let repairedCount = 0;

    for (const issue of results.issues) {
      try {
        switch (issue.type) {
          case 'missing_directory':
            // Already handled in checkDirectoryStructure
            break;

          case 'corrupted_file':
            await this.repairCorruptedFile(issue.path, results);
            repairedCount++;
            break;

          case 'missing_file':
            await this.createDefaultFile(issue.path, results);
            repairedCount++;
            break;

          case 'oversized_file':
            await this.optimizeOversizedFile(issue.path, results);
            repairedCount++;
            break;
        }
      } catch (error) {
        results.repairs.push({
          type: 'repair_failed',
          issue: issue.type,
          path: issue.path,
          status: 'failed',
          error: error.message
        });
      }
    }

    if (repairedCount > 0) {
      console.log(`✅ Auto-repaired ${repairedCount} issues`);
    }
  }

  /**
   * Repair corrupted file
   */
  async repairCorruptedFile(filePath, results) {
    const fullPath = path.join(this.workspaceDir, filePath);

    try {
      // Try to restore from backup if available
      const backupPath = `${fullPath}.backup`;

      if (fs.existsSync(backupPath)) {
        fs.copyFileSync(backupPath, fullPath);
        results.repairs.push({
          type: 'file_restored_from_backup',
          path: filePath,
          status: 'success',
          description: 'Restored file from backup'
        });
      } else {
        // Create default file
        await this.createDefaultFile(filePath, results);
      }
    } catch (error) {
      results.repairs.push({
        type: 'file_repair_failed',
        path: filePath,
        status: 'failed',
        error: error.message
      });
    }
  }

  /**
   * Create default file
   */
  async createDefaultFile(filePath, results) {
    const fullPath = path.join(this.workspaceDir, filePath);
    const fileName = path.basename(filePath);

    try {
      let defaultContent = '';

      switch (fileName) {
        case 'workspace-config.json':
          defaultContent = JSON.stringify({
            version: '1.0',
            created: new Date().toISOString(),
            structure: ['sessions', 'context', 'handoffs', 'decisions', 'progress', 'quality', 'archive'],
            settings: {
              maxContextSize: '10MB',
              sessionTimeout: '2h',
              archiveAfter: '30d',
              maxConcurrentSessions: 5
            }
          }, null, 2);
          break;

        case 'shared-context.md':
          defaultContent = `# Workspace Context

**Last Updated:** ${new Date().toISOString()}
**Active Sessions:** None
**Primary Agent:** unknown

## Current Focus
No current focus available.

## Key Decisions
- No decisions recorded yet

## Next Steps
- Initialize workspace and begin collaborative development

## Session Notes
No session notes available
`;
          break;

        case 'decisions-log.md':
          defaultContent = `# Architectural & Design Decisions

No decisions recorded yet.
`;
          break;

        case 'progress-summary.md':
          defaultContent = `# Development Progress Summary

**Last Updated:** ${new Date().toISOString()}
**Current Story:** No active story
**Overall Progress:** 0%

## Completed Tasks
None

## Active Tasks
None

## Blockers
None identified

## Quality Metrics
Not assessed
`;
          break;

        default:
          defaultContent = `# ${fileName}

Default content created by Claude Code CLI maintenance system.
Created: ${new Date().toISOString()}
`;
      }

      fs.writeFileSync(fullPath, defaultContent);

      results.repairs.push({
        type: 'default_file_created',
        path: filePath,
        status: 'success',
        description: `Created default ${fileName}`
      });

    } catch (error) {
      results.repairs.push({
        type: 'default_file_creation_failed',
        path: filePath,
        status: 'failed',
        error: error.message
      });
    }
  }

  /**
   * Optimize oversized file
   */
  async optimizeOversizedFile(filePath, results) {
    const fullPath = path.join(this.workspaceDir, filePath);

    try {
      // Create backup
      const backupPath = `${fullPath}.backup`;
      fs.copyFileSync(fullPath, backupPath);

      // Archive old content
      const archiveDir = path.join(this.workspaceDir, '.workspace', 'archive');
      if (!fs.existsSync(archiveDir)) {
        fs.mkdirSync(archiveDir, { recursive: true });
      }

      const archivePath = path.join(archiveDir, `${path.basename(filePath)}-${Date.now()}.md`);
      fs.copyFileSync(fullPath, archivePath);

      // Create condensed version
      const content = fs.readFileSync(fullPath, 'utf8');
      const condensedContent = this.condenseContent(content, path.basename(filePath));
      fs.writeFileSync(fullPath, condensedContent);

      results.optimizations.push({
        type: 'file_optimized',
        path: filePath,
        description: 'File archived and condensed',
        archivePath: archivePath,
        originalSize: fs.statSync(backupPath).size,
        newSize: fs.statSync(fullPath).size
      });

    } catch (error) {
      results.repairs.push({
        type: 'file_optimization_failed',
        path: filePath,
        status: 'failed',
        error: error.message
      });
    }
  }

  /**
   * Condense content for oversized files
   */
  condenseContent(content, fileName) {
    const timestamp = new Date().toISOString();

    switch (fileName) {
      case 'shared-context.md':
        return `# Workspace Context (Condensed)

**Last Updated:** ${timestamp}
**Status:** Condensed due to size optimization
**Original Content:** Archived

## Current Focus
Previous context has been archived for size optimization.
Use *workspace-sync to reload if needed.

## Key Decisions
Most recent decisions preserved. Older decisions archived.

## Next Steps
- Review archived context if needed
- Continue with current development focus

## Session Notes
Content condensed - check archive for full history.
`;

      case 'decisions-log.md':
        // Keep last 10 decisions, archive the rest
        const lines = content.split('\n');
        const recentDecisions = lines.slice(-200); // Approximate last 10 decisions
        return `# Architectural & Design Decisions (Condensed)

**Condensed:** ${timestamp}
**Full History:** Available in archive

${recentDecisions.join('\n')}

---
*Older decisions archived for size optimization*
`;

      case 'progress-summary.md':
        return `# Development Progress Summary (Condensed)

**Last Updated:** ${timestamp}
**Previous Content:** Archived for size optimization

## Current Status
Progress history has been archived.
Current session progress will be tracked from this point.

## Recent Activity
Previous activity archived - new tracking begins now.

## Quality Metrics
Historical metrics archived - current assessment required.
`;

      default:
        return `# ${fileName} (Condensed)

**Condensed:** ${timestamp}
**Reason:** File size optimization

Previous content has been archived.
New content will be tracked from this point forward.
`;
    }
  }

  /**
   * Update health metrics
   */
  updateHealthMetrics(checkResults) {
    this.healthMetrics.lastCheck = checkResults.timestamp;
    this.healthMetrics.issues = checkResults.issues;
    this.healthMetrics.optimizations = checkResults.optimizations;

    // Calculate overall health score
    const issueCount = checkResults.issues.length;
    const repairCount = checkResults.repairs.filter(r => r.status === 'success').length;

    if (issueCount === 0) {
      this.healthMetrics.overallHealth = 100;
    } else if (repairCount >= issueCount) {
      this.healthMetrics.overallHealth = 90; // Issues but all repaired
    } else {
      this.healthMetrics.overallHealth = Math.max(50, 100 - (issueCount * 10));
    }
  }

  /**
   * Log maintenance activity
   */
  logMaintenanceActivity(type, data) {
    this.maintenanceLog.push({
      type: type,
      timestamp: new Date().toISOString(),
      data: data
    });

    // Keep only last 100 log entries
    if (this.maintenanceLog.length > 100) {
      this.maintenanceLog = this.maintenanceLog.slice(-100);
    }
  }

  /**
   * Display integrity check results
   */
  displayIntegrityResults(results) {
    if (results.issues.length === 0 && results.optimizations.length === 0) {
      console.log('✅ Workspace integrity check passed - all systems healthy');
      return;
    }

    if (results.repairs.length > 0) {
      const successfulRepairs = results.repairs.filter(r => r.status === 'success').length;
      console.log(`🔧 Workspace maintenance completed: ${successfulRepairs} issues auto-repaired`);
    }

    if (results.optimizations.length > 0) {
      console.log(`⚡ Workspace optimized: ${results.optimizations.length} optimizations applied`);
    }

    // Show remaining issues if any
    const unrepairedIssues = results.issues.filter(issue => 
      !results.repairs.some(repair => repair.path === issue.path && repair.status === 'success')
    );

    if (unrepairedIssues.length > 0) {
      console.log(`⚠️  ${unrepairedIssues.length} issues require manual attention`);
    }
  }

  /**
   * Format bytes for display
   */
  formatBytes(bytes) {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  }

  /**
   * Get maintenance summary
   */
  getMaintenanceSummary() {
    return {
      healthMetrics: this.healthMetrics,
      recentActivity: this.maintenanceLog.slice(-10),
      autoRepairEnabled: this.autoRepairEnabled,
      backgroundOptimization: this.backgroundOptimization
    };
  }
}

module.exports = ClaudeCodeMaintenanceSystem;

const HandoffManager = require('./handoff-manager');
const ContextManager = require('./context-manager');
const path = require('path');
const fs = require('fs');

/**
 * Claude Code CLI Context-Aware Integration
 * Provides seamless context transfer and intelligent handoffs within Claude Code CLI sessions
 */
class ClaudeCodeContextIntegration {
  constructor(workspaceDir) {
    this.workspaceDir = workspaceDir;
    this.handoffManager = new HandoffManager(workspaceDir);
    this.contextManager = new ContextManager(workspaceDir);
    this.sessionContext = null;
    this.activeAgent = null;
  }

  /**
   * Initialize context-aware session
   */
  async initializeContextAware(agentType, sessionId) {
    try {
      this.activeAgent = agentType;
      this.sessionContext = {
        sessionId: sessionId,
        agentType: agentType,
        startTime: new Date().toISOString(),
        contextVersion: '1.0',
        smartFeatures: {
          autoSuggestions: true,
          contextAwareness: true,
          intelligentHandoffs: true,
          predictiveActions: true
        }
      };

      // Load existing context
      const sharedContext = await this.contextManager.getSharedContext();
      const decisions = await this.contextManager.getDecisions();
      const progress = await this.contextManager.getProgress();

      console.log('🧠 Context-aware features initialized');
      console.log(`   • Loaded ${decisions.length} decisions`);
      console.log(`   • Loaded ${progress.completedTasks || 0} completed tasks`);

      if (sharedContext.currentFocus) {
        console.log(`   • Current Focus: ${sharedContext.currentFocus}`);
      }

      return {
        status: 'initialized',
        contextLoaded: true,
        smartFeaturesEnabled: true
      };

    } catch (error) {
      console.error('Failed to initialize context-aware features:', error.message);
      return { status: 'failed', error: error.message };
    }
  }

  /**
   * Generate intelligent workspace suggestions based on context
   */
  async generateIntelligentSuggestions() {
    try {
      const suggestions = [];

      // Analyze current context
      const sharedContext = await this.contextManager.getSharedContext();
      const progress = await this.contextManager.getProgress();
      const decisions = await this.contextManager.getDecisions();

      // Suggest based on current focus
      if (sharedContext.currentFocus) {
        if (sharedContext.currentFocus.includes('implement') || sharedContext.currentFocus.includes('develop')) {
          suggestions.push({
            type: 'workflow',
            priority: 'high',
            title: 'Ready for Quality Review',
            description: 'Consider using *workspace-handoff qa to get quality validation',
            action: '*workspace-handoff qa',
            reasoning: 'Development work detected, QA review recommended'
          });
        }

        if (sharedContext.currentFocus.includes('test') || sharedContext.currentFocus.includes('bug')) {
          suggestions.push({
            type: 'workflow',
            priority: 'medium',
            title: 'Development Collaboration',
            description: 'Hand off to dev agent for implementation fixes',
            action: '*workspace-handoff dev',
            reasoning: 'Testing/bug work detected, dev collaboration recommended'
          });
        }
      }

      // Suggest based on progress patterns
      if (progress.completedTasks > 0) {
        const recentTasks = progress.taskHistory?.slice(-3) || [];
        const hasRecentErrors = recentTasks.some(task => task.status === 'error');

        if (hasRecentErrors) {
          suggestions.push({
            type: 'maintenance',
            priority: 'high',
            title: 'Workspace Cleanup Recommended',
            description: 'Recent errors detected, workspace cleanup may help',
            action: '*workspace-cleanup',
            reasoning: 'Error patterns suggest workspace maintenance needed'
          });
        }
      }

      // Suggest based on decision patterns
      if (decisions.length > 10) {
        const recentDecisions = decisions.slice(-5);
        const hasArchitecturalDecisions = recentDecisions.some(d => 
          d.title.includes('architecture') || d.title.includes('design')
        );

        if (hasArchitecturalDecisions) {
          suggestions.push({
            type: 'collaboration',
            priority: 'medium',
            title: 'Architect Review Recommended',
            description: 'Recent architectural decisions may benefit from architect review',
            action: '*workspace-handoff architect',
            reasoning: 'Complex architectural decisions detected'
          });
        }
      }

      // Suggest based on workspace health
      const workspaceHealth = await this.checkWorkspaceHealth();
      if (workspaceHealth.issues > 0) {
        suggestions.push({
          type: 'maintenance',
          priority: workspaceHealth.issues > 3 ? 'high' : 'medium',
          title: 'Workspace Maintenance Needed',
          description: `${workspaceHealth.issues} workspace issues detected`,
          action: '*workspace-cleanup',
          reasoning: 'Workspace health issues detected'
        });
      }

      return suggestions.sort((a, b) => {
        const priorityOrder = { 'high': 3, 'medium': 2, 'low': 1 };
        return priorityOrder[b.priority] - priorityOrder[a.priority];
      });

    } catch (error) {
      console.warn('Failed to generate intelligent suggestions:', error.message);
      return [];
    }
  }

  /**
   * Detect when work is ready for agent handoff
   */
  async detectHandoffOpportunities() {
    try {
      const opportunities = [];

      // Analyze current work state
      const progress = await this.contextManager.getProgress();
      const sharedContext = await this.contextManager.getSharedContext();

      // Development completion patterns
      if (this.activeAgent === 'dev') {
        const devIndicators = [
          'implementation complete',
          'all tests passing',
          'ready for review',
          'feature complete'
        ];

        const contextText = sharedContext.sessionNotes?.toLowerCase() || '';
        const hasCompletionIndicator = devIndicators.some(indicator => 
          contextText.includes(indicator)
        );

        if (hasCompletionIndicator) {
          opportunities.push({
            targetAgent: 'qa',
            confidence: 0.85,
            reason: 'Development work appears complete, ready for QA review',
            suggestedAction: 'Quality validation and testing',
            context: {
              completionIndicators: devIndicators.filter(i => contextText.includes(i))
            }
          });
        }

        // Check for architectural questions
        const architecturalKeywords = ['architecture', 'design pattern', 'structure', 'framework'];
        const hasArchitecturalQuestions = architecturalKeywords.some(keyword => 
          contextText.includes(keyword)
        );

        if (hasArchitecturalQuestions) {
          opportunities.push({
            targetAgent: 'architect',
            confidence: 0.70,
            reason: 'Architectural decisions or questions detected',
            suggestedAction: 'Architectural guidance and design review',
            context: {
              architecturalIndicators: architecturalKeywords.filter(k => contextText.includes(k))
            }
          });
        }
      }

      // QA completion patterns
      if (this.activeAgent === 'qa') {
        const qaIndicators = [
          'tests passing',
          'quality approved',
          'ready for deployment',
          'validation complete'
        ];

        const contextText = sharedContext.sessionNotes?.toLowerCase() || '';
        const hasQACompletion = qaIndicators.some(indicator => 
          contextText.includes(indicator)
        );

        if (hasQACompletion) {
          opportunities.push({
            targetAgent: 'sm',
            confidence: 0.80,
            reason: 'QA validation complete, ready for story management',
            suggestedAction: 'Story completion and next story planning',
            context: {
              qaIndicators: qaIndicators.filter(i => contextText.includes(i))
            }
          });
        }

        // Check for critical issues requiring dev attention
        const criticalKeywords = ['critical', 'blocker', 'regression', 'failed'];
        const hasCriticalIssues = criticalKeywords.some(keyword => 
          contextText.includes(keyword)
        );

        if (hasCriticalIssues) {
          opportunities.push({
            targetAgent: 'dev',
            confidence: 0.90,
            reason: 'Critical issues detected requiring development attention',
            suggestedAction: 'Issue resolution and bug fixes',
            context: {
              criticalIndicators: criticalKeywords.filter(k => contextText.includes(k))
            }
          });
        }
      }

      return opportunities.sort((a, b) => b.confidence - a.confidence);

    } catch (error) {
      console.warn('Failed to detect handoff opportunities:', error.message);
      return [];
    }
  }

  /**
   * Create enhanced handoff with Claude Code CLI context
   */
  async createEnhancedHandoff(targetAgent, options = {}) {
    try {
      // Generate intelligent context summary
      const contextSummary = await this.generateContextSummary(targetAgent);

      // Detect handoff opportunities
      const opportunities = await this.detectHandoffOpportunities();
      const relevantOpportunity = opportunities.find(opp => opp.targetAgent === targetAgent);

      // Generate smart suggestions for target agent
      const targetSuggestions = await this.generateTargetAgentSuggestions(targetAgent);

      // Create enhanced handoff package
      const handoffData = {
        sourceAgent: this.activeAgent,
        targetAgent: targetAgent,
        sessionContext: this.sessionContext,
        contextSummary: contextSummary,
        handoffOpportunity: relevantOpportunity,
        targetSuggestions: targetSuggestions,
        claudeCodeFeatures: {
          nativeCommands: true,
          autoSuggestions: true,
          contextAware: true,
          sessionContinuity: true
        },
        timestamp: new Date().toISOString()
      };

      // Use existing handoff manager to create the handoff
      const handoffResult = await this.handoffManager.createHandoff(
        this.activeAgent,
        targetAgent,
        this.sessionContext.sessionId,
        handoffData
      );

      // Update context with handoff information
      await this.contextManager.updateSharedContext({
        lastHandoff: {
          from: this.activeAgent,
          to: targetAgent,
          timestamp: handoffData.timestamp,
          handoffId: handoffResult.handoffId
        }
      }, this.sessionContext.sessionId, this.activeAgent);

      return {
        ...handoffResult,
        enhanced: true,
        contextSummary: contextSummary.summary,
        suggestions: targetSuggestions.length
      };

    } catch (error) {
      console.error('Failed to create enhanced handoff:', error.message);
      return { status: 'failed', error: error.message };
    }
  }

  /**
   * Generate intelligent context summary for target agent
   */
  async generateContextSummary(targetAgent) {
    try {
      const sharedContext = await this.contextManager.getSharedContext();
      const decisions = await this.contextManager.getDecisions();
      const progress = await this.contextManager.getProgress();

      const summary = {
        currentFocus: sharedContext.currentFocus || 'No specific focus defined',
        keyDecisions: decisions.slice(-3).map(d => ({
          title: d.title,
          decision: d.decision,
          impact: d.impact || 'Not specified'
        })),
        progressHighlights: {
          completedTasks: progress.completedTasks || 0,
          currentStory: progress.currentStory || 'No active story',
          qualityScore: progress.qualityScore || 'Not assessed'
        },
        nextSteps: this.generateNextSteps(targetAgent, sharedContext, progress),
        contextualNotes: this.generateContextualNotes(targetAgent, sharedContext, decisions)
      };

      return {
        targetAgent: targetAgent,
        summary: summary,
        relevanceScore: this.calculateRelevanceScore(targetAgent, summary),
        generatedAt: new Date().toISOString()
      };

    } catch (error) {
      console.warn('Failed to generate context summary:', error.message);
      return {
        targetAgent: targetAgent,
        summary: { error: 'Context summary unavailable' },
        relevanceScore: 0
      };
    }
  }

  /**
   * Generate smart suggestions for target agent
   */
  async generateTargetAgentSuggestions(targetAgent) {
    const suggestions = [];

    switch (targetAgent) {
      case 'dev':
        suggestions.push(
          'Use *develop-story to implement the next story systematically',
          'Run *reality-audit before marking any work complete',
          'Use *workspace-status to see current development context'
        );
        break;

      case 'qa':
        suggestions.push(
          'Use *reality-audit to perform comprehensive quality validation',
          'Review handoff context for completed development work',
          'Use *create-remediation if issues are found'
        );
        break;

      case 'architect':
        suggestions.push(
          'Review recent architectural decisions in workspace context',
          'Consider system design implications of current work',
          'Use *workspace-sync to get latest project context'
        );
        break;

      case 'sm':
        suggestions.push(
          'Use *draft to create the next development story',
          'Review progress and update project tracking',
          'Consider story scope and team capacity'
        );
        break;

      default:
        suggestions.push(
          'Use *workspace-status to understand current project state',
          'Review handoff context for relevant background',
          'Use *workspace-sync to get latest workspace updates'
        );
    }

    return suggestions;
  }

  /**
   * Generate contextual next steps for target agent
   */
  generateNextSteps(targetAgent, sharedContext, progress) {
    const nextSteps = [];

    // Add agent-specific next steps based on context
    if (targetAgent === 'dev' && progress.currentStory) {
      nextSteps.push(`Continue implementation of: ${progress.currentStory}`);
    }

    if (targetAgent === 'qa' && progress.completedTasks > 0) {
      nextSteps.push('Validate completed development work');
    }

    // Add generic next steps if no specific ones
    if (nextSteps.length === 0) {
      nextSteps.push(`Review workspace context and begin ${targetAgent} activities`);
    }

    return nextSteps;
  }

  /**
   * Generate contextual notes for target agent
   */
  generateContextualNotes(targetAgent, sharedContext, decisions) {
    const notes = [];

    // Add relevant decisions for the target agent
    const relevantDecisions = decisions.filter(d => 
      this.isDecisionRelevant(d, targetAgent)
    );

    if (relevantDecisions.length > 0) {
      notes.push(`${relevantDecisions.length} relevant architectural decisions available`);
    }

    // Add context-specific notes
    if (sharedContext.sessionNotes) {
      notes.push('Previous session context available');
    }

    return notes;
  }

  /**
   * Check if a decision is relevant to the target agent
   */
  isDecisionRelevant(decision, targetAgent) {
    const agentKeywords = {
      'dev': ['implementation', 'code', 'technical', 'development'],
      'qa': ['quality', 'testing', 'validation', 'standards'],
      'architect': ['architecture', 'design', 'structure', 'pattern'],
      'sm': ['scope', 'story', 'planning', 'timeline']
    };

    const keywords = agentKeywords[targetAgent] || [];
    const decisionText = `${decision.title} ${decision.decision}`.toLowerCase();

    return keywords.some(keyword => decisionText.includes(keyword));
  }

  /**
   * Calculate relevance score for context summary
   */
  calculateRelevanceScore(targetAgent, summary) {
    let score = 0.5; // Base score

    // Increase score based on available context
    if (summary.keyDecisions.length > 0) score += 0.2;
    if (summary.progressHighlights.completedTasks > 0) score += 0.2;
    if (summary.currentFocus !== 'No specific focus defined') score += 0.1;

    return Math.min(score, 1.0);
  }

  /**
   * Check workspace health for context-aware suggestions
   */
  async checkWorkspaceHealth() {
    try {
      // Simple health check implementation
      const workspaceDir = path.join(this.workspaceDir, '.workspace');
      const requiredDirs = ['sessions', 'context', 'handoffs', 'decisions', 'progress'];

      let issues = 0;
      for (const dir of requiredDirs) {
        if (!fs.existsSync(path.join(workspaceDir, dir))) {
          issues++;
        }
      }

      return { issues, healthy: issues === 0 };
    } catch (error) {
      return { issues: 1, healthy: false };
    }
  }
}

