#!/usr/bin/env node

const { program } = require('commander');
const path = require('path');
const fs = require('fs').promises;
const yaml = require('js-yaml');
const chalk = require('chalk');
const inquirer = require('inquirer');

// Handle both execution contexts (from root via npx or from installer directory)
let version;
let installer;
try {
  // Try installer context first (when run from tools/installer/)
  version = require('../package.json').version;
  installer = require('../lib/installer');
} catch (e) {
  // Fall back to root context (when run via npx from GitHub)
  console.log(`Installer context not found (${e.message}), trying root context...`);
  try {
    version = require('../../../package.json').version;
    installer = require('../../../tools/installer/lib/installer');
  } catch (e2) {
    console.error('Error: Could not load required modules. Please ensure you are running from the correct directory.');
    console.error('Debug info:', {
      __dirname,
      cwd: process.cwd(),
      error: e2.message
    });
    process.exit(1);
  }
}

program
  .version(version)
  .description('BMad Method installer - Universal AI agent framework for any domain');

program
  .command('install')
  .description('Install BMad Method agents and tools')
  .option('-f, --full', 'Install complete BMad Method')
  .option('-x, --expansion-only', 'Install only expansion packs (no bmad-core)')
  .option('-d, --directory <path>', 'Installation directory')
  .option('-i, --ide <ide...>', 'Configure for specific IDE(s) - can specify multiple (cursor, claude-code, windsurf, trae, roo, cline, gemini, github-copilot, other)')
  .option('-e, --expansion-packs <packs...>', 'Install specific expansion packs (can specify multiple)')
  .action(async (options) => {
    try {
      if (!options.full && !options.expansionOnly) {
        // Interactive mode
        const answers = await promptInstallation();
        if (!answers._alreadyInstalled) {
          await installer.install(answers);
          process.exit(0);
        }
      } else {
        // Direct mode
        let installType = 'full';
        if (options.expansionOnly) installType = 'expansion-only';

        const config = {
          installType,
          directory: options.directory || '.',
          ides: (options.ide || []).filter(ide => ide !== 'other'),
          expansionPacks: options.expansionPacks || []
        };
        await installer.install(config);
        process.exit(0);
      }
    } catch (error) {
      console.error(chalk.red('Installation failed:'), error.message);
      process.exit(1);
    }
  });

program
  .command('update')
  .description('Update existing BMad installation')
  .option('--force', 'Force update, overwriting modified files')
  .option('--dry-run', 'Show what would be updated without making changes')
  .action(async () => {
    try {
      await installer.update();
    } catch (error) {
      console.error(chalk.red('Update failed:'), error.message);
      process.exit(1);
    }
  });

program
  .command('list:expansions')
  .description('List available expansion packs')
  .action(async () => {
    try {
      await installer.listExpansionPacks();
    } catch (error) {
      console.error(chalk.red('Error:'), error.message);
      process.exit(1);
    }
  });

program
  .command('status')
  .description('Show installation status')
  .action(async () => {
    try {
      await installer.showStatus();
    } catch (error) {
      console.error(chalk.red('Error:'), error.message);
      process.exit(1);
    }
  });

program
  .command('flatten')
  .description('Flatten codebase into a single XML file for AI analysis')
  .option('-o, --output <path>', 'Output file path', 'flattened-codebase.xml')
  .action(async (options) => {
    console.log(`Flattening codebase to: ${options.output}`);

    try {
      // Import flattener functions
      const { 
        discoverFiles, 
        aggregateFileContents, 
        generateXMLOutput, 
        calculateStatistics,
        filterFiles 
      } = require('../../flattener/main');

      // Import ora dynamically
      const { default: ora } = await import('ora');
      const fs = require('fs-extra');

      // Start file discovery with spinner
      const discoverySpinner = ora('🔍 Discovering files...').start();
      const files = await discoverFiles(process.cwd());
      const filteredFiles = await filterFiles(files, process.cwd());
      discoverySpinner.succeed(`📁 Found ${filteredFiles.length} files to include`);

      // Process files with progress tracking
      console.log('Reading file contents');
      const processingSpinner = ora('📄 Processing files...').start();
      const aggregatedContent = await aggregateFileContents(filteredFiles, process.cwd(), processingSpinner);
      processingSpinner.succeed(`✅ Processed ${aggregatedContent.processedFiles}/${filteredFiles.length} files`);

      // Log processing results for test validation
      console.log(`Processed ${aggregatedContent.processedFiles}/${filteredFiles.length} files`);
      if (aggregatedContent.errors.length > 0) {
        console.log(`Errors: ${aggregatedContent.errors.length}`);
      }
      console.log(`Text files: ${aggregatedContent.textFiles.length}`);
      if (aggregatedContent.binaryFiles.length > 0) {
        console.log(`Binary files: ${aggregatedContent.binaryFiles.length}`);
      }

      // Generate XML output using streaming
      const xmlSpinner = ora('🔧 Generating XML output...').start();
      await generateXMLOutput(aggregatedContent, options.output);
      xmlSpinner.succeed('📝 XML generation completed');

      // Calculate and display statistics
      const outputStats = await fs.stat(options.output);
      const stats = calculateStatistics(aggregatedContent, outputStats.size);

      // Display completion summary
      console.log('\n📊 Completion Summary:');
      console.log(`✅ Successfully processed ${filteredFiles.length} files into ${options.output}`);
      console.log(`📁 Output file: ${path.resolve(options.output)}`);
      console.log(`📏 Total source size: ${stats.totalSize}`);
      console.log(`📄 Generated XML size: ${stats.xmlSize}`);
      console.log(`📝 Total lines of code: ${stats.totalLines.toLocaleString()}`);
      console.log(`🔢 Estimated tokens: ${stats.estimatedTokens}`);
      console.log(`📊 File breakdown: ${stats.textFiles} text, ${stats.binaryFiles} binary, ${stats.errorFiles} errors`);

    } catch (error) {
      console.error(chalk.red('❌ Critical error:'), error.message);
      console.error('An unexpected error occurred.');
      process.exit(1);
    }
  });

async function promptInstallation() {

  // Display ASCII logo
  console.log(chalk.bold.cyan(`
██████╗ ███╗   ███╗ █████╗ ██████╗       ███╗   ███╗███████╗████████╗██╗  ██╗ ██████╗ ██████╗ 
██╔══██╗████╗ ████║██╔══██╗██╔══██╗      ████╗ ████║██╔════╝╚══██╔══╝██║  ██║██╔═══██╗██╔══██╗
██████╔╝██╔████╔██║███████║██║  ██║█████╗██╔████╔██║█████╗     ██║   ███████║██║   ██║██║  ██║
██╔══██╗██║╚██╔╝██║██╔══██║██║  ██║╚════╝██║╚██╔╝██║██╔══╝     ██║   ██╔══██║██║   ██║██║  ██║
██████╔╝██║ ╚═╝ ██║██║  ██║██████╔╝      ██║ ╚═╝ ██║███████╗   ██║   ██║  ██║╚██████╔╝██████╔╝
╚═════╝ ╚═╝     ╚═╝╚═╝  ╚═╝╚═════╝       ╚═╝     ╚═╝╚══════╝   ╚═╝   ╚═╝  ╚═╝ ╚═════╝ ╚═════╝ 
  `));

  console.log(chalk.bold.magenta('🚀 Universal AI Agent Framework for Any Domain'));
  console.log(chalk.bold.blue(`✨ Installer v${version}\n`));

  const answers = {};

  // Ask for installation directory first
  const { directory } = await inquirer.prompt([
    {
      type: 'input',
      name: 'directory',
      message: 'Enter the full path to your project directory where BMad should be installed:',
      validate: (input) => {
        if (!input.trim()) {
          return 'Please enter a valid project path';
        }
        return true;
      }
    }
  ]);
  answers.directory = directory;

  // Detect existing installations
  const installDir = path.resolve(directory);
  const state = await installer.detectInstallationState(installDir);

  // Check for existing expansion packs
  const existingExpansionPacks = state.expansionPacks || {};

  // Get available expansion packs
  const availableExpansionPacks = await installer.getAvailableExpansionPacks();

  // Build choices list
  const choices = [];

  // Load core config to get short-title
  const coreConfigPath = path.join(__dirname, '..', '..', '..', 'bmad-core', 'core-config.yaml');
  const coreConfig = yaml.load(await fs.readFile(coreConfigPath, 'utf8'));
  const coreShortTitle = coreConfig['short-title'] || 'BMad Agile Core System';

  // Add BMad core option
  let bmadOptionText;
  if (state.type === 'v4_existing') {
    const currentVersion = state.manifest?.version || 'unknown';
    const newVersion = version; // Always use package.json version
    const versionInfo = currentVersion === newVersion 
      ? `(v${currentVersion} - reinstall)`
      : `(v${currentVersion} → v${newVersion})`;
    bmadOptionText = `Update ${coreShortTitle} ${versionInfo} .bmad-core`;
  } else {
    bmadOptionText = `${coreShortTitle} (v${version}) .bmad-core`;
  }

  choices.push({
    name: bmadOptionText,
    value: 'bmad-core',
    checked: true
  });

  // Add expansion pack options
  for (const pack of availableExpansionPacks) {
    const existing = existingExpansionPacks[pack.id];
    let packOptionText;

    if (existing) {
      const currentVersion = existing.manifest?.version || 'unknown';
      const newVersion = pack.version;
      const versionInfo = currentVersion === newVersion 
        ? `(v${currentVersion} - reinstall)`
        : `(v${currentVersion} → v${newVersion})`;
      packOptionText = `Update ${pack.shortTitle} ${versionInfo} .${pack.id}`;
    } else {
      packOptionText = `${pack.shortTitle} (v${pack.version}) .${pack.id}`;
    }

    choices.push({
      name: packOptionText,
      value: pack.id,
      checked: false
    });
  }

  // Ask what to install
  const { selectedItems } = await inquirer.prompt([
    {
      type: 'checkbox',
      name: 'selectedItems',
      message: 'Select what to install/update (use space to select, enter to continue):',
      choices: choices,
      validate: (selected) => {
        if (selected.length === 0) {
          return 'Please select at least one item to install';
        }
        return true;
      }
    }
  ]);

  // Process selections
  answers.installType = selectedItems.includes('bmad-core') ? 'full' : 'expansion-only';
  answers.expansionPacks = selectedItems.filter(item => item !== 'bmad-core');

  // Ask sharding questions if installing BMad core
  if (selectedItems.includes('bmad-core')) {
    console.log(chalk.cyan('\n📋 Document Organization Settings'));
    console.log(chalk.dim('Configure how your project documentation should be organized.\n'));

    // Ask about PRD sharding
    const { prdSharded } = await inquirer.prompt([
      {
        type: 'confirm',
        name: 'prdSharded',
        message: 'Will the PRD (Product Requirements Document) be sharded into multiple files?',
        default: true
      }
    ]);
    answers.prdSharded = prdSharded;

    // Ask about architecture sharding
    const { architectureSharded } = await inquirer.prompt([
      {
        type: 'confirm',
        name: 'architectureSharded',
        message: 'Will the architecture documentation be sharded into multiple files?',
        default: true
      }
    ]);
    answers.architectureSharded = architectureSharded;

    // Show warning if architecture sharding is disabled
    if (!architectureSharded) {
      console.log(chalk.yellow.bold('\n⚠️  IMPORTANT: Architecture Sharding Disabled'));
      console.log(chalk.yellow('With architecture sharding disabled, you should still create the files listed'));
      console.log(chalk.yellow('in devLoadAlwaysFiles (like coding-standards.md, tech-stack.md, source-tree.md)'));
      console.log(chalk.yellow('as these are used by the dev agent at runtime.'));
      console.log(chalk.yellow('\nAlternatively, you can remove these files from the devLoadAlwaysFiles list'));
      console.log(chalk.yellow('in your core-config.yaml after installation.'));

      const { acknowledge } = await inquirer.prompt([
        {
          type: 'confirm',
          name: 'acknowledge',
          message: 'Do you acknowledge this requirement and want to proceed?',
          default: false
        }
      ]);

      if (!acknowledge) {
        console.log(chalk.red('Installation cancelled.'));
        process.exit(0);
      }
    }
  }

  // Ask for IDE configuration
  let ides = [];
  let ideSelectionComplete = false;

  while (!ideSelectionComplete) {
    console.log(chalk.cyan('\n🛠️  IDE Configuration'));
    console.log(chalk.bold.yellow.bgRed(' ⚠️  IMPORTANT: This is a MULTISELECT! Use SPACEBAR to toggle each IDE! '));
    console.log(chalk.bold.magenta('🔸 Use arrow keys to navigate'));
    console.log(chalk.bold.magenta('🔸 Use SPACEBAR to select/deselect IDEs'));
    console.log(chalk.bold.magenta('🔸 Press ENTER when finished selecting\n'));

    const ideResponse = await inquirer.prompt([
      {
        type: 'checkbox',
        name: 'ides',
        message: 'Which IDE(s) do you want to configure? (Select with SPACEBAR, confirm with ENTER):',
        choices: [
          { name: 'Cursor', value: 'cursor' },
          { name: 'Claude Code', value: 'claude-code' },
          { name: 'Windsurf', value: 'windsurf' },
          { name: 'Trae', value: 'trae' }, // { name: 'Trae', value: 'trae'}
          { name: 'Roo Code', value: 'roo' },
          { name: 'Cline', value: 'cline' },
          { name: 'Gemini CLI', value: 'gemini' },
          { name: 'Github Copilot', value: 'github-copilot' }
        ]
      }
    ]);

    ides = ideResponse.ides;

    // Confirm no IDE selection if none selected
    if (ides.length === 0) {
      const { confirmNoIde } = await inquirer.prompt([
        {
          type: 'confirm',
          name: 'confirmNoIde',
          message: chalk.red('⚠️  You have NOT selected any IDEs. This means NO IDE integration will be set up. Is this correct?'),
          default: false
        }
      ]);

      if (!confirmNoIde) {
        console.log(chalk.bold.red('\n🔄 Returning to IDE selection. Remember to use SPACEBAR to select IDEs!\n'));
        continue; // Go back to IDE selection only
      }
    }

    ideSelectionComplete = true;
  }

  // Use selected IDEs directly
  answers.ides = ides;

  // Ask about Collaborative Workspace System
  if (selectedItems.includes('bmad-core')) {
    console.log(chalk.cyan('\n🤝 Collaborative Workspace System'));
    console.log(chalk.dim('Enable multi-session AI agent coordination and context persistence.\n'));

    const { enableWorkspace } = await inquirer.prompt([
      {
        type: 'confirm',
        name: 'enableWorkspace',
        message: chalk.magenta('🚀 Enable Collaborative Workspace System?') + 
                 '\n   • Multi-session AI agent coordination' +
                 '\n   • Context persistence across sessions' + 
                 '\n   • Cross-IDE collaboration support' +
                 '\n   • Enhanced workflow automation' +
                 '\n   Enable workspace system?',
        default: true
      }
    ]);

    answers.enableWorkspace = enableWorkspace;

    if (enableWorkspace) {
      console.log(chalk.green('✅ Collaborative Workspace System will be configured during installation'));

      if (ides.includes('claude-code')) {
        console.log(chalk.blue('🎯 Claude Code CLI users will get native workspace commands'));
      }

      if (ides.some(ide => ide !== 'claude-code')) {
        console.log(chalk.blue('🛠️  Other IDE users will get comprehensive utility scripts'));
      }
    } else {
      console.log(chalk.yellow('⚠️  Workspace system disabled - standard BMAD functionality only'));
    }
  }

  // Configure GitHub Copilot immediately if selected
  if (ides.includes('github-copilot')) {
    console.log(chalk.cyan('\n🔧 GitHub Copilot Configuration'));
    console.log(chalk.dim('BMad works best with specific VS Code settings for optimal agent experience.\n'));

    const { configChoice } = await inquirer.prompt([
      {
        type: 'list',
        name: 'configChoice',
        message: chalk.yellow('How would you like to configure GitHub Copilot settings?'),
        choices: [
          {
            name: 'Use recommended defaults (fastest setup)',
            value: 'defaults'
          },
          {
            name: 'Configure each setting manually (customize to your preferences)',
            value: 'manual'
          },
          {
            name: 'Skip settings configuration (I\'ll configure manually later)',
            value: 'skip'
          }
        ],
        default: 'defaults'
      }
    ]);

    answers.githubCopilotConfig = { configChoice };
  }

  // Ask for web bundles installation
  const { includeWebBundles } = await inquirer.prompt([
    {
      type: 'confirm',
      name: 'includeWebBundles',
      message: 'Would you like to include pre-built web bundles? (standalone files for ChatGPT, Claude, Gemini)',
      default: false
    }
  ]);

  if (includeWebBundles) {
    console.log(chalk.cyan('\n📦 Web bundles are standalone files perfect for web AI platforms.'));
    console.log(chalk.dim('   You can choose different teams/agents than your IDE installation.\n'));

    const { webBundleType } = await inquirer.prompt([
      {
        type: 'list',
        name: 'webBundleType',
        message: 'What web bundles would you like to include?',
        choices: [
          {
            name: 'All available bundles (agents, teams, expansion packs)',
            value: 'all'
          },
          {
            name: 'Specific teams only',
            value: 'teams'
          },
          {
            name: 'Individual agents only',
            value: 'agents'
          },
          {
            name: 'Custom selection',
            value: 'custom'
          }
        ]
      }
    ]);

    answers.webBundleType = webBundleType;

    // If specific teams, let them choose which teams
    if (webBundleType === 'teams' || webBundleType === 'custom') {
      const teams = await installer.getAvailableTeams();
      const { selectedTeams } = await inquirer.prompt([
        {
          type: 'checkbox',
          name: 'selectedTeams',
          message: 'Select team bundles to include:',
          choices: teams.map(t => ({
            name: `${t.icon || '📋'} ${t.name}: ${t.description}`,
            value: t.id,
            checked: webBundleType === 'teams' // Check all if teams-only mode
          })),
          validate: (answer) => {
            if (answer.length < 1) {
              return 'You must select at least one team.';
            }
            return true;
          }
        }
      ]);
      answers.selectedWebBundleTeams = selectedTeams;
    }

    // If custom selection, also ask about individual agents
    if (webBundleType === 'custom') {
      const { includeIndividualAgents } = await inquirer.prompt([
        {
          type: 'confirm',
          name: 'includeIndividualAgents',
          message: 'Also include individual agent bundles?',
          default: true
        }
      ]);
      answers.includeIndividualAgents = includeIndividualAgents;
    }

    const { webBundlesDirectory } = await inquirer.prompt([
      {
        type: 'input',
        name: 'webBundlesDirectory',
        message: 'Enter directory for web bundles:',
        default: `${answers.directory}/web-bundles`,
        validate: (input) => {
          if (!input.trim()) {
            return 'Please enter a valid directory path';
          }
          return true;
        }
      }
    ]);
    answers.webBundlesDirectory = webBundlesDirectory;
  }

  answers.includeWebBundles = includeWebBundles;

  return answers;
}

program.parse(process.argv);

// Show help if no command provided
if (!process.argv.slice(2).length) {
  program.outputHelp();
}

from core.config import MOVEMENT_DATA, XP_MULTIPLIER_PER_LEVEL import math from typing import Optional
from core.database import db
def get_xp_required_for_level(level: int) -> int: return int(100 * (XP_MULTIPLIER_PER_LEVEL ** (level - 1)))
async def add_stat_xp(connection, user_id: int, movement: str, reps: int, bot=None): movement_info = MOVEMENT_DATA.get(movement) if not movement_info: return
BASE_REP_VALUE = 0.5 TIER_MULTIPLIERS = {1: 1.0, 2: 1.2, 3: 1.5, 4: 2.0, 5: 2.5}
target_stat = movement_info["stat"] exercise_tier = movement_info["tier"]
is_hold = "Hold" in movement or "Plank" in movement or "Sit" in movement effective_reps = math.ceil(reps / 5) if is_hold else reps
tier_multiplier = TIER_MULTIPLIERS.get(exercise_tier, 1.0) stat_xp_gained = (BASE_REP_VALUE * effective_reps) * tier_multiplier
stats = await db.get_user_stats(connection, user_id) current_stat = stats[target_stat] current_stat['xp'] += stat_xp_gained
xp_for_next_level = 100 * current_stat['level'] while current_stat['xp'] >= xp_for_next_level: current_stat['level'] += 1 current_stat['xp'] -= xp_for_next_level xp_for_next_level = 100 * current_stat['level']
await db.update_user_stat(connection, user_id, target_stat, current_stat['level'], current_stat['xp'], bot=bot)
async def add_xp(connection, user_id: int, xp_to_add: int, movement: Optional[str] = None, reps: int = 0, bot=None): if movement and reps > 0: await add_stat_xp(connection, user_id, movement, reps, bot=bot) user_data = await db.get_user(connection, user_id) if not user_data: user_data = {} current_xp = user_data.get("xp", 0) current_level = user_data.get("level", 1) final_xp_gain = xp_to_add new_xp = current_xp + final_xp_gain new_level = current_level xp_for_next_level = user_data.get("xp_max") or get_xp_required_for_level(new_level) leveled_up = False while new_xp >= xp_for_next_level: new_xp -= xp_for_next_level new_level += 1 xp_for_next_level = get_xp_required_for_level(new_level) leveled_up = True await db.update_user(connection, user_id, xp=new_xp, level=new_level, xp_max=xp_for_next_level, bot=bot) return {"xp_gain": final_xp_gain, "leveled_up": leveled_up, "new_level": new_level}
def calculate_xp_for_movement(movement: str, reps: int) -> int: movement_info = MOVEMENT_DATA.get(movement) if not movement_info: return 0 xp_per_rep = movement_info["xp"] return math.ceil(xp_per_rep * reps)

from typing import Dict, Optional
from features.user.logic.user_data import load_user_data, save_user_data

from core.config import CLASS_EVOLUTIONS

def get_class_for_level(level: int) -> dict:
    """Get the current class evolution for a level."""
    current_class = CLASS_EVOLUTIONS[1]
    for evo_level, evo_data in CLASS_EVOLUTIONS.items():
        if level >= evo_level:
            current_class = evo_data
        else:
            break
    return current_class

def get_next_evolution(level: int) -> Optional[Dict]:
    """Get the next class evolution milestone."""
    for evo_level, evo_data in sorted(CLASS_EVOLUTIONS.items()):
        if level < evo_level:
            return {"level": evo_level, "evolution": evo_data}
    return None

async def check_evolution_unlock(user_id: int, new_level: int) -> Optional[Dict]:
    """Check if user unlocked a new evolution and apply rewards."""
    user_data = await load_user_data(user_id)
    # This logic assumes you have a 'passive_buffs' system to apply rewards
    # For now, it just tracks completed evolutions.
    completed = user_data.setdefault("completed_evolutions", [])

    unlocked_evolution = None
    for evo_level, evo_data in CLASS_EVOLUTIONS.items():
        if new_level >= evo_level and evo_level not in completed:
            completed.append(evo_level)
            unlocked_evolution = {"level": evo_level, "evolution": evo_data, "unlocked": True}

    if unlocked_evolution:
        await save_user_data(user_id, user_data)
        return unlocked_evolution

    return None

async def get_passive_bonuses(user_id: int) -> Dict:
    """Get all active passive bonuses for a user."""
    user_data = await load_user_data(user_id)
    return user_data.get("passive_buffs", {})

from dataclasses import dataclass from datetime import datetime, timezone from typing import Dict, Any, Optional from enum import Enum
class IncursionType(Enum): SURGE = "surge" CHALLENGE = "challenge" ANOMALY = "anomaly"
class RewardType(Enum): XP = "xp" BUFF = "buff" ITEM = "item"
@dataclass class Incursion: """Core data model for Shadow Incursions""" id: int incursion_id: str incursion_type: IncursionType title: str description: str target_exercise: str target_reps: int current_reps: int reward_type: RewardType reward_value: int reward_description: str created_at: datetime expires_at: datetime is_active: bool metadata: Dict[str, Any]
@property def progress_percentage(self) -> float: """Calculate completion percentage""" if self.target_reps == 0: return 0.0 return min(100.0, (self.current_reps / self.target_reps) * 100)
@property def is_completed(self) -> bool: """Check if incursion is completed""" return self.current_reps >= self.target_reps
@property def is_expired(self) -> bool: """Check if incursion has expired""" return datetime.now(timezone.utc) > self.expires_at
@property def time_remaining(self) -> Optional[str]: """Get human-readable time remaining with color coding""" if self.is_expired: return None
delta = self.expires_at - datetime.now(timezone.utc) total_seconds = int(delta.total_seconds())
hours = total_seconds // 3600 minutes = (total_seconds % 3600) // 60 seconds = total_seconds % 60
# Determine color based on time remaining if total_seconds > 1800: # > 30 minutes color = "\x1b[1;32m" # Bright green elif total_seconds > 300: # > 5 minutes color = "\x1b[1;33m" # Bright yellow/orange else: # <= 5 minutes color = "\x1b[1;31m" # Bright red
reset = "\x1b[0m" # Reset color
# Format based on time remaining if hours > 0: return f"{color}{hours}h {minutes}m {seconds}s{reset}" elif minutes > 0: return f"{color}{minutes}m {seconds}s{reset}" else: return f"{color}{seconds}s{reset}"

import random from datetime import datetime, timedelta from typing import Dict, List, Tuple from features.incursions.models.incursion import IncursionType, RewardType
class IncursionContentGenerator: """Generates thematic content for Shadow Incursions"""
# Content templates organized by incursion type SURGE_TEMPLATES = [ { "title": "🌊 Crimson Tide Surge", "description": "The shadows pulse with ancient energy, amplifying all training efforts. Strike while the darkness flows through you!", "effect": "All XP gains increased by 50% for the next 60 minutes", "target_exercise": "any", "target_reps": 0, # No specific target for surge events "reward_type": RewardType.XP, "reward_value": 50, # 50% XP boost "duration_hours": 1 }, { "title": "⚡ Lightning Reflexes Surge", "description": "Electric energy crackles through the realm. Your movements become swift and precise!", "effect": "All exercises grant +1 bonus rep for progression tracking", "target_exercise": "any", "target_reps": 0, "reward_type": RewardType.BUFF, "reward_value": 1, "duration_hours": 2 }, { "title": "🔥 Infernal Focus Surge", "description": "The fires of determination burn bright. Channel this intensity into your training!", "effect": "Next 3 completed quests grant double STR/END/TECH XP", "target_exercise": "any", "target_reps": 0, "reward_type": RewardType.BUFF, "reward_value": 2, "duration_hours": 4 } ]
CHALLENGE_TEMPLATES = [ { "title": "💀 Shadow Wraith Challenge", "description": "A spectral enemy emerges from the void. Prove your upper body dominance to banish it back to the shadows!", "target_exercise": "pull_ups", "target_reps": 100, "reward_type": RewardType.XP, "reward_value": 300, "duration_hours": 6 }, { "title": "🗡️ Blade Master's Trial", "description": "The ancient blade masters test your pushing power. Show them the strength of your resolve!", "target_exercise": "push_ups", "target_reps": 150, "reward_type": RewardType.XP, "reward_value": 250, "duration_hours": 8 }, { "title": "🏔️ Mountain's Endurance", "description": "The mountain spirits challenge your leg strength. Climb to new heights of power!", "target_exercise": "squats", "target_reps": 200, "reward_type": RewardType.XP, "reward_value": 275, "duration_hours": 12 }, { "title": "🌪️ Tempest Core Trial", "description": "Chaotic winds test your stability. Prove your core is unshakeable!", "target_exercise": "plank_seconds", "target_reps": 600, # 10 minutes total "reward_type": RewardType.XP, "reward_value": 200, "duration_hours": 6 } ]
ANOMALY_TEMPLATES = [ { "title": "🌀 Gravitational Flux", "description": "Reality bends around you. Reps are harder to achieve, but the rewards are magnificent!", "effect": "All reps count as 0.5x, but XP rewards are doubled", "target_exercise": "any", "target_reps": 0, "reward_type": RewardType.BUFF, "reward_value": 200, # 200% XP multiplier "duration_hours": 3, "metadata": {"rep_multiplier": 0.5, "xp_multiplier": 2.0} }, { "title": "⏰ Temporal Acceleration", "description": "Time moves differently in the shadow realm. Quick bursts of activity yield exponential gains!", "effect": "Sets of 10+ reps in under 30 seconds grant triple XP", "target_exercise": "any", "target_reps": 0, "reward_type": RewardType.BUFF, "reward_value": 300, "duration_hours": 2, "metadata": {"speed_bonus": True, "time_limit": 30} }, { "title": "🎭 Mirror Dimension", "description": "Your reflection challenges you to a duel. Every rep must be matched by its mirror!", "effect": "All exercises must be performed in pairs (2x reps), but grant 150% XP", "target_exercise": "any", "target_reps": 0, "reward_type": RewardType.BUFF, "reward_value": 150, "duration_hours": 4, "metadata": {"pair_requirement": True, "xp_multiplier": 1.5} } ]
# Exercise mappings for V-taper focus V_TAPER_EXERCISES = { "pull_ups": {"category": "back_width", "priority": "high"}, "chin_ups": {"category": "back_width", "priority": "high"}, "wide_grip_pull_ups": {"category": "back_width", "priority": "very_high"}, "lateral_raises": {"category": "shoulder_width", "priority": "very_high"}, "pike_push_ups": {"category": "shoulder_width", "priority": "high"}, "handstand_push_ups": {"category": "shoulder_width", "priority": "high"}, "push_ups": {"category": "chest_shoulders", "priority": "medium"}, "diamond_push_ups": {"category": "triceps", "priority": "medium"}, "squats": {"category": "legs", "priority": "low"}, "lunges": {"category": "legs", "priority": "low"}, "plank_seconds": {"category": "core", "priority": "medium"} }
def generate_surge_incursion(self) -> Dict: """Generate a random surge incursion""" template = random.choice(self.SURGE_TEMPLATES) incursion_id = f"SURGE_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
return { "incursion_id": incursion_id, "incursion_type": IncursionType.SURGE, "title": template["title"], "description": template["description"], "target_exercise": template["target_exercise"], "target_reps": template["target_reps"], "reward_type": template["reward_type"], "reward_value": template["reward_value"], "reward_description": template["effect"], "duration_hours": template["duration_hours"], "metadata": template.get("metadata", {}) }
def generate_challenge_incursion(self, focus_v_taper: bool = True) -> Dict: """Generate a challenge incursion, optionally focused on V-taper development""" if focus_v_taper: # Prioritize V-taper exercises v_taper_templates = [ t for t in self.CHALLENGE_TEMPLATES if t["target_exercise"] in self.V_TAPER_EXERCISES and self.V_TAPER_EXERCISES[t["target_exercise"]]["priority"] in ["high", "very_high"] ] template = random.choice(v_taper_templates if v_taper_templates else self.CHALLENGE_TEMPLATES) else: template = random.choice(self.CHALLENGE_TEMPLATES)
incursion_id = f"CHALLENGE_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
# Add some randomization to target reps (±20%) base_reps = template["target_reps"] variation = random.uniform(0.8, 1.2) target_reps = int(base_reps * variation)
return { "incursion_id": incursion_id, "incursion_type": IncursionType.CHALLENGE, "title": template["title"], "description": template["description"], "target_exercise": template["target_exercise"], "target_reps": target_reps, "reward_type": template["reward_type"], "reward_value": template["reward_value"], "reward_description": f"{template['reward_value']} XP for completing the challenge", "duration_hours": template["duration_hours"], "metadata": {"base_reps": base_reps, "variation": variation} }
def generate_anomaly_incursion(self) -> Dict: """Generate a reality-bending anomaly incursion""" template = random.choice(self.ANOMALY_TEMPLATES) incursion_id = f"ANOMALY_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
return { "incursion_id": incursion_id, "incursion_type": IncursionType.ANOMALY, "title": template["title"], "description": template["description"], "target_exercise": template["target_exercise"], "target_reps": template["target_reps"], "reward_type": template["reward_type"], "reward_value": template["reward_value"], "reward_description": template["effect"], "duration_hours": template["duration_hours"], "metadata": template.get("metadata", {}) }
def generate_random_incursion(self, v_taper_bias: float = 0.7) -> Dict: """Generate a random incursion with weighted probabilities""" # Weighted probabilities: Surge (50%), Challenge (35%), Anomaly (15%) incursion_type = random.choices( ["surge", "challenge", "anomaly"], weights=[50, 35, 15] )[0]
if incursion_type == "surge": return self.generate_surge_incursion() elif incursion_type == "challenge": # 70% chance to focus on V-taper exercises focus_v_taper = random.random() < v_taper_bias return self.generate_challenge_incursion(focus_v_taper) else: return self.generate_anomaly_incursion()

