import requests import json from datetime import datetime, timedelta from typing import Optional, Dict, Any from features.user.logic.user_data import load_user_data, save_user_data
class FitnessIntegrations: """Handle integrations with Garmin Connect"""
@staticmethod async def sync_garmin_steps(user_id: int, access_token: str, access_token_secret: str) -> Optional[int]: """Sync steps from Garmin Connect IQ API""" try: yesterday = (datetime.now() - timedelta(days=1)).strftime("%Y-%m-%d")
url = f"https://apis.garmin.com/wellness-api/rest/dailies" params = { "uploadStartTimeInSeconds": int((datetime.now() - timedelta(days=1)).timestamp()), "uploadEndTimeInSeconds": int(datetime.now().timestamp()) }
# Note: Garmin uses OAuth 1.0a, you'll need proper signing headers = { "Authorization": f"OAuth oauth_token=\"{access_token}\"" }
response = requests.get(url, params=params, headers=headers)
if response.status_code == 200: data = response.json() for daily in data: steps = daily.get("totalSteps", 0) if steps > 0: await FitnessIntegrations._log_steps_as_movement(user_id, steps) return steps
except Exception as e: print(f"Garmin sync error: {e}")
return None
@staticmethod async def _log_steps_as_movement(user_id: int, steps: int): """Convert steps to movement reps and log them""" # Convert steps to equivalent reps (e.g., 1000 steps = 100 "walking" reps) walking_reps = max(1, steps // 100) # At least 1 rep
# Log as walking movement from features.quests.logic.daily_quests.daily_quest_logic import update_quest_progress from features.quests.ui.weekly.weekly_contract_panel import update_weekly_progress from features.user.logic.xp_engine import add_xp, calculate_xp_for_movement from features.user.logic.user_data import load_user_data, save_user_data
# Update user stats data = await load_user_data(user_id) stats = data.setdefault("log_stats", {}) stats["walking"] = stats.get("walking", 0) + walking_reps
# Add XP only (no quest/contract progress) xp_earned = calculate_xp_for_movement("Walking", walking_reps) await add_xp(user_id, xp_earned) # If add_xp expects (user_id, xp_to_add), use: # await add_xp(user_id, xp_earned) # If it expects (xp_to_add, user_id), use: # await add_xp(xp_earned, user_id) # If signature is different, please adjust accordingly.
await save_user_data(user_id, data) print(f"Auto-synced {steps} steps as {walking_reps} walking reps for user {user_id}")
@staticmethod async def setup_fitness_sync(user_id: int, platform: str, credentials: Dict[str, str]): """Setup automatic fitness syncing for a user (Garmin only)""" if platform != "garmin": return False
data = await load_user_data(user_id) fitness_config = data.setdefault("fitness_integrations", {})
fitness_config[platform] = { "enabled": True, "credentials": credentials, "last_sync": None }
await save_user_data(user_id, data) return True from features.quests.logic.daily_quests.daily_quest_logic import update_quest_progress

""" Enhanced Awakening Panel UI - V2 Integrates with the new API-first architecture and backend services. """
import discord import asyncio import sentry_sdk import logging import httpx from typing import Union, Dict, Any, Optional, List from datetime import date
from shared.utils.ui_helpers import run_with_animation from shared.utils.headers import get_system_status_header from shared.utils.ui_styles import get_panel_sub_header from shared.utils.panel_registry import register from core.api_client import APIClient from shared.utils.error_helpers import handle_panel_errors
logger = logging.getLogger(__name__)
# --- UTILITY FUNCTIONS ---
def _map_tier_to_name(tier_value): """Map numeric tier values to tier names""" if isinstance(tier_value, int): tier_mapping = {1: "shadow", 2: "warrior", 3: "ascendant"} return tier_mapping.get(tier_value, "shadow") elif isinstance(tier_value, str): return tier_value.lower() return "shadow"
# --- FALLBACK AND ERROR EMBEDS ---
async def _create_fallback_embed(user: discord.User, error_type: str) -> discord.Embed: """Create a fallback embed for when the API is unavailable.""" header = get_system_status_header(user).replace('```ansi', '').replace('```', '').strip() sub_header = get_panel_sub_header("awakening") content = ( f"```ansi
" f"{header}
" f"{sub_header}

" f"\x1b[1;31m● System Alert: Service Unreachable\x1b[0m
" f"Status: \x1b[1;31m❌ OFFLINE\x1b[0m
" f"Reason: \x1b[1;33m{error_type}\x1b[0m

" f"\x1b[1;37mThe Awakening system is currently unable to
" f"connect to the central archives. Your data is
" f"safe, but services are temporarily unavailable.

" f"\x1b[1;37mPlease try again shortly.
" f"──────────────────────────
" f"```" ) embed = discord.Embed(description=content, color=discord.Color.red()) embed.set_footer(text="Shadow Archive • System Alert") return embed
async def _build_quest_sync_pending_embed(header: str, sub_header: str) -> discord.Embed: """Build an embed for when quest data is still synchronizing.""" content = ( f"```ansi
" f"{header}
" f"{sub_header}

" f"\x1b[1;33m● Awakening Data Synchronization\x1b[0m
" f"Status: \x1b[1;33m🔄 PENDING\x1b[0m

" f"\x1b[1;37mYour awakening session is active, but quest
" f"data is still being synchronized from the
" f"archives. This may take a few moments.

" f"\x1b[1;37mPlease wait for synchronization to complete.
" f"──────────────────────────
" f"```" ) embed = discord.Embed(description=content, color=discord.Color.orange()) embed.set_footer(text="Shadow Archive • Data Synchronization") return embed
# --- MAIN AWAKENING PANEL ---
@register class EnhancedAwakeningPanel: key = "awakening" label = "Awakening" emoji = "🌅"
@staticmethod async def render_embed(bot, user: discord.User, **kwargs) -> discord.Embed: return await build_enhanced_awakening_embed(bot, user)
@staticmethod async def build_view(bot, user: discord.User, **kwargs) -> discord.ui.View: api_client = APIClient() try: status = await api_client.get_awakening_status_v2(user) if status and status.get("awakened"): if status.get("status") == "active" and not status.get("quests"): return RecoveryView(bot, user) return EnhancedAwakeningMainView(bot, user) else: return EnhancedAwakeningInitialView(bot, user) except (httpx.RequestError, asyncio.TimeoutError): return await _create_fallback_view(bot, user)
async def build_enhanced_awakening_embed(bot, user: Union[discord.User, discord.Member]) -> discord.Embed: """Build the enhanced awakening panel embed with comprehensive error handling""" header = get_system_status_header(user).replace('```ansi', '').replace('```', '').strip() sub_header = get_panel_sub_header("awakening")
try: api_client = APIClient() status = await asyncio.wait_for(api_client.get_awakening_status_v2(user, include_quests=True), timeout=10.0)
if not status: status = {"awakened": False}
if status.get("awakened"): if status.get("status") == "active" and not status.get("quests"): return await _build_quest_sync_pending_embed(header, sub_header)
if status.get("status") == "completed": # Completed state xp_gained = status.get("total_xp_gained", 0) session_theme = status.get("session_theme", "Shadow Training") content = ( f"```ansi
" f"{header}
" f"{sub_header}

" f"\x1b[1;32m● {session_theme} Complete\x1b[0m
" f"Status: \x1b[1;32m🏆 MASTERY ACHIEVED\x1b[0m

" f"\x1b[1;37mAll awakening quests completed. Total XP earned: \x1b[1;33m{xp_gained}\x1b[0m.
" f"Return at dawn for a new ritual.

" f"──────────────────────────
" f"```" ) color = discord.Color.green() else: # Awakened state completed = status.get("completed_quests", 0) total = status.get("quest_count", 0) xp_gained = status.get("total_xp_gained", 0) readiness = status.get("readiness_level", "unknown") session_theme = status.get("session_theme", "Shadow Training") progress_percent = (completed / total * 100) if total > 0 else 0 progress_bar = "█" * int(progress_percent / 10) + "░" * (10 - int(progress_percent / 10)) readiness_info = { "low": ("\x1b[1;34m", "🔋", "RECOVERY"), "standard": ("\x1b[1;33m", "⚖️", "BALANCED"), "high": ("\x1b[1;31m", "🔥", "PEAK") } color_code, emoji, level_text = readiness_info.get(readiness, ("\x1b[1;37m", "❓", "UNKNOWN")) content = ( f"```ansi
" f"{header}
" f"{sub_header}

" f"\x1b[1;32m● {session_theme}\x1b[0m
" f"Readiness: {color_code}{emoji} {level_text}\x1b[0m

" f"\x1b[1;37m📊 Progress: [{progress_bar}] {progress_percent:.0f}%\x1b[0m
" f"Completed: \x1b[1;33m{completed}/{total}\x1b[0m | XP: \x1b[1;33m{xp_gained}\x1b[0m

" f"──────────────────────────
" f"```" ) color = discord.Color.orange() else: # Ready to awaken state content = ( f"```ansi
" f"{header}
" f"{sub_header}

" f"\x1b[1;36m● Shadow Awakening Ritual\x1b[0m
" f"Status: \x1b[1;33mREADY TO BEGIN\x1b[0m

" f"\x1b[1;37mBegin your daily training ritual to unlock
" f"today's personalized quest selection.

" f"──────────────────────────
" f"```" ) color = discord.Color.blue()
embed = discord.Embed(description=content, color=color) embed.set_footer(text="Shadow Archive • Awakening V2")
except (asyncio.TimeoutError, httpx.RequestError) as e: logger.error(f"Awakening API call failed: {e}") sentry_sdk.capture_exception(e) return await _create_fallback_embed(user, "Service Unavailable") except Exception as e: logger.error(f"Error building awakening embed: {e}") sentry_sdk.capture_exception(e) return await _create_fallback_embed(user, "System Error")
return embed
# --- VIEWS AND BUTTONS ---
class EnhancedAwakeningInitialView(discord.ui.View): """View for when the user has not yet awakened.""" def __init__(self, bot, user): super().__init__(timeout=300) self.bot = bot self.user = user self.add_item(EnhancedAwakeningButton())
class EnhancedAwakeningMainView(discord.ui.View): """Main view for an awakened user.""" def __init__(self, bot, user): super().__init__(timeout=300) self.bot = bot self.user = user self.add_item(ViewQuestsButton()) self.add_item(ViewBriefingButton()) self.add_item(ViewHistoryButton())
class EnhancedReadinessSelectionView(discord.ui.View): """View for selecting readiness level.""" def __init__(self, bot, user): super().__init__(timeout=300) self.bot = bot self.user = user self.add_item(EnhancedReadinessButton("low", "🔋 Recovery", discord.ButtonStyle.secondary)) self.add_item(EnhancedReadinessButton("medium", "⚖️ Balanced", discord.ButtonStyle.primary)) self.add_item(EnhancedReadinessButton("high", "🔥 Peak", discord.ButtonStyle.danger)) self.add_item(BackToAwakeningButton())
class EnhancedAwakeningButton(discord.ui.Button): """Button to start the awakening process.""" def __init__(self): super().__init__(label="🌅 Begin Awakening", style=discord.ButtonStyle.success)
async def callback(self, interaction: discord.Interaction): if interaction.user.id != self.view.user.id: await interaction.response.send_message("This is not for you.", ephemeral=True) return view = EnhancedReadinessSelectionView(self.view.bot, self.view.user) await interaction.response.edit_message(view=view)
class EnhancedReadinessButton(discord.ui.Button): """Button for selecting a readiness level and performing the awakening.""" def __init__(self, readiness_level: str, label: str, style: discord.ButtonStyle): super().__init__(label=label, style=style) self.readiness_level = readiness_level
@handle_panel_errors("awakening", "api") async def callback(self, interaction: discord.Interaction): if interaction.user.id != self.view.user.id: await interaction.response.send_message("This is not for you.", ephemeral=True) return await run_with_animation(interaction, self._perform_awakening)
async def _perform_awakening(self): api_client = APIClient() print(f"[UI DEBUG] Calling perform_awakening_v2 with readiness={self.readiness_level}") response = await api_client.perform_awakening_v2(self.view.user, self.readiness_level) print(f"[UI DEBUG] Response from perform_awakening_v2: {response}") if not response or not response.get("message"): raise ValueError("Invalid API response during awakening.")
embed = await build_enhanced_awakening_embed(self.view.bot, self.view.user) view = EnhancedAwakeningMainView(self.view.bot, self.view.user) return embed, view
class ViewQuestsButton(discord.ui.Button): """Button to view the current quests.""" def __init__(self): super().__init__(label="⚔️ View Quests", style=discord.ButtonStyle.primary)
@handle_panel_errors("awakening", "quest_view") async def callback(self, interaction: discord.Interaction): if interaction.user.id != self.view.user.id: await interaction.response.send_message("This is not for you.", ephemeral=True) return await run_with_animation(interaction, self._show_quests)
@handle_panel_errors("awakening", "quest_view") async def _show_quests(self): """Show enhanced quest details with full functionality""" try: api_client = APIClient() # Single API call to get both status and quests response = await api_client.get_awakening_status_v2(self.view.user, include_quests=True)
# If no awakening exists, show the "not initiated" message if not response or not response.get("awakened", False): return await self._show_no_quests_available()
# Check if quests are available quests = response.get("quests", []) if not quests: # Active session but no quests - this is a sync issue return await self._show_session_quest_error()
# Build quest view with the quests view = EnhancedQuestView(self.view.bot, self.view.user, quests, response) embed = await view.build_quest_overview_embed() return embed, view
except Exception as e: logger.exception(f"Error showing quests: {e}") return await self._show_no_quests_available()
async def _show_no_quests_available(self): embed = discord.Embed(title="No Quests Available", description="Quest data is currently unavailable. Please try again later.", color=discord.Color.orange()) return embed, self.view
async def _show_session_quest_error(self): embed = discord.Embed( title="Quest Sync Issue", description="There appears to be an active session but no quests are available. This may be a temporary sync issue. Please try again in a moment.", color=discord.Color.red() ) return embed, self.view class ViewBriefingButton(discord.ui.Button): """Button to view the daily briefing.""" def __init__(self): super().__init__(label="📜 View Briefing", style=discord.ButtonStyle.secondary)
@handle_panel_errors("awakening", "briefing_view") async def callback(self, interaction: discord.Interaction): if interaction.user.id != self.view.user.id: await interaction.response.send_message("This is not for you.", ephemeral=True) return await run_with_animation(interaction, self._show_briefing)
async def _show_briefing(self): api_client = APIClient() briefing = await api_client.get_awakening_briefing_v2(self.view.user) if not briefing: embed = discord.Embed(title="Briefing Unavailable", description="Could not retrieve the daily briefing.", color=discord.Color.red()) return embed, self.view
header = get_system_status_header(self.view.user).replace('```ansi', '').replace('```', '').strip() sub_header = get_panel_sub_header("awakening") content = ( f"```ansi
" f"{header}
" f"{sub_header}

" f"\x1b[1;36m● Daily Briefing\x1b[0m
" f"{briefing.get('awakening_summary', '')}

" f"\x1b[1;37m⚔️ Quest Overview:\x1b[0m
{briefing.get('quest_summary', '')}

" f"\x1b[1;37m💡 Readiness Impact:\x1b[0m
{briefing.get('readiness_impact', '')}

" f"\x1b[1;37m🔥 Motivation:\x1b[0m
{briefing.get('motivation_message', '')}

" f"──────────────────────────
" f"```" ) embed = discord.Embed(description=content, color=discord.Color.purple()) view = EnhancedAwakeningMainView(self.view.bot, self.view.user) return embed, view
class ViewHistoryButton(discord.ui.Button): """Button to view awakening history.""" def __init__(self): super().__init__(label="📊 View History", style=discord.ButtonStyle.secondary)
@handle_panel_errors("awakening", "history_view") async def callback(self, interaction: discord.Interaction): if interaction.user.id != self.view.user.id: await interaction.response.send_message("This is not for you.", ephemeral=True) return await run_with_animation(interaction, self._show_history)
async def _show_history(self): api_client = APIClient() history = await api_client.get_awakening_history_v2(self.view.user) if not history or not history.get('recent_sessions'): embed = discord.Embed(title="History Unavailable", description="Could not retrieve awakening history.", color=discord.Color.red()) return embed, self.view
header = get_system_status_header(self.view.user).replace('```ansi', '').replace('```', '').strip() sub_header = get_panel_sub_header("awakening") stats = history.get('stats', {}) sessions_list = "" from datetime import datetime for session in history.get('recent_sessions', [])[:5]: dt = datetime.fromisoformat(session['date']) date_str = dt.strftime("%b %d") readiness_map = {"low": "L", "medium": "M", "high": "H"} readiness = readiness_map.get(session['readiness_level'], '?') sessions_list += f"├─ {date_str} | {session['total_xp']} XP | Readiness: {readiness}
"
content = ( f"```ansi
" f"{header}
" f"{sub_header}

" f"\x1b[1;36m● Shadow Archive: Awakening History\x1b[0m
" f"Total Sessions: \x1b[1;33m{stats.get('total_sessions', 0)}\x1b[0m | Avg XP: \x1b[1;33m{stats.get('average_xp', 0):.0f}\x1b[0m

" f"\x1b[1;37m📊 Recent Sessions:\x1b[0m
{sessions_list}
" f"──────────────────────────
" f"```" ) embed = discord.Embed(description=content, color=discord.Color.dark_gold()) view = EnhancedAwakeningMainView(self.view.bot, self.view.user) return embed, view
class BackToAwakeningButton(discord.ui.Button): """Button to return to the main awakening panel.""" def __init__(self): super().__init__(label="🔙 Back", style=discord.ButtonStyle.grey)
async def callback(self, interaction: discord.Interaction): if interaction.user.id != self.view.user.id: await interaction.response.send_message("This is not for you.", ephemeral=True) return await run_with_animation(interaction, self._go_back)
async def _go_back(self): embed = await build_enhanced_awakening_embed(self.view.bot, self.view.user) view = await EnhancedAwakeningPanel.build_view(self.view.bot, self.view.user) return embed, view
# --- QUEST VIEWS AND BUTTONS ---
class EnhancedQuestView(discord.ui.View): """View for displaying the quest overview.""" def __init__(self, bot, user, quests, awakening_data): super().__init__(timeout=300) self.bot = bot self.user = user self.quests = quests self.awakening_data = awakening_data self.current_quest_index = 0
self.add_item(PreviousQuestButton()) self.add_item(NextQuestButton()) self.add_item(QuestDetailsButton()) self.add_item(CompleteQuestButton()) self.add_item(BackToAwakeningButton())
def get_current_quest(self): return self.quests[self.current_quest_index]
async def build_quest_overview_embed(self): quest = self.get_current_quest() header = get_system_status_header(self.user).replace('```ansi', '').replace('```', '').strip() sub_header = get_panel_sub_header("awakening")
completed = self.awakening_data.get("completed_quests", 0) total = self.awakening_data.get("quest_count", 0) progress_percent = (completed / total * 100) if total > 0 else 0 progress_bar = "█" * int(progress_percent / 10) + "░" * (10 - int(progress_percent / 10))
quest_title = quest.get('title', 'Unknown Quest') quest_status = "✅" if quest.get('completed') else "❌"
content = ( f"```ansi
" f"{header}
" f"{sub_header}

" f"\x1b[1;36m● Quest Overview ({self.current_quest_index + 1}/{total})\x1b[0m
" f"Progress: [{progress_bar}] {progress_percent:.0f}%

" f"\x1b[1;37mCurrent Quest: {quest_status} {quest_title}\x1b[0m
" f"{quest.get('description', '')}

" f"──────────────────────────
" f"```" ) embed = discord.Embed(description=content, color=discord.Color.blue()) return embed
class EnhancedQuestDetailView(discord.ui.View): """View for displaying detailed information about a single quest.""" def __init__(self, bot, user, quests, awakening_data, current_quest_index): super().__init__(timeout=300) self.bot = bot self.user = user self.quests = quests self.awakening_data = awakening_data self.current_quest_index = current_quest_index
self.add_item(PreviousQuestDetailButton()) self.add_item(NextQuestDetailButton()) # TODO: Re-implement logging when API supports it # self.add_item(LogRepsButton()) # self.add_item(LogSetsButton()) self.add_item(BackToQuestOverviewButton())
def get_current_quest(self): return self.quests[self.current_quest_index]
async def build_quest_detail_embed(self): quest = self.get_current_quest() header = get_system_status_header(self.user).replace('```ansi', '').replace('```', '').strip() sub_header = get_panel_sub_header("awakening")
title = quest.get("title", "Unknown Quest") description = quest.get("description", "No description") movement = quest.get("movement_name", "N/A") target_reps = quest.get("target_reps", 0) target_sets = quest.get("target_sets", 1) xp_reward = quest.get("xp_reward", 0) completed = quest.get("completed", False) status_text = "\x1b[1;32m✅ COMPLETED\x1b[0m" if completed else "\x1b[1;31m❌ PENDING\x1b[0m"
content = ( f"```ansi
" f"{header}
" f"{sub_header}

" f"\x1b[1;36m● Quest Details ({self.current_quest_index + 1}/{len(self.quests)})\x1b[0m
" f"Status: {status_text}

" f"\x1b[1;37m⚔️ {title}\x1b[0m
" f"{description}

" f"\x1b[1;37m🎯 Parameters:\x1b[0m
" f"├─ Movement: \x1b[1;33m{movement}\x1b[0m
" f"├─ Target: \x1b[1;33m{target_sets} sets x {target_reps} reps\x1b[0m
" f"└─ Reward: \x1b[1;33m{xp_reward} XP\x1b[0m

" f"──────────────────────────
" f"```" ) embed = discord.Embed(description=content, color=discord.Color.green() if completed else discord.Color.dark_orange()) return embed
class PreviousQuestButton(discord.ui.Button): def __init__(self): super().__init__(label="◀️ Previous", style=discord.ButtonStyle.secondary)
async def callback(self, interaction: discord.Interaction): if self.view.current_quest_index > 0: self.view.current_quest_index -= 1 else: self.view.current_quest_index = len(self.view.quests) - 1 embed = await self.view.build_quest_overview_embed() await interaction.response.edit_message(embed=embed, view=self.view)
class NextQuestButton(discord.ui.Button): def __init__(self): super().__init__(label="Next ▶️", style=discord.ButtonStyle.secondary)
async def callback(self, interaction: discord.Interaction): if self.view.current_quest_index < len(self.view.quests) - 1: self.view.current_quest_index += 1 else: self.view.current_quest_index = 0 embed = await self.view.build_quest_overview_embed() await interaction.response.edit_message(embed=embed, view=self.view)
class QuestDetailsButton(discord.ui.Button): def __init__(self): super().__init__(label="📋 Details", style=discord.ButtonStyle.primary)
async def callback(self, interaction: discord.Interaction): view = EnhancedQuestDetailView(self.view.bot, self.view.user, self.view.quests, self.view.awakening_data, self.view.current_quest_index) embed = await view.build_quest_detail_embed() await interaction.response.edit_message(embed=embed, view=view)
class CompleteQuestButton(discord.ui.Button): def __init__(self): super().__init__(label="✅ Complete", style=discord.ButtonStyle.success)
@handle_panel_errors("awakening", "quest_completion") async def callback(self, interaction: discord.Interaction): await run_with_animation(interaction, self._complete_quest)
async def _complete_quest(self): quest = self.view.get_current_quest() api_client = APIClient() response = await api_client.complete_awakening_quest_v2(self.view.user, quest['id']) if not response or not response.get('success'): raise ValueError("Failed to complete quest.")
# Refresh data awakening_data = await api_client.get_awakening_status_v2(self.view.user, include_quests=True) quests = awakening_data.get("quests", []) self.view.quests = quests self.view.awakening_data = awakening_data
embed = await self.view.build_quest_overview_embed() return embed, self.view
class PreviousQuestDetailButton(discord.ui.Button): def __init__(self): super().__init__(label="◀️ Previous", style=discord.ButtonStyle.secondary)
async def callback(self, interaction: discord.Interaction): if self.view.current_quest_index > 0: self.view.current_quest_index -= 1 else: self.view.current_quest_index = len(self.view.quests) - 1 embed = await self.view.build_quest_detail_embed() await interaction.response.edit_message(embed=embed, view=self.view)
class NextQuestDetailButton(discord.ui.Button): def __init__(self): super().__init__(label="Next ▶️", style=discord.ButtonStyle.secondary)
async def callback(self, interaction: discord.Interaction): if self.view.current_quest_index < len(self.view.quests) - 1: self.view.current_quest_index += 1 else: self.view.current_quest_index = 0 embed = await self.view.build_quest_detail_embed() await interaction.response.edit_message(embed=embed, view=self.view)
class BackToQuestOverviewButton(discord.ui.Button): def __init__(self): super().__init__(label="🔙 Overview", style=discord.ButtonStyle.grey)
async def callback(self, interaction: discord.Interaction): view = EnhancedQuestView(self.view.bot, self.view.user, self.view.quests, self.view.awakening_data) embed = await view.build_quest_overview_embed() await interaction.response.edit_message(embed=embed, view=view)
# --- RECOVERY VIEW ---
class RecoveryView(discord.ui.View): """Recovery view for handling stuck awakening sessions""" def __init__(self, bot, user): super().__init__(timeout=300) self.bot = bot self.user = user self.add_item(RecoveryButton()) self.add_item(BackToAwakeningButton())
class RecoveryButton(discord.ui.Button): """Button to recover from stuck sessions""" def __init__(self): super().__init__(label="🔄 Recover", style=discord.ButtonStyle.danger)
@handle_panel_errors("awakening", "session_recovery") async def callback(self, interaction: discord.Interaction): await run_with_animation(interaction, self._attempt_recovery)
async def _attempt_recovery(self): api_client = APIClient() response = await api_client.get_awakening_status_v2(self.view.user, include_quests=True) if response and response.get("quests"): embed = await build_enhanced_awakening_embed(self.view.bot, self.view.user) view = await EnhancedAwakeningPanel.build_view(self.view.bot, self.view.user) return embed, view else: raise ValueError("Recovery failed, quests still not available.")
async def _create_fallback_view(bot, user): """Creates a fallback view for when the API is down.""" view = discord.ui.View(timeout=300) view.add_item(BackToAwakeningButton()) return view

""" Mock Awakening Service for development mode """ from datetime import date, datetime from typing import Dict, List, Any import json import os from api.models.awakening import ReadinessLevel
class MockAwakeningService: """Mock service for awakening system functionality in development mode"""
# Class-level storage for true singleton behavior _sessions = {} _quests = {} _initialized = False
def __init__(self): # File-based storage for persistence self.data_file = "mock_awakening_data.json" if not MockAwakeningService._initialized: self._load_data() MockAwakeningService._initialized = True print(f"[MOCK] Initialized MockAwakeningService with {len(MockAwakeningService._sessions)} sessions")
def _load_data(self): """Load data from file if it exists""" if os.path.exists(self.data_file): try: with open(self.data_file, 'r') as f: data = json.load(f) MockAwakeningService._sessions = data.get('sessions', {}) MockAwakeningService._quests = data.get('quests', {}) print(f"[MOCK] Loaded {len(MockAwakeningService._sessions)} sessions from file") except Exception as e: print(f"[MOCK] Error loading data: {e}") MockAwakeningService._sessions = {} MockAwakeningService._quests = {} else: MockAwakeningService._sessions = {} MockAwakeningService._quests = {}
def _save_data(self): """Save data to file""" try: with open(self.data_file, 'w') as f: json.dump({ 'sessions': MockAwakeningService._sessions, 'quests': MockAwakeningService._quests }, f, indent=2) print(f"[MOCK] Saved {len(MockAwakeningService._sessions)} sessions to file") except Exception as e: print(f"[MOCK] Error saving data: {e}")
async def get_or_create_daily_session(self, user_id: int, readiness_level: str) -> Dict: """Get or create a daily awakening session""" today = date.today().isoformat() session_key = f"{user_id}_{today}"
# Check if session already exists if session_key in MockAwakeningService._sessions: session = MockAwakeningService._sessions[session_key] quests = MockAwakeningService._quests.get(session_key, []) return { "session": session, "quests": quests, "awakened": session["status"] != "pending", "message": "Existing session retrieved" }
# Convert string readiness to ReadinessLevel enum readiness_map = {"low": ReadinessLevel.LOW, "medium": ReadinessLevel.STANDARD, "standard": ReadinessLevel.STANDARD, "high": ReadinessLevel.HIGH} readiness_enum = readiness_map.get(readiness_level, ReadinessLevel.STANDARD)
# Create new session quest_count = self._get_quest_count_for_readiness(readiness_enum)
session = { "user_id": user_id, "awakening_date": today, "readiness_level": readiness_level, "status": "awakened", "quest_count": quest_count, "completed_quests": 0, "total_xp_gained": 0, "awakened_at": datetime.now().isoformat(), }
MockAwakeningService._sessions[session_key] = session
# Generate mock quests quests = self._generate_mock_quests(quest_count, readiness_enum) MockAwakeningService._quests[session_key] = quests
# Save to file self._save_data()
return { "session": session, "quests": quests, "awakened": True, "message": f"New session created with {quest_count} quests" }
async def get_awakening_progress(self, user_id: int, include_quests: bool = True) -> Dict: """Get mock awakening progress - alias for get_awakening_status""" return await self.get_awakening_status(user_id, include_quests)
async def get_awakening_status(self, user_id: int, include_quests: bool = False) -> Dict: """Get mock awakening status""" today = date.today().isoformat() session_key = f"{user_id}_{today}"
# Debug logging to file with open("debug_awakening.log", "a") as f: f.write(f"[STATUS] user_id={user_id}, session_key={session_key}, include_quests={include_quests}\n") f.write(f"[STATUS] instance_id={id(self)}, total_sessions={len(MockAwakeningService._sessions)}\n") f.write(f"[STATUS] session_exists={session_key in MockAwakeningService._sessions}\n") if MockAwakeningService._sessions: f.write(f"[STATUS] available_sessions={list(MockAwakeningService._sessions.keys())}\n")
if session_key not in MockAwakeningService._sessions: with open("debug_awakening.log", "a") as f: f.write(f"[STATUS] session not found, returning pending\n") return { "status": "pending", "awakened": False, "quests_available": False, "readiness_level": None, "quests": [], "active_session": None, }
session = MockAwakeningService._sessions[session_key] quests = []
if include_quests and session_key in MockAwakeningService._quests: quests = MockAwakeningService._quests[session_key]
with open("debug_awakening.log", "a") as f: f.write(f"[STATUS] returning session with status={session['status']}, quest_count={len(quests)}\n")
return { "status": session["status"], "awakened": session["status"] != "pending", "quests_available": len(quests) > 0, "readiness_level": session["readiness_level"], "quest_count": session["quest_count"], "completed_quests": session.get("completed_quests", 0), "total_xp_gained": session.get("total_xp_gained", 0), "session_theme": "Shadow Training (Mock)", "quests": quests, "active_session": session, }
async def process_awakening(self, user_id: int, readiness_level: ReadinessLevel) -> Dict: """Process mock awakening""" today = date.today().isoformat() session_key = f"{user_id}_{today}"
# Debug logging to file with open("debug_awakening.log", "a") as f: f.write(f"[PROCESS] user_id={user_id}, session_key={session_key}, readiness={readiness_level.value}\n") f.write(f"[PROCESS] instance_id={id(self)}, sessions_before={len(MockAwakeningService._sessions)}\n")
# Create mock session quest_count = self._get_quest_count_for_readiness(readiness_level)
MockAwakeningService._sessions[session_key] = { "user_id": user_id, "awakening_date": today, "readiness_level": readiness_level.value, "status": "awakened", "quest_count": quest_count, "completed_quests": 0, "total_xp_gained": 0, "awakened_at": datetime.now().isoformat(), }
# Generate mock quests MockAwakeningService._quests[session_key] = self._generate_mock_quests(quest_count, readiness_level)
# Save to file self._save_data()
with open("debug_awakening.log", "a") as f: f.write(f"[PROCESS] stored session, sessions_after={len(MockAwakeningService._sessions)}, quest_count={quest_count}\n")
return await self.get_awakening_status(user_id, include_quests=True)
async def complete_quest(self, user_id: int, quest_id: int) -> Dict: """Complete mock quest""" today = date.today().isoformat() session_key = f"{user_id}_{today}"
quest_found = False xp_awarded = 0
if session_key in MockAwakeningService._quests: for quest in MockAwakeningService._quests[session_key]: if quest["id"] == quest_id: quest["status"] = "completed" quest["completed"] = True quest["completed_at"] = datetime.now().isoformat() quest_found = True xp_awarded = quest["xp_reward"]
# Update session progress if session_key in MockAwakeningService._sessions: session = MockAwakeningService._sessions[session_key] session["completed_quests"] += 1 session["total_xp_gained"] += quest["xp_reward"]
# Check if all quests completed completed_count = sum(1 for q in MockAwakeningService._quests[session_key] if q["status"] == "completed") if completed_count >= session["quest_count"]: session["status"] = "completed" session["completed_at"] = datetime.now().isoformat()
# Save to file self._save_data() break
return { "success": quest_found, "xp_awarded": xp_awarded, "message": f"Quest {quest_id} completed successfully" if quest_found else f"Quest {quest_id} not found", "session": await self.get_awakening_status(user_id, include_quests=True) }
async def get_awakening_history(self, user_id: int, limit: int = 10) -> Dict: """Get mock awakening history""" # Return mock history data sessions = [] for i in range(min(3, limit)): # Mock 3 previous sessions past_date = date.today().replace(day=date.today().day - i - 1) sessions.append({ "awakening_date": past_date.isoformat(), "readiness_level": "standard", "status": "completed", "quest_count": 3, "completed_quests": 3, "total_xp_gained": 150, "awakened_at": f"{past_date}T08:00:00", "completed_at": f"{past_date}T20:00:00", })
return { "sessions": sessions, "total_sessions": len(sessions), }
async def recover_session(self, user_id: int) -> Dict: """Recover mock session""" today = date.today().isoformat() session_key = f"{user_id}_{today}"
# Clear today's session if session_key in MockAwakeningService._sessions: del MockAwakeningService._sessions[session_key] if session_key in MockAwakeningService._quests: del MockAwakeningService._quests[session_key]
return await self.get_awakening_status(user_id)
def _get_quest_count_for_readiness(self, readiness_level: ReadinessLevel) -> int: """Determine quest count based on readiness level""" if readiness_level == ReadinessLevel.LOW: return 2 elif readiness_level == ReadinessLevel.STANDARD: return 3 else: # HIGH return 4
def _generate_mock_quests(self, quest_count: int, readiness_level: ReadinessLevel) -> List[Dict]: """Generate mock quests""" quests = [] quest_types = ["practice", "technique", "intensity"]
for i in range(quest_count): quest_type = quest_types[i % len(quest_types)] tier = (i % 3) + 1
quests.append({ "id": i + 1, "title": f"Mock {quest_type.title()} Quest {i+1}", "description": f"Complete mock {quest_type} exercise", "type": quest_type, "difficulty": readiness_level.value, "tier": tier, "xp_reward": 50 * tier, "status": "available", "completed": False, "movement_name": f"Mock Movement {i+1}", "target_reps": 10 + (i * 2), "target_sets": 3, "progress": {}, "completed_at": None, "created_at": datetime.now().isoformat(), })
return quests
async def get_daily_briefing(self, user_id: int) -> Dict: """Get mock daily briefing""" today = date.today().isoformat() session_key = f"{user_id}_{today}"
if session_key in MockAwakeningService._sessions: session = MockAwakeningService._sessions[session_key] readiness = session.get("readiness_level", "standard") quest_count = session.get("quest_count", 0)
return { "awakening_summary": f"Your {readiness} intensity session is active with {quest_count} challenges.", "quest_summary": f"Complete all {quest_count} quests to maximize your daily XP gains.", "readiness_impact": f"Your {readiness} readiness level provides balanced quest difficulty and rewards.", "motivation_message": "Push beyond your limits. Every rep counts towards your shadow mastery!" }
return { "awakening_summary": "No active awakening session. Begin your daily ritual to unlock today's challenges.", "quest_summary": "Quests will be generated based on your chosen readiness level.", "readiness_impact": "Choose your readiness level wisely - it affects quest difficulty and XP rewards.", "motivation_message": "The shadow realm awaits. Are you ready to awaken your true potential?" }
async def get_system_health(self) -> Dict: """Get mock system health status""" return { "status": "healthy", "uptime": "100%", "active_sessions": len(MockAwakeningService._sessions), "total_quests": sum(len(q) for q in MockAwakeningService._quests.values()), "environment": "development", "timestamp": datetime.now().isoformat() }

template: id: level-design-doc-template-v2 name: Level Design Document version: 2.0 output: format: markdown filename: "docs/{{game_name}}-level-design-document.md" title: "{{game_title}} Level Design Document"
workflow: mode: interactive
sections: - id: initial-setup instruction: | This template creates comprehensive level design documentation that guides both content creation and technical implementation. This document should provide enough detail for developers to create level loading systems and for designers to create specific levels.
If available, review: Game Design Document (GDD), Game Architecture Document. This document should align with the game mechanics and technical systems defined in those documents.
- id: introduction title: Introduction instruction: Establish the purpose and scope of level design for this game content: | This document defines the level design framework for {{game_title}}, providing guidelines for creating engaging, balanced levels that support the core gameplay mechanics defined in the Game Design Document.
This framework ensures consistency across all levels while providing flexibility for creative level design within established technical and design constraints. sections: - id: change-log title: Change Log instruction: Track document versions and changes type: table template: | | Date | Version | Description | Author | | :--- | :------ | :---------- | :----- |
- id: level-design-philosophy title: Level Design Philosophy instruction: Establish the overall approach to level design based on the game's core pillars and mechanics. Apply `tasks#advanced-elicitation` after presenting this section. sections: - id: design-principles title: Design Principles instruction: Define 3-5 core principles that guide all level design decisions type: numbered-list template: | **{{principle_name}}** - {{description}} - id: player-experience-goals title: Player Experience Goals instruction: Define what players should feel and learn in each level category template: | **Tutorial Levels:** {{experience_description}} **Standard Levels:** {{experience_description}} **Challenge Levels:** {{experience_description}} **Boss Levels:** {{experience_description}} - id: level-flow-framework title: Level Flow Framework instruction: Define the standard structure for level progression template: | **Introduction Phase:** {{duration}} - {{purpose}} **Development Phase:** {{duration}} - {{purpose}} **Climax Phase:** {{duration}} - {{purpose}} **Resolution Phase:** {{duration}} - {{purpose}}
- id: level-categories title: Level Categories instruction: Define different types of levels based on the GDD requirements. Each category should be specific enough for implementation. repeatable: true sections: - id: level-category title: "{{category_name}} Levels" template: | **Purpose:** {{gameplay_purpose}}
**Target Duration:** {{min_time}} - {{max_time}} minutes
**Difficulty Range:** {{difficulty_scale}}
**Key Mechanics Featured:**
- {{mechanic_1}} - {{usage_description}} - {{mechanic_2}} - {{usage_description}}
**Player Objectives:**
- Primary: {{primary_objective}} - Secondary: {{secondary_objective}} - Hidden: {{secret_objective}}
**Success Criteria:**
- {{completion_requirement_1}} - {{completion_requirement_2}}
**Technical Requirements:**
- Maximum entities: {{entity_limit}} - Performance target: {{fps_target}} FPS - Memory budget: {{memory_limit}}MB - Asset requirements: {{asset_needs}}
- id: level-progression-system title: Level Progression System instruction: Define how players move through levels and how difficulty scales sections: - id: world-structure title: World Structure instruction: Based on GDD requirements, define the overall level organization template: | **Organization Type:** {{linear|hub_world|open_world}}
**Total Level Count:** {{number}}
**World Breakdown:**
- World 1: {{level_count}} levels - {{theme}} - {{difficulty_range}} - World 2: {{level_count}} levels - {{theme}} - {{difficulty_range}} - World 3: {{level_count}} levels - {{theme}} - {{difficulty_range}} - id: difficulty-progression title: Difficulty Progression instruction: Define how challenge increases across the game sections: - id: progression-curve title: Progression Curve type: code language: text template: | Difficulty ^ ___/``` | / | / ___/``` | / / | / / |/ / +-----------> Level Number Tutorial Early Mid Late - id: scaling-parameters title: Scaling Parameters type: bullet-list template: | - Enemy count: {{start_count}} → {{end_count}} - Enemy difficulty: {{start_diff}} → {{end_diff}} - Level complexity: {{start_complex}} → {{end_complex}} - Time pressure: {{start_time}} → {{end_time}} - id: unlock-requirements title: Unlock Requirements instruction: Define how players access new levels template: | **Progression Gates:**
- Linear progression: Complete previous level - Star requirements: {{star_count}} stars to unlock - Skill gates: Demonstrate {{skill_requirement}} - Optional content: {{unlock_condition}}
- id: level-design-components title: Level Design Components instruction: Define the building blocks used to create levels sections: - id: environmental-elements title: Environmental Elements instruction: Define all environmental components that can be used in levels template: | **Terrain Types:**
- {{terrain_1}}: {{properties_and_usage}} - {{terrain_2}}: {{properties_and_usage}}
**Interactive Objects:**
- {{object_1}}: {{behavior_and_purpose}} - {{object_2}}: {{behavior_and_purpose}}
**Hazards and Obstacles:**
- {{hazard_1}}: {{damage_and_behavior}} - {{hazard_2}}: {{damage_and_behavior}} - id: collectibles-rewards title: Collectibles and Rewards instruction: Define all collectible items and their placement rules template: | **Collectible Types:**
- {{collectible_1}}: {{value_and_purpose}} - {{collectible_2}}: {{value_and_purpose}}
**Placement Guidelines:**
- Mandatory collectibles: {{placement_rules}} - Optional collectibles: {{placement_rules}} - Secret collectibles: {{placement_rules}}
**Reward Distribution:**
- Easy to find: {{percentage}}% - Moderate challenge: {{percentage}}% - High skill required: {{percentage}}% - id: enemy-placement-framework title: Enemy Placement Framework instruction: Define how enemies should be placed and balanced in levels template: | **Enemy Categories:**
- {{enemy_type_1}}: {{behavior_and_usage}} - {{enemy_type_2}}: {{behavior_and_usage}}
**Placement Principles:**
- Introduction encounters: {{guideline}} - Standard encounters: {{guideline}} - Challenge encounters: {{guideline}}
**Difficulty Scaling:**
- Enemy count progression: {{scaling_rule}} - Enemy type introduction: {{pacing_rule}} - Encounter complexity: {{complexity_rule}}
- id: level-creation-guidelines title: Level Creation Guidelines instruction: Provide specific guidelines for creating individual levels sections: - id: level-layout-principles title: Level Layout Principles template: | **Spatial Design:**
- Grid size: {{grid_dimensions}} - Minimum path width: {{width_units}} - Maximum vertical distance: {{height_units}} - Safe zones placement: {{safety_guidelines}}
**Navigation Design:**
- Clear path indication: {{visual_cues}} - Landmark placement: {{landmark_rules}} - Dead end avoidance: {{dead_end_policy}} - Multiple path options: {{branching_rules}} - id: pacing-and-flow title: Pacing and Flow instruction: Define how to control the rhythm and pace of gameplay within levels template: | **Action Sequences:**
- High intensity duration: {{max_duration}} - Rest period requirement: {{min_rest_time}} - Intensity variation: {{pacing_pattern}}
**Learning Sequences:**
- New mechanic introduction: {{teaching_method}} - Practice opportunity: {{practice_duration}} - Skill application: {{application_context}} - id: challenge-design title: Challenge Design instruction: Define how to create appropriate challenges for each level type template: | **Challenge Types:**
- Execution challenges: {{skill_requirements}} - Puzzle challenges: {{complexity_guidelines}} - Time challenges: {{time_pressure_rules}} - Resource challenges: {{resource_management}}
**Difficulty Calibration:**
- Skill check frequency: {{frequency_guidelines}} - Failure recovery: {{retry_mechanics}} - Hint system integration: {{help_system}}
- id: technical-implementation title: Technical Implementation instruction: Define technical requirements for level implementation sections: - id: level-data-structure title: Level Data Structure instruction: Define how level data should be structured for implementation template: | **Level File Format:**
- Data format: {{json|yaml|custom}} - File naming: `level_{{world}}_{{number}}.{{extension}}` - Data organization: {{structure_description}} sections: - id: required-data-fields title: Required Data Fields type: code language: json template: | { "levelId": "{{unique_identifier}}", "worldId": "{{world_identifier}}", "difficulty": {{difficulty_value}}, "targetTime": {{completion_time_seconds}}, "objectives": { "primary": "{{primary_objective}}", "secondary": ["{{secondary_objectives}}"], "hidden": ["{{secret_objectives}}"] }, "layout": { "width": {{grid_width}}, "height": {{grid_height}}, "tilemap": "{{tilemap_reference}}" }, "entities": [ { "type": "{{entity_type}}", "position": {"x": {{x}}, "y": {{y}}}, "properties": {{entity_properties}} } ] } - id: asset-integration title: Asset Integration instruction: Define how level assets are organized and loaded template: | **Tilemap Requirements:**
- Tile size: {{tile_dimensions}}px - Tileset organization: {{tileset_structure}} - Layer organization: {{layer_system}} - Collision data: {{collision_format}}
**Audio Integration:**
- Background music: {{music_requirements}} - Ambient sounds: {{ambient_system}} - Dynamic audio: {{dynamic_audio_rules}} - id: performance-optimization title: Performance Optimization instruction: Define performance requirements for level systems template: | **Entity Limits:**
- Maximum active entities: {{entity_limit}} - Maximum particles: {{particle_limit}} - Maximum audio sources: {{audio_limit}}
**Memory Management:**
- Texture memory budget: {{texture_memory}}MB - Audio memory budget: {{audio_memory}}MB - Level loading time: <{{load_time}}s
**Culling and LOD:**
- Off-screen culling: {{culling_distance}} - Level-of-detail rules: {{lod_system}} - Asset streaming: {{streaming_requirements}}
- id: level-testing-framework title: Level Testing Framework instruction: Define how levels should be tested and validated sections: - id: automated-testing title: Automated Testing template: | **Performance Testing:**
- Frame rate validation: Maintain {{fps_target}} FPS - Memory usage monitoring: Stay under {{memory_limit}}MB - Loading time verification: Complete in <{{load_time}}s
**Gameplay Testing:**
- Completion path validation: All objectives achievable - Collectible accessibility: All items reachable - Softlock prevention: No unwinnable states - id: manual-testing-protocol title: Manual Testing Protocol sections: - id: playtesting-checklist title: Playtesting Checklist type: checklist items: - "Level completes within target time range" - "All mechanics function correctly" - "Difficulty feels appropriate for level category" - "Player guidance is clear and effective" - "No exploits or sequence breaks (unless intended)" - id: player-experience-testing title: Player Experience Testing type: checklist items: - "Tutorial levels teach effectively" - "Challenge feels fair and rewarding" - "Flow and pacing maintain engagement" - "Audio and visual feedback support gameplay" - id: balance-validation title: Balance Validation template: | **Metrics Collection:**
- Completion rate: Target {{completion_percentage}}% - Average completion time: {{target_time}} ± {{variance}} - Death count per level: <{{max_deaths}} - Collectible discovery rate: {{discovery_percentage}}%
**Iteration Guidelines:**
- Adjustment criteria: {{criteria_for_changes}} - Testing sample size: {{minimum_testers}} - Validation period: {{testing_duration}}
- id: content-creation-pipeline title: Content Creation Pipeline instruction: Define the workflow for creating new levels sections: - id: design-phase title: Design Phase template: | **Concept Development:**
1. Define level purpose and goals 2. Create rough layout sketch 3. Identify key mechanics and challenges 4. Estimate difficulty and duration
**Documentation Requirements:**
- Level design brief - Layout diagrams - Mechanic integration notes - Asset requirement list - id: implementation-phase title: Implementation Phase template: | **Technical Implementation:**
1. Create level data file 2. Build tilemap and layout 3. Place entities and objects 4. Configure level logic and triggers 5. Integrate audio and visual effects
**Quality Assurance:**
1. Automated testing execution 2. Internal playtesting 3. Performance validation 4. Bug fixing and polish - id: integration-phase title: Integration Phase template: | **Game Integration:**
1. Level progression integration 2. Save system compatibility 3. Analytics integration 4. Achievement system integration
**Final Validation:**
1. Full game context testing 2. Performance regression testing 3. Platform compatibility verification 4. Final approval and release
- id: success-metrics title: Success Metrics instruction: Define how to measure level design success sections: - id: player-engagement title: Player Engagement type: bullet-list template: | - Level completion rate: {{target_rate}}% - Replay rate: {{replay_target}}% - Time spent per level: {{engagement_time}} - Player satisfaction scores: {{satisfaction_target}}/10 - id: technical-performance title: Technical Performance type: bullet-list template: | - Frame rate consistency: {{fps_consistency}}% - Loading time compliance: {{load_compliance}}% - Memory usage efficiency: {{memory_efficiency}}% - Crash rate: <{{crash_threshold}}% - id: design-quality title: Design Quality type: bullet-list template: | - Difficulty curve adherence: {{curve_accuracy}} - Mechanic integration effectiveness: {{integration_score}} - Player guidance clarity: {{guidance_score}} - Content accessibility: {{accessibility_rate}}%

template:
  id: game-story-template-v2
  name: Game Development Story
  version: 2.0
  output:
    format: markdown
    filename: "stories/{{epic_name}}/{{story_id}}-{{story_name}}.md"
    title: "Story: {{story_title}}"

workflow:
  mode: interactive

sections:
  - id: initial-setup
    instruction: |
      This template creates detailed game development stories that are immediately actionable by game developers. Each story should focus on a single, implementable feature that contributes to the overall game functionality.

      Before starting, ensure you have access to:

      - Game Design Document (GDD)
      - Game Architecture Document
      - Any existing stories in this epic

      The story should be specific enough that a developer can implement it without requiring additional design decisions.

  - id: story-header
    content: |
      **Epic:** {{epic_name}}  
      **Story ID:** {{story_id}}  
      **Priority:** {{High|Medium|Low}}  
      **Points:** {{story_points}}  
      **Status:** Draft

  - id: description
    title: Description
    instruction: Provide a clear, concise description of what this story implements. Focus on the specific game feature or system being built. Reference the GDD section that defines this feature.
    template: "{{clear_description_of_what_needs_to_be_implemented}}"

  - id: acceptance-criteria
    title: Acceptance Criteria
    instruction: Define specific, testable conditions that must be met for the story to be considered complete. Each criterion should be verifiable and directly related to gameplay functionality.
    sections:
      - id: functional-requirements
        title: Functional Requirements
        type: checklist
        items:
          - "{{specific_functional_requirement}}"
      - id: technical-requirements
        title: Technical Requirements
        type: checklist
        items:
          - "Code follows C# best practices"
          - "Maintains stable frame rate on target devices"
          - "No memory leaks or performance degradation"
          - "{{specific_technical_requirement}}"
      - id: game-design-requirements
        title: Game Design Requirements
        type: checklist
        items:
          - "{{gameplay_requirement_from_gdd}}"
          - "{{balance_requirement_if_applicable}}"
          - "{{player_experience_requirement}}"

  - id: technical-specifications
    title: Technical Specifications
    instruction: Provide specific technical details that guide implementation. Include class names, file locations, and integration points based on the game architecture.
    sections:
      - id: files-to-modify
        title: Files to Create/Modify
        template: |
          **New Files:**

          - `{{file_path_1}}` - {{purpose}}
          - `{{file_path_2}}` - {{purpose}}

          **Modified Files:**

          - `{{existing_file_1}}` - {{changes_needed}}
          - `{{existing_file_2}}` - {{changes_needed}}
      - id: class-interface-definitions
        title: Class/Interface Definitions
        instruction: Define specific C# interfaces and class structures needed
        type: code
        language: c#
        template: |
          // {{interface_name}}
          public interface {{InterfaceName}}
          {
              {{type}} {{Property1}} { get; set; }
              {{return_type}} {{Method1}}({{params}});
          }

          // {{class_name}}
          public class {{ClassName}} : MonoBehaviour
          {
              private {{type}} _{{property}};

              private void Awake()
              {
                  // Implementation requirements
              }

              public {{return_type}} {{Method1}}({{params}})
              {
                  // Method requirements
              }
          }
      - id: integration-points
        title: Integration Points
        instruction: Specify how this feature integrates with existing systems
        template: |
          **Scene Integration:**

          - {{scene_name}}: {{integration_details}}

          **Component Dependencies:**

          - {{component_name}}: {{dependency_description}}

          **Event Communication:**

          - Emits: `{{event_name}}` when {{condition}}
          - Listens: `{{event_name}}` to {{response}}

  - id: implementation-tasks
    title: Implementation Tasks
    instruction: Break down the implementation into specific, ordered tasks. Each task should be completable in 1-4 hours.
    sections:
      - id: dev-agent-record
        title: Dev Agent Record
        template: |
          **Tasks:**

          - [ ] {{task_1_description}}
          - [ ] {{task_2_description}}
          - [ ] {{task_3_description}}
          - [ ] {{task_4_description}}
          - [ ] Write unit tests for {{component}}
          - [ ] Integration testing with {{related_system}}
          - [ ] Performance testing and optimization

          **Debug Log:**
          | Task | File | Change | Reverted? |
          |------|------|--------|-----------|
          | | | | |

          **Completion Notes:**

          <!-- Only note deviations from requirements, keep under 50 words -->

          **Change Log:**

          <!-- Only requirement changes during implementation -->

  - id: game-design-context
    title: Game Design Context
    instruction: Reference the specific sections of the GDD that this story implements
    template: |
      **GDD Reference:** {{section_name}} ({{page_or_section_number}})

      **Game Mechanic:** {{mechanic_name}}

      **Player Experience Goal:** {{experience_description}}

      **Balance Parameters:**

      - {{parameter_1}}: {{value_or_range}}
      - {{parameter_2}}: {{value_or_range}}

  - id: testing-requirements
    title: Testing Requirements
    instruction: Define specific testing criteria for this game feature
    sections:
      - id: unit-tests
        title: Unit Tests
        template: |
          **Test Files:**

          - `Assets/Tests/EditMode/{{component_name}}Tests.cs`

          **Test Scenarios:**

          - {{test_scenario_1}}
          - {{test_scenario_2}}
          - {{edge_case_test}}
      - id: game-testing
        title: Game Testing
        template: |
          **Manual Test Cases:**

          1. {{test_case_1_description}}

            - Expected: {{expected_behavior}}
            - Performance: {{performance_expectation}}

          2. {{test_case_2_description}}
            - Expected: {{expected_behavior}}
            - Edge Case: {{edge_case_handling}}
      - id: performance-tests
        title: Performance Tests
        template: |
          **Metrics to Verify:**

          - Frame rate maintains stable FPS
          - Memory usage stays under {{memory_limit}}MB
          - {{feature_specific_performance_metric}}

  - id: dependencies
    title: Dependencies
    instruction: List any dependencies that must be completed before this story can be implemented
    template: |
      **Story Dependencies:**

      - {{story_id}}: {{dependency_description}}

      **Technical Dependencies:**

      - {{system_or_file}}: {{requirement}}

      **Asset Dependencies:**

      - {{asset_type}}: {{asset_description}}
      - Location: `{{asset_path}}`

  - id: definition-of-done
    title: Definition of Done
    instruction: Checklist that must be completed before the story is considered finished
    type: checklist
    items:
      - "All acceptance criteria met"
      - "Code reviewed and approved"
      - "Unit tests written and passing"
      - "Integration tests passing"
      - "Performance targets met"
      - "No C# compiler errors or warnings"
      - "Documentation updated"
      - "{{game_specific_dod_item}}"

  - id: notes
    title: Notes
    instruction: Any additional context, design decisions, or implementation notes
    template: |
      **Implementation Notes:**

      - {{note_1}}
      - {{note_2}}

      **Design Decisions:**

      - {{decision_1}}: {{rationale}}
      - {{decision_2}}: {{rationale}}

      **Future Considerations:**

      - {{future_enhancement_1}}
      - {{future_optimization_1}}

template: id: game-design-doc-template-v2 name: Game Design Document (GDD) version: 2.0 output: format: markdown filename: "docs/{{game_name}}-game-design-document.md" title: "{{game_title}} Game Design Document (GDD)"
workflow: mode: interactive
sections: - id: initial-setup instruction: | This template creates a comprehensive Game Design Document that will serve as the foundation for all game development work. The GDD should be detailed enough that developers can create user stories and epics from it. Focus on gameplay systems, mechanics, and technical requirements that can be broken down into implementable features.
If available, review any provided documents or ask if any are optionally available: Project Brief, Market Research, Competitive Analysis
- id: executive-summary title: Executive Summary instruction: Create a compelling overview that captures the essence of the game. Present this section first and get user feedback before proceeding. sections: - id: core-concept title: Core Concept instruction: 2-3 sentences that clearly describe what the game is and why players will love it - id: target-audience title: Target Audience instruction: Define the primary and secondary audience with demographics and gaming preferences template: | **Primary:** {{age_range}}, {{player_type}}, {{platform_preference}} **Secondary:** {{secondary_audience}} - id: platform-technical title: Platform & Technical Requirements instruction: Based on the technical preferences or user input, define the target platforms template: | **Primary Platform:** {{platform}} **Engine:** Unity & C# **Performance Target:** Stable FPS on {{minimum_device}} **Screen Support:** {{resolution_range}} - id: unique-selling-points title: Unique Selling Points instruction: List 3-5 key features that differentiate this game from competitors type: numbered-list template: "{{usp}}"
- id: core-gameplay title: Core Gameplay instruction: This section defines the fundamental game mechanics. After presenting each subsection, apply `tasks#advanced-elicitation` protocol to ensure completeness. sections: - id: game-pillars title: Game Pillars instruction: Define 3-5 core pillars that guide all design decisions. These should be specific and actionable. type: numbered-list template: | **{{pillar_name}}** - {{description}} - id: core-gameplay-loop title: Core Gameplay Loop instruction: Define the 30-60 second loop that players will repeat. Be specific about timing and player actions. template: | **Primary Loop ({{duration}} seconds):**
1. {{action_1}} ({{time_1}}s) 2. {{action_2}} ({{time_2}}s) 3. {{action_3}} ({{time_3}}s) 4. {{reward_feedback}} ({{time_4}}s) - id: win-loss-conditions title: Win/Loss Conditions instruction: Clearly define success and failure states template: | **Victory Conditions:**
- {{win_condition_1}} - {{win_condition_2}}
**Failure States:**
- {{loss_condition_1}} - {{loss_condition_2}}
- id: game-mechanics title: Game Mechanics instruction: Detail each major mechanic that will need to be implemented. Each mechanic should be specific enough for developers to create implementation stories. sections: - id: primary-mechanics title: Primary Mechanics repeatable: true sections: - id: mechanic title: "{{mechanic_name}}" template: | **Description:** {{detailed_description}}
**Player Input:** {{input_method}}
**System Response:** {{game_response}}
**Implementation Notes:**
- {{tech_requirement_1}} - {{tech_requirement_2}} - {{performance_consideration}}
**Dependencies:** {{other_mechanics_needed}} - id: controls title: Controls instruction: Define all input methods for different platforms type: table template: | | Action | Desktop | Mobile | Gamepad | | ------ | ------- | ------ | ------- | | {{action}} | {{key}} | {{gesture}} | {{button}} |
- id: progression-balance title: Progression & Balance instruction: Define how players advance and how difficulty scales. This section should provide clear parameters for implementation. sections: - id: player-progression title: Player Progression template: | **Progression Type:** {{linear|branching|metroidvania}}
**Key Milestones:**
1. **{{milestone_1}}** - {{unlock_description}} 2. **{{milestone_2}}** - {{unlock_description}} 3. **{{milestone_3}}** - {{unlock_description}} - id: difficulty-curve title: Difficulty Curve instruction: Provide specific parameters for balancing template: | **Tutorial Phase:** {{duration}} - {{difficulty_description}} **Early Game:** {{duration}} - {{difficulty_description}} **Mid Game:** {{duration}} - {{difficulty_description}} **Late Game:** {{duration}} - {{difficulty_description}} - id: economy-resources title: Economy & Resources condition: has_economy instruction: Define any in-game currencies, resources, or collectibles type: table template: | | Resource | Earn Rate | Spend Rate | Purpose | Cap | | -------- | --------- | ---------- | ------- | --- | | {{resource}} | {{rate}} | {{rate}} | {{use}} | {{max}} |
- id: level-design-framework title: Level Design Framework instruction: Provide guidelines for level creation that developers can use to create level implementation stories sections: - id: level-types title: Level Types repeatable: true sections: - id: level-type title: "{{level_type_name}}" template: | **Purpose:** {{gameplay_purpose}} **Duration:** {{target_time}} **Key Elements:** {{required_mechanics}} **Difficulty:** {{relative_difficulty}}
**Structure Template:**
- Introduction: {{intro_description}} - Challenge: {{main_challenge}} - Resolution: {{completion_requirement}} - id: level-progression title: Level Progression template: | **World Structure:** {{linear|hub|open}} **Total Levels:** {{number}} **Unlock Pattern:** {{progression_method}}
- id: technical-specifications title: Technical Specifications instruction: Define technical requirements that will guide architecture and implementation decisions. Review any existing technical preferences. sections: - id: performance-requirements title: Performance Requirements template: | **Frame Rate:** Stable FPS (minimum 30 FPS on low-end devices) **Memory Usage:** <{{memory_limit}}MB **Load Times:** <{{load_time}}s initial, <{{level_load}}s between levels **Battery Usage:** Optimized for mobile devices - id: platform-specific title: Platform Specific template: | **Desktop:**
- Resolution: {{min_resolution}} - {{max_resolution}} - Input: Keyboard, Mouse, Gamepad - Browser: Chrome 80+, Firefox 75+, Safari 13+
**Mobile:**
- Resolution: {{mobile_min}} - {{mobile_max}} - Input: Touch, Tilt (optional) - OS: iOS 13+, Android 8+ - id: asset-requirements title: Asset Requirements instruction: Define asset specifications for the art and audio teams template: | **Visual Assets:**
- Art Style: {{style_description}} - Color Palette: {{color_specification}} - Animation: {{animation_requirements}} - UI Resolution: {{ui_specs}}
**Audio Assets:**
- Music Style: {{music_genre}} - Sound Effects: {{sfx_requirements}} - Voice Acting: {{voice_needs}}
- id: technical-architecture-requirements title: Technical Architecture Requirements instruction: Define high-level technical requirements that the game architecture must support sections: - id: engine-configuration title: Engine Configuration template: | **Unity Setup:**
- C#: Latest stable version - Physics: 2D Physics - Renderer: 2D Renderer (URP) - Input System: New Input System - id: code-architecture title: Code Architecture template: | **Required Systems:**
- Scene Management - State Management - Asset Loading - Save/Load System - Input Management - Audio System - Performance Monitoring - id: data-management title: Data Management template: | **Save Data:**
- Progress tracking - Settings persistence - Statistics collection - {{additional_data}}
- id: development-phases title: Development Phases instruction: Break down the development into phases that can be converted to epics sections: - id: phase-1-core-systems title: "Phase 1: Core Systems ({{duration}})" sections: - id: foundation-epic title: "Epic: Foundation" type: bullet-list template: | - Engine setup and configuration - Basic scene management - Core input handling - Asset loading pipeline - id: core-mechanics-epic title: "Epic: Core Mechanics" type: bullet-list template: | - {{primary_mechanic}} implementation - Basic physics and collision - Player controller - id: phase-2-gameplay-features title: "Phase 2: Gameplay Features ({{duration}})" sections: - id: game-systems-epic title: "Epic: Game Systems" type: bullet-list template: | - {{mechanic_2}} implementation - {{mechanic_3}} implementation - Game state management - id: content-creation-epic title: "Epic: Content Creation" type: bullet-list template: | - Level loading system - First playable levels - Basic UI implementation - id: phase-3-polish-optimization title: "Phase 3: Polish & Optimization ({{duration}})" sections: - id: performance-epic title: "Epic: Performance" type: bullet-list template: | - Optimization and profiling - Mobile platform testing - Memory management - id: user-experience-epic title: "Epic: User Experience" type: bullet-list template: | - Audio implementation - Visual effects and polish - Final UI/UX refinement
- id: success-metrics title: Success Metrics instruction: Define measurable goals for the game sections: - id: technical-metrics title: Technical Metrics type: bullet-list template: | - Frame rate: {{fps_target}} - Load time: {{load_target}} - Crash rate: <{{crash_threshold}}% - Memory usage: <{{memory_target}}MB - id: gameplay-metrics title: Gameplay Metrics type: bullet-list template: | - Tutorial completion: {{completion_rate}}% - Average session: {{session_length}} minutes - Level completion: {{level_completion}}% - Player retention: D1 {{d1}}%, D7 {{d7}}%
- id: appendices title: Appendices sections: - id: change-log title: Change Log instruction: Track document versions and changes type: table template: | | Date | Version | Description | Author | | :--- | :------ | :---------- | :----- | - id: references title: References instruction: List any competitive analysis, inspiration, or research sources type: bullet-list template: "{{reference}}"

template: id: game-brief-template-v2 name: Game Brief version: 2.0 output: format: markdown filename: "docs/{{game_name}}-game-brief.md" title: "{{game_title}} Game Brief"
workflow: mode: interactive
sections: - id: initial-setup instruction: | This template creates a comprehensive game brief that serves as the foundation for all subsequent game development work. The brief should capture the essential vision, scope, and requirements needed to create a detailed Game Design Document.
This brief is typically created early in the ideation process, often after brainstorming sessions, to crystallize the game concept before moving into detailed design.
