#!/bin/sh
# An example hook script to validate a patch (and/or patch series) before # sending it via email. # # The hook should exit with non-zero status after issuing an appropriate # message if it wants to prevent the email(s) from being sent. # # To enable this hook, rename this file to "sendemail-validate". # # By default, it will only check that the patch(es) can be applied on top of # the default upstream branch without conflicts in a secondary worktree. After # validation (successful or not) of the last patch of a series, the worktree # will be deleted. # # The following config variables can be set to change the default remote and # remote ref that are used to apply the patches against: # # sendemail.validateRemote (default: origin) # sendemail.validateRemoteRef (default: HEAD) # # Replace the TODO placeholders with appropriate checks according to your # needs.
validate_cover_letter () { file="$1" # TODO: Replace with appropriate checks (e.g. spell checking). true }
validate_patch () { file="$1" # Ensure that the patch applies without conflicts. git am -3 "$file" || return # TODO: Replace with appropriate checks for this patch # (e.g. checkpatch.pl). true }
validate_series () { # TODO: Replace with appropriate checks for the whole series # (e.g. quick build, coding style checks, etc.). true }
# main -------------------------------------------------------------------------
if test "$GIT_SENDEMAIL_FILE_COUNTER" = 1 then remote=$(git config --default origin --get sendemail.validateRemote) && ref=$(git config --default HEAD --get sendemail.validateRemoteRef) && worktree=$(mktemp --tmpdir -d sendemail-validate.XXXXXXX) && git worktree add -fd --checkout "$worktree" "refs/remotes/$remote/$ref" && git config --replace-all sendemail.validateWorktree "$worktree" else worktree=$(git config --get sendemail.validateWorktree) fi || { echo "sendemail-validate: error: failed to prepare worktree" >&2 exit 1 }
unset GIT_DIR GIT_WORK_TREE cd "$worktree" &&
if grep -q "^diff --git " "$1" then validate_patch "$1" else validate_cover_letter "$1" fi &&
if test "$GIT_SENDEMAIL_FILE_COUNTER" = "$GIT_SENDEMAIL_FILE_TOTAL" then git config --unset-all sendemail.validateWorktree && trap 'git worktree remove -ff "$worktree"' EXIT && validate_series fi

#!/usr/bin/perl

use strict;
use warnings;
use IPC::Open2;

# An example hook script to integrate Watchman
# (https://facebook.github.io/watchman/) with git to speed up detecting
# new and modified files.
#
# The hook is passed a version (currently 2) and last update token
# formatted as a string and outputs to stdout a new update token and
# all files that have been modified since the update token. Paths must
# be relative to the root of the working tree and separated by a single NUL.
#
# To enable this hook, rename this file to "query-watchman" and set
# 'git config core.fsmonitor .git/hooks/query-watchman'
#
my ($version, $last_update_token) = @ARGV;

# Uncomment for debugging
# print STDERR "$0 $version $last_update_token\n";

# Check the hook interface version
if ($version ne 2) {
	die "Unsupported query-fsmonitor hook version '$version'.\n" .
	    "Falling back to scanning...\n";
}

my $git_work_tree = get_working_dir();

my $retry = 1;

my $json_pkg;
eval {
	require JSON::XS;
	$json_pkg = "JSON::XS";
	1;
} or do {
	require JSON::PP;
	$json_pkg = "JSON::PP";
};

launch_watchman();

sub launch_watchman {
	my $o = watchman_query();
	if (is_work_tree_watched($o)) {
		output_result($o->{clock}, @{$o->{files}});
	}
}

sub output_result {
	my ($clockid, @files) = @_;

	# Uncomment for debugging watchman output
	# open (my $fh, ">", ".git/watchman-output.out");
	# binmode $fh, ":utf8";
	# print $fh "$clockid\n@files\n";
	# close $fh;

	binmode STDOUT, ":utf8";
	print $clockid;
	print "\0";
	local $, = "\0";
	print @files;
}

sub watchman_clock {
	my $response = qx/watchman clock "$git_work_tree"/;
	die "Failed to get clock id on '$git_work_tree'.\n" .
		"Falling back to scanning...\n" if $? != 0;

	return $json_pkg->new->utf8->decode($response);
}

sub watchman_query {
	my $pid = open2(\*CHLD_OUT, \*CHLD_IN, 'watchman -j --no-pretty')
	or die "open2() failed: $!\n" .
	"Falling back to scanning...\n";

	# In the query expression below we're asking for names of files that
	# changed since $last_update_token but not from the .git folder.
	#
	# To accomplish this, we're using the "since" generator to use the
	# recency index to select candidate nodes and "fields" to limit the
	# output to file names only. Then we're using the "expression" term to
	# further constrain the results.
	my $last_update_line = "";
	if (substr($last_update_token, 0, 1) eq "c") {
		$last_update_token = "\"$last_update_token\"";
		$last_update_line = qq[\n"since": $last_update_token,];
	}
	my $query = <<"	END";
		["query", "$git_work_tree", {$last_update_line
			"fields": ["name"],
			"expression": ["not", ["dirname", ".git"]]
		}]
	END

	# Uncomment for debugging the watchman query
	# open (my $fh, ">", ".git/watchman-query.json");
	# print $fh $query;
	# close $fh;

	print CHLD_IN $query;
	close CHLD_IN;
	my $response = do {local $/; <CHLD_OUT>};

	# Uncomment for debugging the watch response
	# open ($fh, ">", ".git/watchman-response.json");
	# print $fh $response;
	# close $fh;

	die "Watchman: command returned no output.\n" .
	"Falling back to scanning...\n" if $response eq "";
	die "Watchman: command returned invalid output: $response\n" .
	"Falling back to scanning...\n" unless $response =~ /^\{/;

	return $json_pkg->new->utf8->decode($response);
}

sub is_work_tree_watched {
	my ($output) = @_;
	my $error = $output->{error};
	if ($retry > 0 and $error and $error =~ m/unable to resolve root .* directory (.*) is not watched/) {
		$retry--;
		my $response = qx/watchman watch "$git_work_tree"/;
		die "Failed to make watchman watch '$git_work_tree'.\n" .
		    "Falling back to scanning...\n" if $? != 0;
		$output = $json_pkg->new->utf8->decode($response);
		$error = $output->{error};
		die "Watchman: $error.\n" .
		"Falling back to scanning...\n" if $error;

		# Uncomment for debugging watchman output
		# open (my $fh, ">", ".git/watchman-output.out");
		# close $fh;

		# Watchman will always return all files on the first query so
		# return the fast "everything is dirty" flag to git and do the
		# Watchman query just to get it over with now so we won't pay
		# the cost in git to look up each individual file.
		my $o = watchman_clock();
		$error = $output->{error};

		die "Watchman: $error.\n" .
		"Falling back to scanning...\n" if $error;

		output_result($o->{clock}, ("/"));
		$last_update_token = $o->{clock};

		eval { launch_watchman() };
		return 0;
	}

	die "Watchman: $error.\n" .
	"Falling back to scanning...\n" if $error;

	return 1;
}

sub get_working_dir {
	my $working_dir;
	if ($^O =~ 'msys' || $^O =~ 'cygwin') {
		$working_dir = Win32::GetCwd();
		$working_dir =~ tr/\\/\//;
	} else {
		require Cwd;
		$working_dir = Cwd::cwd();
	}

	return $working_dir;
}

#!/bin/sh # # An example hook script to check the commit log message. # Called by "git commit" with one argument, the name of the file # that has the commit message. The hook should exit with non-zero # status after issuing an appropriate message if it wants to stop the # commit. The hook is allowed to edit the commit message file. # # To enable this hook, rename this file to "commit-msg".
# Uncomment the below to add a Signed-off-by line to the message. # Doing this in a hook is a bad idea in general, but the prepare-commit-msg # hook is more suited to it. # # SOB=$(git var GIT_AUTHOR_IDENT | sed -n 's/^\(.*>\).*$/Signed-off-by: \1/p') # grep -qs "^$SOB" "$1" || echo "$SOB" >> "$1"
# This example catches duplicate Signed-off-by lines.
test "" = "$(grep '^Signed-off-by: ' "$1" | sort | uniq -c | sed -e '/^[ ]*1[ ]/d')" || { echo >&2 Duplicate Signed-off-by lines. exit 1 }

import sentry_sdk import discord # Pycord (discord.py compatible) from shared.utils.ui_styles import get_panel_sub_header from shared.utils.headers import get_system_status_header from core.redis_cache import invalidate_user_json_cache, get_or_cache_user_json_data from features.quests.ui.quest_panel import build_quest_panel_embed from core.database import db as db_utils from typing import Union import asyncio from shared.utils.headers import render_loading_embed from shared.utils.ui_helpers import create_loading_animation, interaction_handler
async def build_quest_reroll_embed(bot, user: Union[discord.User, discord.Member]): json_data = None try: header = get_system_status_header(user).replace('```ansi', '').replace('```', '').strip() sub_header = get_panel_sub_header("quest_reroll") import json json_data = await get_or_cache_user_json_data(bot, user.id) daily_quests_raw = json_data.get("daily_quests", {}) daily_quests = daily_quests_raw.get("quests", []) if isinstance(daily_quests_raw, dict) else daily_quests_raw # Parse quest objects if they are strings parsed_daily_quests = [] for q in daily_quests: if isinstance(q, str): try: parsed_daily_quests.append(json.loads(q)) except Exception: sentry_sdk.capture_message(f"Failed to parse daily quest: {q}") elif isinstance(q, dict): parsed_daily_quests.append(q) # Build daily quest summary if parsed_daily_quests: dq = parsed_daily_quests[0] dq_name = dq.get("QuestName") or dq.get("name") or dq.get("quest_name") or "?" dq_tasks = dq.get("Movements") or dq.get("movements") or [] if isinstance(dq_tasks, str): try: dq_tasks = json.loads(dq_tasks) except Exception: dq_tasks = [dq_tasks] dq_xp = dq.get("XPReward") or dq.get("xpReward") or dq.get("xp_reward") or 0 dq_buff = dq.get("BuffReward") or dq.get("buffReward") or dq.get("buff_reward") daily_summary = f"**{dq_name}**
Tasks: {', '.join(dq_tasks)}
Reward: {dq_xp} XP" + (f", {dq_buff}" if dq_buff else "") else: daily_summary = "No daily quest." weekly_contracts_raw = json_data.get("weekly_contracts", {}) weekly_contracts = weekly_contracts_raw.get("contracts", []) if isinstance(weekly_contracts_raw, dict) else weekly_contracts_raw parsed_weekly_contracts = [] for q in weekly_contracts: if isinstance(q, str): try: parsed_weekly_contracts.append(json.loads(q)) except Exception: sentry_sdk.capture_message(f"Failed to parse weekly contract: {q}") elif isinstance(q, dict): parsed_weekly_contracts.append(q) else: sentry_sdk.capture_message(f"Unexpected weekly contract type: {type(q)} value: {q}") if parsed_weekly_contracts and isinstance(parsed_weekly_contracts[0], dict): wc = parsed_weekly_contracts[0] wc_name = wc.get("ContractName") or wc.get("name") or wc.get("contract_name") or "?" wc_obj = wc.get("Objectives") or [] wc_obj_lines = [] for obj in wc_obj: t = obj.get("type") tgt = obj.get("target", 0) if t == "complete_dailies": wc_obj_lines.append(f"Complete Daily Quests x{tgt}") elif t == "total_reps": wc_obj_lines.append(f"Log {tgt} reps") elif t == "training_days": wc_obj_lines.append(f"Train {tgt} days") elif t == "side_quest": wc_obj_lines.append(f"Side Quest: {obj.get('desc', '?')}") else: wc_obj_lines.append(f"{t or '?'}: {tgt}") wc_xp = wc.get("XPReward") or wc.get("xpReward") or wc.get("xp_reward") or 0 wc_buff = wc.get("BuffReward") or wc.get("buffReward") or wc.get("buff_reward") weekly_summary = f"**{wc_name}**
Tasks: {', '.join(wc_obj_lines)}
Reward: {wc_xp} XP" + (f", {wc_buff}" if wc_buff else "") else: weekly_summary = "No weekly contract." desc = ( f"{header}
{sub_header}

Your quests have been rerolled!

" f"**New Daily Quest:**
{daily_summary}

" f"**New Weekly Contract:**
{weekly_summary}
" ) embed = discord.Embed( title="🔄 Quests Rerolled!", description=f"```ansi
{desc}
```", color=discord.Color.gold() ) embed.set_footer(text="Shadow Archive • Quest Database") return embed except KeyError as e: sentry_sdk.capture_exception(e) sentry_sdk.capture_message(f"Quest reroll KeyError: {e}, user={getattr(user, 'id', None)}, json_data={json_data}") embed = discord.Embed( title="🔄 Quests Rerolled!", description="```ansi
