def get_reroll_summary_view(bot, user): return BackToMenuView(bot, user)
class ConfirmRerollView(discord.ui.View): def __init__(self, bot, user: Union[discord.User, discord.Member]): super().__init__(timeout=60) self.bot = bot self.user = user # Red danger button with triangle danger icon self.confirm_button = discord.ui.Button(label="⚠️ Confirm Reroll", style=discord.ButtonStyle.danger) self.confirm_button.callback = self.confirm_reroll self.add_item(self.confirm_button) self.cancel_button = discord.ui.Button(label="Cancel", style=discord.ButtonStyle.secondary) self.cancel_button.callback = self.cancel_reroll self.add_item(self.cancel_button)
async def interaction_check(self, interaction: discord.Interaction) -> bool: return bool(interaction.user) and interaction.user.id == self.user.id
async def on_timeout(self): self.clear_items()
async def _check_reroll_limit(self, user_id, bot): from features.user.logic.user_data import load_user_data import datetime today = datetime.date.today().isoformat() user_data = await load_user_data(user_id, bot=bot) dq_data = user_data.get("daily_quests", {}) return dq_data.get("rerolled") == today
@interaction_handler(ephemeral=True, with_loading=True) async def confirm_reroll(self, interaction: discord.Interaction): try: sentry_sdk.capture_message(f"confirm_reroll called for user {self.user.id}")
from features.quests.logic.daily_quests.daily_quest_logic import reroll_daily_quests from features.user.logic.user_data import load_user_data, save_user_data import datetime user_id = self.user.id today = datetime.date.today().isoformat() # Always force cache invalidation and fetch fresh user data await invalidate_user_json_cache(self.bot, user_id) user_data = await load_user_data(user_id, bot=self.bot) dq_data = user_data.get("daily_quests", {}) rerolled_flag = dq_data.get("rerolled") sentry_sdk.capture_message(f"[REROLL CHECK] user={user_id} rerolled_flag={repr(rerolled_flag)} source=pre-reroll") print(f"[REROLL CHECK] user={user_id} rerolled_flag={repr(rerolled_flag)} source=pre-reroll") # Only block reroll if rerolled is a non-empty string and equals today reroll_blocked = isinstance(rerolled_flag, str) and rerolled_flag == today
if reroll_blocked: embed = build_reroll_confirm_embed(self.user, already_rerolled=True, add_back_button=True) view = get_reroll_limit_view(self.bot, self.user) await interaction.edit_original_response(embed=embed, view=view) return # Actually reroll (generates 3-5 quests with random tiers) await reroll_daily_quests(user_id, bot=self.bot) # After reroll, set rerolled flag and save, then show success embed directly await invalidate_user_json_cache(self.bot, user_id) user_data = await load_user_data(user_id, bot=self.bot) dq_data = user_data.get("daily_quests", {}) dq_data["rerolled"] = today user_data["daily_quests"] = dq_data await save_user_data(user_id, user_data, bot=self.bot) await invalidate_user_json_cache(self.bot, user_id) embed = await build_quest_reroll_embed(self.bot, self.user) view = get_reroll_summary_view(self.bot, self.user) self.clear_items() await interaction.edit_original_response(embed=embed, view=view) except Exception as e: sentry_sdk.capture_exception(e) print(f"[REROLL ERROR] {e}") try: await interaction.edit_original_response(content="❌ An error occurred while processing your reroll. Please try again or contact support.", embed=None, view=None) except Exception: pass
