Args: request: Incursion creation data
Returns: IncursionResponse: The created incursion """ try: incursion = await service.create_incursion( title=request.title, description=request.description, incursion_type=request.incursion_type, target_exercise=request.target_exercise, target_reps=request.target_reps, reward_type=request.reward_type, reward_value=request.reward_value, reward_description=request.reward_description, duration_hours=request.duration_hours, metadata=request.metadata )
return IncursionResponse( id=incursion.id, incursion_id=incursion.incursion_id, title=incursion.title, description=incursion.description, incursion_type=incursion.incursion_type, target_exercise=incursion.target_exercise, target_reps=incursion.target_reps, current_reps=incursion.current_reps, reward_type=incursion.reward_type, reward_value=incursion.reward_value, reward_description=incursion.reward_description, status=incursion.status, is_active=incursion.is_active, expires_at=incursion.expires_at, created_at=incursion.created_at, updated_at=incursion.updated_at, progress_percentage=incursion.progress_percentage, is_completed=incursion.is_completed, participant_count=0, # New incursion has no participants metadata=incursion.metadata )
except ValueError as e: raise HTTPException( status_code=status.HTTP_400_BAD_REQUEST, detail=str(e) ) except Exception as e: raise HTTPException( status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=f"Failed to create incursion: {str(e)}" )
@router.post("/{incursion_id}/contribute", response_model=ParticipantContributionResponse) async def add_contribution( incursion_id: str, request: ParticipantContributionRequest, service: IncursionService = Depends(get_incursion_service) ): """ Add a user's contribution to an incursion.
Args: incursion_id: The incursion identifier request: Contribution data
Returns: ParticipantContributionResponse: Result of the contribution """ try: # Get incursion before contribution to check completion status incursion_before = await service.get_incursion_by_id(incursion_id) if not incursion_before: raise HTTPException( status_code=status.HTTP_404_NOT_FOUND, detail=f"Incursion {incursion_id} not found" )
was_completed = incursion_before.is_completed
# Add contribution success = await service.add_participant_contribution( incursion_id=incursion_id, user_id=request.user_id, reps=request.reps )
if not success: return ParticipantContributionResponse( success=False, message="Failed to add contribution. Incursion may be inactive or expired." )
# Check if incursion was completed by this contribution incursion_after = await service.get_incursion_by_id(incursion_id) incursion_completed = not was_completed and incursion_after.is_completed
message = f"Successfully contributed {request.reps} reps" if incursion_completed: message += ". Incursion completed!"
return ParticipantContributionResponse( success=True, message=message, incursion_completed=incursion_completed )
except HTTPException: raise except ValueError as e: raise HTTPException( status_code=status.HTTP_400_BAD_REQUEST, detail=str(e) ) except Exception as e: raise HTTPException( status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=f"Failed to add contribution: {str(e)}" )
