return {"message": f"Incursion {incursion_id} ended successfully", "reason": reason}
except HTTPException: raise except Exception as e: raise HTTPException( status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=f"Failed to end incursion: {str(e)}" )
