## Development Workflow

### Story Implementation Process

1. **Read Story Requirements:**

   - Understand acceptance criteria
   - Identify technical requirements
   - Review performance constraints

2. **Plan Implementation:**

   - Identify files to create/modify
   - Consider component architecture
   - Plan testing approach

3. **Implement Feature:**

   - Follow TypeScript strict mode
   - Use established patterns
   - Maintain 60 FPS performance

4. **Test Implementation:**

   - Write unit tests for game logic
   - Test cross-platform functionality
   - Validate performance targets

5. **Update Documentation:**
   - Mark story checkboxes complete
   - Document any deviations
   - Update architecture if needed

### Code Review Checklist

**Before Committing:**

- [ ] TypeScript compiles without errors
- [ ] All tests pass
- [ ] Performance targets met (60 FPS)
- [ ] No console errors or warnings
- [ ] Cross-platform compatibility verified
- [ ] Memory usage within bounds
- [ ] Code follows naming conventions
- [ ] Error handling implemented
- [ ] Documentation updated

## Performance Targets

### Frame Rate Requirements

- **Desktop**: Maintain 60 FPS at 1080p
- **Mobile**: Maintain 60 FPS on mid-range devices, minimum 30 FPS on low-end
- **Optimization**: Implement dynamic quality scaling when performance drops

### Memory Management

- **Total Memory**: Under 100MB for full game
- **Per Scene**: Under 50MB per gameplay scene
- **Asset Loading**: Progressive loading to stay under limits
- **Garbage Collection**: Minimize object creation in update loops

### Loading Performance

- **Initial Load**: Under 5 seconds for game start
- **Scene Transitions**: Under 2 seconds between scenes
- **Asset Streaming**: Background loading for upcoming content

These guidelines ensure consistent, high-quality game development that meets performance targets and maintains code quality across all implementation stories.

# utils/generate_daily_quests.py
import random from datetime import datetime from features.quests.logic.quest_data import save_today_quests from features.user.logic.xp_engine import MOVEMENT_DATA
def pick_main_buff(): import random buffs = ["xp_boost_5", "recovery_aura", "shadow_focus", None] return random.choice(buffs)
def pick_side_buff(): import random side_buffs = ["bonus_log_chance", "focus_hint", None, None] return random.choice(side_buffs)
QUEST_NAMES = { 1: "Veins of the Abyss", 2: "Ritual of the Core", 3: "Iron Cradle", 4: "Whispers of the Flesh", 5: "Burden of Bone", 6: "Elegy of Sinew", 7: "Grim Edict", 8: "Oath to Obsidian", 9: "Feast of the Hollow", 10: "The Nameless Reign", }
QUEST_QUOTES = { 1: "The path begins in silence.", 2: "Steel your breath for the shaping.", 3: "Pain teaches what memory forgets.", 4: "Your flesh remembers. Make it earn the silence.", 5: "The marrow bends before it breaks.", 6: "Scars do not speak. They judge.", 7: "You are your burden. Carry it.", 8: "The forge sings for no one.", 9: "Ritual is strength made obedient.", 10: "What rises from the grave no longer fears the dark.", }
def get_unlocked_tiers(level: int): return list(range(1, min(11, (level - 1) // 5 + 2))) # +1 tier every 5 levels
def get_daily_quest_count(level: int) -> int: return min(3 + (level // 10), 7)
def get_movements_by_tier(tiers: list[int]): return [m for m, info in MOVEMENT_DATA.items() if info["tier"] in tiers]
def reps_for_tier(tier: int): return 20 + (tier - 1) * 10 # Tier 1: 20 → Tier 10: 110
def roll_buff(tier: int): if random.random() < 0.3: buff_value = 5 + (tier // 3) * 5 # Tier 3+ = +10%, Tier 6+ = +15% return f"+{buff_value}% XP for 24h" return None
def calculate_xp_reward(movements: dict): total = 0 for move, reps in movements.items(): xp_per_rep = MOVEMENT_DATA.get(move, {}).get("xp", 1) total += reps * xp_per_rep return int(total)
def generate_daily_quests(user_id: int, username: str, level: int): tiers = get_unlocked_tiers(level) quest_count = get_daily_quest_count(level) all_quests = []
for _ in range(quest_count): tier = random.choice(tiers) reps = reps_for_tier(tier)
pool = get_movements_by_tier([t for t in tiers if t <= tier])
# Fix: Handle cases where pool has fewer movements than needed movement_count = min(4, len(pool)) # Use available movements, max 4 if movement_count == 0: # Fallback: use all available movements regardless of tier pool = list(MOVEMENT_DATA.keys()) movement_count = min(4, len(pool))
chosen = random.sample(pool, k=movement_count)
targets = {m: reps for m in chosen} progress = {m: 0 for m in chosen}
quest = { "Tier": tier, "QuestName": QUEST_NAMES.get(tier, f"Tier {tier} Quest"), "Flavor": QUEST_QUOTES.get(tier, ""), "Movements": chosen, # List of movement names "Targets": targets, # Dict of movement: reps "BuffReward": roll_buff(tier), "Progress": progress, "XPReward": calculate_xp_reward(targets), "Active": False, "Completed": False }
all_quests.append(quest)
save_today_quests(user_id, all_quests) return all_quests

import discord from discord.ui import Button, View import asyncio from features.user.logic.user_data import load_user_data, save_user_data
class EnhancedDailyQuestView(View): """Generate enhanced daily quests with themes and modifiers""" user_data = load_user_data(user_id) user_level = user_data.get("level", 1)
# Select 2-3 random themes selected_themes = random.sample(list(QUEST_THEMES.keys()), min(3, len(QUEST_THEMES))) quests = []
for theme_key in selected_themes: theme = QUEST_THEMES[theme_key]
# Select random movement from theme movement = random.choice(theme["movements"])
# Calculate base reps based on user level and movement difficulty base_reps = calculate_quest_reps(movement, user_level)
# Maybe add a modifier (30% chance) modifier = None if random.random() < 0.3: # Higher level users get better chance at rare modifiers modifier_pool = [m for m, data in QUEST_MODIFIERS.items() if should_get_modifier(data["rarity"], user_level)] if modifier_pool: modifier_key = random.choice(modifier_pool) modifier = QUEST_MODIFIERS[modifier_key]
# Apply modifier effects final_reps = base_reps xp_multiplier = 1.0
if modifier: if "rep_multiplier" in modifier: final_reps = int(base_reps * modifier["rep_multiplier"]) if "xp_multiplier" in modifier: xp_multiplier = modifier["xp_multiplier"]
# Create quest quest = { "id": f"daily_{theme_key}_{date.today().isoformat()}", "theme": theme, "movement": movement, "target_reps": final_reps, "progress": 0, "completed": False, "BuffReward": pick_main_buff(), "SideBuffReward": pick_side_buff(), "modifier": modifier, "xp_multiplier": xp_multiplier, "flavor_text": random.choice(theme["flavor"]), "created_date": date.today().isoformat() }
quests.append(quest)
return quests
def calculate_quest_reps(movement: str, user_level: int) -> int: """Calculate appropriate rep count based on movement and user level""" base_reps = { "Push-Ups": 30, "Pull-Ups": 15, "Squats": 40, "Crunches": 50, "Planks": 120, # seconds "Knee Raises": 25, "Dips": 20, "Jump Squats": 25, "Bulgarian Split Squats": 20, "L-Sit / V-Ups": 15, "Hollow Hold": 90, # seconds "Walking": 5000 # steps }
base = base_reps.get(movement, 30) # Scale with level but cap growth level_multiplier = 1 + (user_level - 1) * 0.1 level_multiplier = min(level_multiplier, 2.5) # Cap at 2.5x
return int(base * level_multiplier)
def should_get_modifier(rarity: str, user_level: int) -> bool: """Determine if user should get a modifier based on rarity and level""" chances = { "common": 0.6, "uncommon": 0.3 + (user_level * 0.01), "rare": 0.1 + (user_level * 0.015), "legendary": 0.02 + (user_level * 0.008) }
return random.random() < chances.get(rarity, 0.1)
def get_daily_quest_summary(user_id: int) -> Dict: """Get summary of today's quests with progress""" user_data = load_user_data(user_id) today = date.today().isoformat()
daily_quests = user_data.get("daily_quests", {}) today_quests = daily_quests.get(today, [])
if not today_quests: # Generate new quests if none exist today_quests = generate_enhanced_daily_quests(user_id) daily_quests[today] = today_quests user_data["daily_quests"] = daily_quests save_user_data(user_id, user_data)
completed = sum(1 for q in today_quests if q.get("completed", False)) total = len(today_quests)
return { "quests": today_quests, "completed": completed, "total": total, "completion_rate": completed / total if total > 0 else 0 }

"""
API schemas for movement logging endpoints.

These schemas define the request and response models for the movement logging API,
including validation rules and documentation.
"""
from typing import Optional, Dict, Any, List
from pydantic import BaseModel, Field, field_validator, ConfigDict


class LogMovementRequest(BaseModel):
    """
    Request model for logging movement reps.

    This model validates the input for the POST /v2/events/log-movement endpoint.
    """

    model_config = ConfigDict(
        json_schema_extra={
            "example": {
                "movement_id": 1,
                "reps": 10,
                "session_id": "workout_session_123"
            }
        }
    )

    movement_id: int = Field(
        ..., 
        gt=0, 
        description="ID of the movement being logged (must be positive)"
    )

    reps: int = Field(
        ..., 
        gt=0, 
        le=10000,  # Reasonable upper limit
        description="Number of repetitions performed (1-10000)"
    )

    session_id: Optional[str] = Field(
        None,
        max_length=100,
        description="Optional session tracking ID for analytics"
    )

    @field_validator('session_id')
    @classmethod
    def validate_session_id(cls, v):
        """Validate session_id format if provided."""
        if v is not None and len(v.strip()) == 0:
            return None
        return v


class MovementInfo(BaseModel):
    """Movement information in the response."""

    model_config = ConfigDict(
        json_schema_extra={
            "example": {
                "id": 1,
                "name": "Push-ups"
            }
        }
    )

    id: int = Field(..., description="Movement ID")
    name: str = Field(..., description="Movement name")


class LevelUpInfo(BaseModel):
    """Information about a level-up that occurred."""

    model_config = ConfigDict(
        json_schema_extra={
            "example": {
                "type": "strength",
                "new_level": 5,
                "points_earned": 2
            }
        }
    )

    type: str = Field(..., description="Type of level-up (global, strength, endurance, technique)")
    new_level: int = Field(..., description="New level achieved")
    points_earned: int = Field(..., description="Stat points earned from level-up")


class AuraUpdateInfo(BaseModel):
    """Information about aura changes."""

    model_config = ConfigDict(
        json_schema_extra={
            "example": {
                "previous_aura": 1250,
                "new_aura": 1275,
                "change": 25,
                "reason": "Strength progression"
            }
        }
    )

    previous_aura: int = Field(..., description="Previous aura value")
    new_aura: int = Field(..., description="New aura value")
    change: int = Field(..., description="Aura change amount")
    reason: str = Field(..., description="Reason for aura change")


class LogMovementResponse(BaseModel):
    """
    Response model for successful movement logging.

    Contains all information about what happened during the movement log,
    including XP earned, level-ups, and aura changes.
    """

    model_config = ConfigDict(
        json_schema_extra={
            "example": {
                "movement": {
                    "id": 1,
                    "name": "Push-ups"
                },
                "reps_logged": 10,
                "xp_earned": {
                    "global": 50,
                    "strength": 37
                },
                "level_ups": [
                    {
                        "type": "strength",
                        "new_level": 5,
                        "points_earned": 2
                    }
                ],
                "aura_update": {
                    "previous_aura": 1250,
                    "new_aura": 1275,
                    "change": 25,
                    "reason": "Strength progression"
                },
                "session_id": "workout_session_123"
            }
        }
    )

    movement: MovementInfo = Field(..., description="Information about the logged movement")

    reps_logged: int = Field(..., description="Number of reps that were logged")

    xp_earned: Dict[str, int] = Field(
        ..., 
        description="XP earned by category (global, strength, endurance, technique)"
    )

    level_ups: List[LevelUpInfo] = Field(
        default_factory=list,
        description="List of level-ups that occurred"
    )

    aura_update: Optional[AuraUpdateInfo] = Field(
        None,
        description="Aura update information if aura changed"
    )

    session_id: Optional[str] = Field(
        None,
        description="Session ID if provided in request"
    )


class ErrorResponse(BaseModel):
    """Standard error response model."""

    model_config = ConfigDict(
        json_schema_extra={
            "example": {
                "error": "Movement not found",
                "detail": "Movement with ID 999 does not exist"
            }
        }
    )

    error: str = Field(..., description="Error message")
    detail: Optional[str] = Field(None, description="Additional error details")

""" Pydantic schemas for DungeonKey and DungeonProgress models for V2. These are simple data containers aligned with our SQLAlchemy models. """ from pydantic import BaseModel, Field, ConfigDict, field_validator from typing import Optional, Dict, Any, List from datetime import datetime
# DungeonKey Schemas class DungeonKeyBase(BaseModel): """Base schema for DungeonKey with common fields""" ascendant_id: int = Field(..., description="The user who owns these keys") key_type: str = Field(default="shadow_key", max_length=50, description="The type of key") quantity: int = Field(default=0, ge=0, description="How many keys of this type the user has")
class DungeonKeyCreate(DungeonKeyBase): """Schema for creating a new DungeonKey""" pass
class DungeonKeyUpdate(BaseModel): """Schema for updating a DungeonKey""" key_type: Optional[str] = Field(None, max_length=50, description="The type of key") quantity: Optional[int] = Field(None, ge=0, description="How many keys of this type the user has")
class DungeonKeyResponse(DungeonKeyBase): """Schema for DungeonKey responses""" id: int = Field(..., description="Unique identifier for the dungeon key record")
model_config = ConfigDict(from_attributes=True)
# DungeonProgress Schemas class DungeonProgressBase(BaseModel): """Base schema for DungeonProgress with common fields""" ascendant_id: int = Field(..., description="The user whose progress is being tracked") highest_level_completed: int = Field(default=0, ge=0, description="The highest dungeon level completed")
class DungeonProgressCreate(DungeonProgressBase): """Schema for creating a new DungeonProgress""" pass
class DungeonProgressUpdate(BaseModel): """Schema for updating DungeonProgress""" highest_level_completed: Optional[int] = Field(None, ge=0, description="The highest dungeon level completed")
class DungeonProgressResponse(DungeonProgressBase): """Schema for DungeonProgress responses""" id: int = Field(..., description="Unique identifier for the dungeon progress record")
model_config = ConfigDict(from_attributes=True)
# Dungeon Entry and Trial Schemas class DungeonEntryRequest(BaseModel): """Schema for dungeon entry requests""" dungeon_level: int = Field(..., ge=1, description="The dungeon level to enter (infinite progression)")
@field_validator('dungeon_level') @classmethod def validate_dungeon_level(cls, v): if v < 1: raise ValueError('Dungeon level must be at least 1') return v
class TrialCompletionRequest(BaseModel): """Schema for trial completion requests""" trial_id: int = Field(..., gt=0, description="The trial being completed") progress_data: Dict[str, Any] = Field(..., description="Movement progress data")
@field_validator('progress_data') @classmethod def validate_progress_data(cls, v): required_fields = ['reps', 'duration', 'sets', 'distance'] if not any(field in v for field in required_fields): raise ValueError('Progress data must contain at least one progress field') return v
class TrialData(BaseModel): """Schema for trial data in dungeon responses""" id: int = Field(..., description="Trial identifier") movement_id: int = Field(..., description="Movement associated with this trial") movement_name: str = Field(..., description="Name of the movement") target_type: str = Field(..., description="Type of target (reps, duration, etc.)") target_value: int = Field(..., description="Target value to achieve") current_progress: int = Field(default=0, description="Current progress towards target") is_completed: bool = Field(default=False, description="Whether the trial is completed") difficulty_multiplier: float = Field(..., description="Difficulty multiplier for this trial")
class DungeonEntryResponse(BaseModel): """Schema for dungeon entry responses""" success: bool = Field(..., description="Whether the entry was successful") message: str = Field(..., description="Response message") session_id: int = Field(..., description="The created dungeon session ID") dungeon_level: int = Field(..., description="The dungeon level entered") shadow_keys_spent: int = Field(..., description="Number of shadow keys spent") trials: List[TrialData] = Field(..., description="List of trials for this session") daily_modifier: Optional[Dict[str, Any]] = Field(None, description="Active daily modifier") expires_at: datetime = Field(..., description="When the session expires")
class TrialCompletionResponse(BaseModel): """Schema for trial completion responses""" success: bool = Field(..., description="Whether the completion was successful") message: str = Field(..., description="Response message") trial_completed: bool = Field(..., description="Whether the trial was completed") session_completed: bool = Field(..., description="Whether the entire session was completed") rewards_earned: List[Dict[str, Any]] = Field(..., description="Rewards earned from completion") next_trial_available: bool = Field(..., description="Whether another trial is available")

""" Authentication schemas for V2 API.
Defines request/response models for user registration and authentication. """ from pydantic import BaseModel, Field from typing import Optional
class UserRegistrationRequest(BaseModel): """Request model for user registration.""" discord_id: str = Field(..., description="Discord user ID") username: str = Field(..., description="Discord username") display_name: Optional[str] = Field(None, description="Discord display name")
class UserRegistrationResponse(BaseModel): """Response model for user registration.""" user_id: int = Field(..., description="Database user ID") discord_id: str = Field(..., description="Discord user ID") username: str = Field(..., description="Username") is_new_user: bool = Field(..., description="Whether this is a new registration") access_token: str = Field(..., description="JWT access token") token_type: str = Field(default="bearer", description="Token type")
class UserLoginRequest(BaseModel): """Request model for user login.""" discord_id: str = Field(..., description="Discord user ID")
class UserLoginResponse(BaseModel): """Response model for user login.""" user_id: int = Field(..., description="Database user ID") discord_id: str = Field(..., description="Discord user ID") username: str = Field(..., description="Username") access_token: str = Field(..., description="JWT access token") token_type: str = Field(default="bearer", description="Token type")

