@router.post("/action", response_model=AwakeningActionResponse) async def create_awakening_session( request: AwakeningActionRequest, current_user_id: int = Depends(get_current_user_id), db: AsyncSession = Depends(get_async_session) ) -> AwakeningActionResponse: """ Create or retrieve today's awakening session for the user.
Args: request: Contains user_id and readiness_level current_user: Authenticated user information awakening_service: Awakening service (mock for development)
Returns: AwakeningActionResponse with session data and quests
Raises: HTTPException: If user not found or invalid readiness level """ try: # Initialize awakening service with database session awakening_service = AwakeningService(db)
# Validate readiness level readiness_int = {"low": 3, "medium": 5, "high": 8}.get(request.readiness_level, 5) if not (1 <= readiness_int <= 10): raise HTTPException( status_code=status.HTTP_400_BAD_REQUEST, detail="Invalid readiness level" )
# Get or create daily session session_data = await awakening_service.get_or_create_daily_session( user_id=request.user_id, readiness_level=request.readiness_level )
return AwakeningActionResponse(**session_data)
except ValueError as e: logger.error(f"Validation error in create_awakening_session: {e}") raise HTTPException( status_code=status.HTTP_400_BAD_REQUEST, detail=str(e) ) except Exception as e: logger.error(f"Error creating awakening session: {e}") raise HTTPException( status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail="Failed to create awakening session" )
