# Complete quest completion_data = await awakening_service.complete_quest( user_id=current_user_id, quest_id=quest_id, progress_data=request.dict() )
return QuestCompletionResponse(**completion_data)
except ValueError as e: logger.error(f"Validation error in complete_quest: {e}") raise HTTPException( status_code=status.HTTP_400_BAD_REQUEST, detail=str(e) ) except Exception as e: logger.error(f"Error completing quest {quest_id}: {e}") raise HTTPException( status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail="Failed to complete quest" )
@router.get("/status/{user_id}", response_model=AwakeningStatusResponse) async def get_awakening_status( user_id: int, include_quests: bool = False, db: AsyncSession = Depends(get_async_session) ) -> AwakeningStatusResponse: """ Get current awakening status for a user.
Args: user_id: ID of the user include_quests: Whether to include quest data in the response awakening_service: Awakening service (mock for development)
Returns: AwakeningStatusResponse with current session and progress
Raises: HTTPException: If user not found """ try: awakening_service = AwakeningService(db) # Get daily session for today today = date.today() session = await awakening_service.get_daily_session(user_id, today)
if not session: status_data = { "status": "pending", "awakened": False, "quests_available": False, "readiness_level": None, "quests": [], "active_session": None, } else: # Build status response status_data = { "status": session.status, "awakened": True, "quests_available": True, "readiness_level": session.tier_level, "quest_count": len(session.quests), "completed_quests": sum(1 for q in session.quests if q.status == "completed"), "total_xp_gained": sum(q.xp_reward for q in session.quests if q.status == "completed"), "session_theme": "Shadow Training", "active_session": { "user_id": session.user_id, "awakening_date": session.session_date.isoformat(), "readiness_level": session.tier_level, "status": session.status, "quest_count": len(session.quests), "completed_quests": sum(1 for q in session.quests if q.status == "completed"), "total_xp_gained": sum(q.xp_reward for q in session.quests if q.status == "completed"), "awakened_at": session.created_at.isoformat(), }, }
if include_quests: status_data["quests"] = [ { "id": q.id, "title": q.title, "description": q.description, "type": q.quest_type, "difficulty": q.difficulty, "tier": q.tier, "xp_reward": q.xp_reward, "status": q.status, "completed": q.status == "completed", "movement_name": q.movement_name, "target_reps": q.target_reps, "target_sets": q.target_sets, "progress": q.progress or {}, "completed_at": q.completed_at.isoformat() if q.completed_at else None, "created_at": q.created_at.isoformat() } for q in session.quests ]
return AwakeningStatusResponse(**status_data)
except Exception as e: logger.error(f"Error getting awakening status for user {user_id}: {e}") raise HTTPException( status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail="Failed to get awakening status" )
